window.__Q=window.__Q||{};window.__Q["tcm/5/A1"]=[{"q":"关于乳突小房叙述，下列错误的是","o":["位于颞骨乳突内","内衬黏膜","与鼓室的黏膜不连续","与乳突窦的黏膜相连续","中耳炎症可引起乳突小房炎症"],"a":2,"e":"乳突小房是颞骨乳突内的含气小腔，内衬黏膜，经乳突窦与鼓室相通，其黏膜与鼓室及乳突窦黏膜彼此延续；中耳炎症可经此蔓延引起乳突炎，故‘与鼓室黏膜不连续’一说错误。D项所述与乳突窦黏膜相连续正确，E项炎症蔓延亦属实；A项位于颞骨乳突内、B项内衬黏膜均为该结构的正常特征"},{"q":"循环系统的组成是","o":["心、血管、淋巴结","心、动脉、静脉、毛细血管","心、动脉、静脉、淋巴管","心血管系统和淋巴系统","心血管系统和免疫系统"],"a":3,"e":"循环系统由心血管系统和淋巴系统两大部分组成，前者包括心与血管，后者包括淋巴管、淋巴器官和淋巴组织，二者共同完成物质运输。A项将淋巴结与心、血管并列，混淆了器官与系统层次；B项所列心、动脉、静脉、毛细血管只是心血管系统的组成，遗漏淋巴系统；C项以淋巴管代替淋巴系统，且缺少毛细淋巴管与淋巴器官，均不完整。E项的免疫系统并非循环系统的子系统"},{"q":"开口高于窦底的鼻旁窦是","o":["额窦","蝶窦","筛窦的前、中小房","筛窦的后小房","上颌窦"],"a":4,"e":"上颌窦是最大的鼻旁窦，开口位于窦腔内侧壁最高处，明显高于窦底，分泌物不易引流，直立时易潴留，故为开口高于窦底者。额窦开口于中鼻道前部，筛窦前、中、后群分别开口于中、上鼻道，位置均低于窦底，引流相对顺畅；蝶窦开口于蝶筛隐窝。上颌窦底与上颌磨牙根毗邻，牙源性感染可波及窦腔，是其引流不畅的临床意义所在"},{"q":"属于后丘脑的结构是","o":["上丘","下丘","外侧膝状体","锥体","腹后核"],"a":2,"e":"后丘脑包括内侧膝状体和外侧膝状体，外侧膝状体为视觉传导通路的中继核，接受视束纤维并发出视辐射至视觉中枢，属于后丘脑。上丘、下丘位于中脑顶盖，是视觉、听觉反射中枢，不属后丘脑；锥体为延髓前部的下行纤维束；腹后核是丘脑本部核团，为感觉中继站，均不在后丘脑之列。内侧膝状体则与听觉传导有关，和外侧膝状体同属后丘脑"},{"q":"下列在体表不能摸到的结构是","o":["肩胛下窝","桡骨茎突","肱骨内上髁","桡骨头","尺骨鹰嘴"],"a":0,"e":"肩胛下窝位于肩胛骨前面，被肩胛下肌等软组织覆盖，位置深在，体表无法触及。桡骨茎突位于腕部桡侧皮下，肱骨内上髁在肘部内侧突出，尺骨鹰嘴构成肘尖，均浅表易扪；桡骨头在肘后外侧肱桡关节处亦可触及。这些骨性标志都是体表定位的重要依凭，而肩胛下窝需借助背部肌肉深面才能间接判断，不能作为体表标志"},{"q":"关于腹主动脉描述错误的是","o":["在主动脉裂孔处与胸主动脉相续","终于第4腰椎下缘平面","分支中有壁支和脏支两种","脏支较多，有成对脏支和单个脏支","分支中壁支全部成对"],"a":4,"e":"腹主动脉的壁支包括成对的膈下动脉、四对腰动脉，还有不成对的骶正中动脉，故‘壁支全部成对’的说法错误。脏支确有成对与不成对之分，成对的有肾上腺中动脉、肾动脉、睾丸或卵巢动脉，不成对的有腹腔干、肠系膜上、下动脉。腹主动脉在主动脉裂孔续接胸主动脉，至第4腰椎下缘分为左右髂总动脉而终，故其余各项描述均属实"},{"q":"躯体感觉中枢位于","o":["中央后回和中央旁小叶后部","中央前回和中央旁小叶前部","颞横回","额下回后部","角回"],"a":0,"e":"躯体感觉中枢位于中央后回和中央旁小叶后部，接受丘脑腹后核投射的躯干四肢意识性感觉纤维，身体各部在此呈倒置的人形投射，下肢代表区在中央旁小叶。中央前回和中央旁小叶前部为躯体运动中枢；颞横回是听觉中枢；额下回后部为运动性语言中枢；角回与阅读有关。这些中枢各司其职，与中央后回的感觉功能不可混淆"},{"q":"下列骨连结中属于直接连结的是","o":["椎间盘","肩关节","肘关节","髋关节","膝关节"],"a":0,"e":"椎间盘由纤维环和髓核构成，是相邻椎体间的纤维软骨连结，属直接连结，无关节腔，活动度小但稳固。肩关节、肘关节、髋关节、膝关节均具备关节面、关节囊和关节腔，为滑膜关节，属间接连结，活动范围大。直接连结还包括韧带连结和骨性结合，如棘间韧带、骶椎融合等；区分关键在于有无关节腔及能否活动，椎间盘显然属前者"},{"q":"关于咽，下列说法正确的是","o":["向下在第6颈椎下缘处续于气管","是上窄下宽的肌性管道","分为鼻咽、口咽和喉咽","后壁与咽鼓管圆枕之间有咽鼓管咽口","下鼻甲后方约1cm处有咽隐窝"],"a":2,"e":"咽是上宽下窄的肌性管道，自上而下分为鼻咽、口咽和喉咽三部，是消化道与呼吸道的共同通道。咽向下在第6颈椎下缘续于食管而非气管；其整体呈上宽下窄，并非上窄下宽；咽鼓管咽口位于鼻咽侧壁下鼻甲后方约1cm处，咽隐窝则在咽鼓管圆枕后上方，二者位置不同。掌握咽的分部及咽鼓管咽口、咽隐窝的毗邻，是理解鼻咽部病变的基础"},{"q":"损伤哪种脑神经后不能闭眼","o":["动眼神经","展神经","滑车神经","面神经","三叉神经"],"a":3,"e":"面神经支配眼轮匝肌，损伤后眼轮匝肌瘫痪，眼睑不能闭合，出现闭目障碍，并伴口角歪斜、额纹消失等面肌麻痹表现。动眼神经支配提上睑肌和眼球运动肌，损伤表现为上睑下垂、眼球运动障碍；展神经支配外直肌，损伤致眼球外展受限；滑车神经支配上斜肌；三叉神经主要司面部感觉和咀嚼肌运动，均不支配眼轮匝肌，故不会导致闭眼不能"},{"q":"关于腭扁桃体的描述，正确的是","o":["位于腭舌弓与腭咽弓之间","在鼻咽部的侧壁内","在舌根部的黏膜内","位于扁桃体上窝内","在喉咽部的侧壁内"],"a":0,"e":"腭扁桃体位于口咽部侧壁的扁桃体窝内，该窝处于腭舌弓与腭咽弓之间，是咽淋巴环的重要组成部分。鼻咽部侧壁有咽扁桃体和咽鼓管扁桃体，舌根部黏膜内有舌扁桃体，喉咽部并无扁桃体分布；扁桃体上窝是扁桃体上方的凹陷，并非腭扁桃体本身所在。明确各扁桃体的位置归属，有助于判断咽部炎症与肿瘤的好发部位"},{"q":"瞳孔位于","o":["虹膜的中央","角膜的边缘","脉络膜中央","视网膜中央","巩膜的中央"],"a":0,"e":"瞳孔是虹膜中央的圆孔，直径约2～5mm，光线经此进入眼内，其大小由虹膜内的瞳孔括约肌和开大肌调节。虹膜是血管膜的最前部，呈圆盘状，中央的孔即瞳孔；角膜是纤维膜前部透明结构，无中央孔；脉络膜、视网膜、巩膜位于眼球壁后部，均不在虹膜中央。瞳孔对光反射是眼科检查的重要指标，直接取决于虹膜肌的活动"},{"q":"有关直肠横襞的叙述，正确的是","o":["主要构成齿状线","是会阴曲和骶曲的分界线","位于直肠的右前壁","内有括约肌","是由环行肌和黏膜形成的半月状皱襞"],"a":4,"e":"直肠横襞是直肠腔内由黏膜和环行肌共同形成的半月形皱襞，通常有3条，以中直肠横襞最恒定，位于直肠右前壁，距肛门约7cm，是直肠镜检的定位标志。齿状线由肛柱下端与肛瓣边缘围成，并非横襞构成；直肠的骶曲、会阴曲是矢状面上的弯曲，与横襞无关；横襞内不含括约肌，肛门括约肌位于肛管周围"},{"q":"有关肝门静脉的说法，正确的是","o":["行于肝胃韧带内","由肠系膜上、下静脉合成","注入下腔静脉","肾静脉是其属支","两端均为毛细血管"],"a":4,"e":"肝门静脉起自腹腔消化管及脾等器官的毛细血管网，经肝门入肝后反复分支终于肝窦，肝窦再汇入肝静脉，故其两端均为毛细血管，是血管系统中的特殊结构。它行于肝十二指肠韧带内而非肝胃韧带；由肠系膜上静脉与脾静脉汇合而成，肠系膜下静脉多注入脾静脉；注入肝而非下腔静脉；肾静脉属下腔静脉系，不是其属支"},{"q":"食管的第二个狭窄位置是","o":["食管起始处","食管与胃相接处","食管与左主气管交叉处","距中切牙约40cm","食管穿膈处"],"a":2,"e":"食管第二狭窄位于食管与左主支气管交叉处，相当于第4、5胸椎之间，距中切牙约25cm，是异物易停留和食管癌的好发部位之一。食管起始处为第一狭窄，距中切牙约15cm；穿膈的食管裂孔处为第三狭窄，距中切牙约40cm；食管与胃相接处并非典型狭窄。三处狭窄中第二处因左主支气管跨越而受压，临床意义突出"},{"q":"位于延髓内的脑神经核是","o":["展神经核","面神经核","迷走神经背核","红核","薄束核"],"a":2,"e":"迷走神经背核位于延髓，属一般内脏运动核，发出副交感节前纤维支配胸腹腔脏器，是延髓内重要的脑神经核。展神经核、面神经核位于脑桥；红核位于中脑；薄束核虽在延髓，但传导本体觉，属非脑神经核，不支配任何骨骼肌或脏器。脑神经核按机能柱分布于脑干各段，辨明其所在平面是理解脑神经损伤定位的前提"},{"q":"关于肺动脉的描述，正确的是","o":["肺动脉中含的是动脉血","左肺动脉长，向左行至左肺门","右肺动脉向右经升主动脉与上腔静脉后方达右肺门","肺动脉全长包在心包内","在肺动脉分叉处的稍右侧有动脉韧带连于主动脉弓"],"a":2,"e":"肺动脉干起自右心室，含静脉血，在主动脉弓下方分为左右肺动脉；右肺动脉较长，向右经升主动脉和上腔静脉后方至右肺门，故该项描述正确。肺动脉含静脉血而非动脉血；左肺动脉较短，向左至左肺门；肺动脉仅根部包于心包内，并非全长；动脉韧带连于肺动脉分叉处稍左侧与主动脉弓之间，而非右侧"},{"q":"背阔肌的作用","o":["使肩关节旋外","只能使肩关节内收","使肩胛骨旋内","使肩关节后伸、内收和旋内","使肩关节后伸和旋外"],"a":3,"e":"背阔肌起自下位胸椎棘突、胸腰筋膜及髂嵴，止于肱骨小结节嵴，收缩时使肩关节后伸、内收和旋内，是引体向上时的主要动力肌。它不能使肩关节旋外，旋外主要由冈下肌、小圆肌完成；也非只能内收，尚参与后伸与旋内；其作用于肱骨而非肩胛骨，故不参与肩胛骨旋内；旋外与后伸并存的组合不符其实际功能"},{"q":"收集腹腔不成对脏器淋巴的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":0,"e":"肠干由腹腔淋巴结和肠系膜上、下淋巴结的输出管汇合而成，收集腹腔内不成对脏器如胃、肠、肝、胰、脾的淋巴，最终注入乳糜池。颈干收集头颈部淋巴，锁骨下干收集上肢及部分胸壁淋巴，支气管纵隔干收集胸部淋巴，三者均为成对淋巴干；腰干收集下肢、盆部及腹腔成对脏器的淋巴，也成对，均不负责腹腔不成对脏器"},{"q":"通过斜角肌间隙的是","o":["阴部内动脉","臀上动脉","旋肱后动脉","锁骨下动脉","股动脉"],"a":3,"e":"斜角肌间隙位于前斜角肌与中斜角肌之间，有锁骨下动脉和臂丛通过，是上肢血管神经的重要通道。阴部内动脉、臀上动脉均起自髂内动脉，分布于盆部及臀部；旋肱后动脉为腋神经伴行血管，经四边孔；股动脉是髂外动脉的延续，在股三角内。这些动脉走行均不涉及斜角肌间隙，唯锁骨下动脉经此隙续为腋动脉"},{"q":"下列关于脊髓丘脑侧束的描述，正确的是","o":["由同侧后角细胞轴突构成","由同侧脊神经节细胞的中枢突组成","传导对侧躯干、四肢的精细触觉","传导对侧躯干、四肢的痛温觉","传导对侧躯干、四肢触觉"],"a":3,"e":"脊髓丘脑侧束由脊髓后角细胞发出的纤维交叉至对侧后上行而成，传导对侧躯干和四肢的痛觉、温度觉。其第1级神经元在脊神经节，后角细胞为第2级，故不以同侧后角细胞轴突或脊神经节中枢突构成；精细触觉由薄束、楔束传导；躯干四肢的粗触觉主要由脊髓丘脑前束传导，侧束专司痛温觉，分工明确"},{"q":"关于胸膜，下列说法正确的是","o":["胸膜腔在男性完全封闭，女性间接通体外","可分胸膜顶、肋胸膜、膈胸膜三部分","胸膜腔最低点是肋膈隐窝","胸膜顶高出胸骨上端2～3cm","胸膜下界在腋中线与第8肋相交"],"a":2,"e":"肋膈隐窝位于肋胸膜与膈胸膜转折处，是胸膜腔的最低部位，胸腔积液首先积聚于此，也是胸膜腔穿刺的常用部位。胸膜腔在男女均完全封闭，不与外界相通；胸膜分胸膜顶、肋胸膜、膈胸膜和纵隔胸膜四部；胸膜顶高出锁骨内侧段上方2～3cm，而非胸骨；胸膜下界在腋中线与第10肋相交，第8肋为肺下界体表投影"},{"q":"下列哪项关于动脉触摸点的叙述是正确的","o":["颈总动脉触摸点在胸锁乳突肌后缘中点","足背动脉在活体上易触摸到搏动的部位是踝关节后方，内、外踝连线的中点","股动脉在活体上易触摸到的搏动部位是股动脉的上段","桡动脉在活体上诊脉的部位是桡动脉上段","锁骨下动脉触摸点在锁骨上小窝"],"a":2,"e":"股动脉在腹股沟韧带中点深面、股三角上部位置浅表，活体上易触及搏动，是临床采血和穿刺的常用部位，故该项叙述正确。颈总动脉触摸点应在胸锁乳突肌前缘；足背动脉在踝关节前方、内外踝连线中点可触及；桡动脉诊脉取腕部桡侧浅表处，属下段而非上段；锁骨下动脉在锁骨上大窝可触及，非锁骨上小窝"},{"q":"下列关于马尾描述正确的是","o":["由骶部脊神经后根形成","由下部脊神经前根形成","由下部几对脊神经形成","是在脊髓末端下行的脊神经根的总称","位于椎间孔内"],"a":3,"e":"脊髓末端约平第1腰椎下缘，其下方的椎管内，腰、骶、尾神经根在终丝周围下行，形似马尾，称为马尾，故它是下行脊神经根的总称。马尾并非仅由骶部后根或下部前根构成，而是包含腰骶尾各部的前后根；它由多对脊神经根组成，不限于‘几对’；马尾位于椎管内而非椎间孔，椎间孔内为脊神经干"},{"q":"分布在大脑皮质顶枕沟以前的半球内侧面的主要动脉是","o":["大脑前动脉","大脑中动脉","大脑后动脉","椎动脉","基底动脉"],"a":0,"e":"大脑前动脉发自颈内动脉，沿大脑半球内侧面前行，主要分布于顶枕沟以前的半球内侧面及额叶底面，故为该区域的主要供血动脉。大脑中动脉主要分布于大脑半球外侧面；大脑后动脉分布于半球后部及下面，包括顶枕沟以后的内侧面；椎动脉、基底动脉主要供应脑干、小脑，并参与大脑动脉环的构成，均不负责该区"},{"q":"关于尺骨形态的描述，何者错误","o":["属长骨","有尺切迹","有鹰嘴","下端无腕关节面","有滑车切迹"],"a":1,"e":"尺骨上端有鹰嘴、冠突和滑车切迹，下端为尺骨头，其外侧的桡切迹位于尺骨上端而非尺骨，尺切迹实为桡骨下端与尺骨头相关节的结构，故‘尺骨有尺切迹’错误。尺骨属长骨，鹰嘴构成肘尖，滑车切迹与肱骨滑车相关节，均为其正常形态；尺骨下端不直接参与腕关节，故无腕关节面，此项描述正确"},{"q":"大脑后动脉发自","o":["基底动脉","椎动脉","颈内动脉","颈外动脉","颈总动脉"],"a":0,"e":"大脑后动脉是基底动脉的终支，基底动脉由左右椎动脉在脑桥下缘汇合而成，沿基底沟上行至脑桥上缘分为左右大脑后动脉，主要分布于大脑半球后部。椎动脉发出小脑后下动脉等分支，不直接续为大脑后动脉；颈内动脉主要发出大脑前、中动脉；颈外动脉分布于头颈部颅外结构；颈总动脉分为颈内、外动脉，均非其来源"},{"q":"支配比目鱼肌的神经是","o":["闭孔神经","胫神经","腓浅神经","腓深神经","股神经"],"a":1,"e":"比目鱼肌与腓肠肌共同构成小腿三头肌，由胫神经支配，收缩时提跟骨使足跖屈，是站立与行走的重要动力肌。闭孔神经支配大腿内收肌群；腓浅神经支配腓骨长、短肌；腓深神经支配胫骨前肌等小腿前群肌；股神经支配股四头肌等大腿前群肌。各神经支配的肌群界限分明，小腿后群及足底肌均由胫神经统一管理"},{"q":"女性生殖腺是","o":["卵巢","输卵管","子宫","阴道","前庭大腺"],"a":0,"e":"卵巢是女性的生殖腺，能产生卵细胞并分泌雌激素和孕激素，兼具生殖与内分泌双重功能。输卵管是输送卵细胞及受精的部位，属生殖管道；子宫是孕育胎儿的器官；阴道为月经排出和胎儿娩出的通道；前庭大腺是位于阴道口两侧的外分泌腺，分泌黏液润滑阴道前庭，均非生殖腺。生殖腺的核心在于产生生殖细胞并分泌性激素"},{"q":"下列关于男性尿道的描述，正确的是","o":["分为前列腺部、膜部和海绵体部","全长粗细均匀一致","膜部有射精管开口","耻骨前弯是恒定弯曲","全长有三个弯曲"],"a":0,"e":"男性尿道以尿生殖膈为界分为前列腺部、膜部和海绵体部三部，其中前列腺部有射精管和前列腺导管开口，是尿道最宽的一段。尿道全长有三处狭窄和三个膨大，粗细不均；射精管开口于前列腺部而非膜部；耻骨前弯是上提阴茎即可消失的可变弯曲，耻骨下弯才恒定；尿道仅有两个弯曲，而非三个"},{"q":"脑神经有多少对","o":["10","11","12","13","14"],"a":2,"e":"脑神经共12对，依序为嗅、视、动眼、滑车、三叉、展、面、前庭蜗、舌咽、迷走、副、舌下神经，除嗅神经连于端脑、视神经连于间脑外，其余均连于脑干。10对、11对、13对、14对等说法均不符合人体解剖学的固定数目。记忆脑神经的数目与顺序是理解其连脑部位、出颅孔道及功能分类的基础，务必准确"},{"q":"中央有视网膜中央血管穿过的结构是","o":["黄斑","中央凹","脉络膜","视神经盘","巩膜"],"a":3,"e":"视神经盘是视网膜后部偏鼻侧的圆盘状隆起，为视神经纤维汇集穿出眼球壁之处，视网膜中央动、静脉由此穿入并分布于视网膜，此处无视细胞，故为生理性盲点。黄斑及其中心的中央凹是视力最敏锐处，无血管穿过；脉络膜、巩膜位于眼球壁外层；视神经盘与黄斑在眼底检查中位置、色泽迥异，是辨识眼底的重要标志"},{"q":"左侧三叉丘系传导的感觉信息主要是","o":["左侧躯干、四肢意识性浅感觉","右侧躯干、四肢意识性浅感觉","左侧头面部意识性浅感觉","右侧头面部意识性浅感觉","双侧头面、躯干、四肢意识性浅感觉"],"a":3,"e":"三叉丘系由三叉神经感觉核发出的纤维交叉至对侧上行而成，终止于丘脑腹后内侧核，传导头面部意识性浅感觉；左侧三叉丘系因此传导右侧头面部的痛温觉和触觉。躯干四肢的意识性浅感觉由脊髓丘脑束传导，不经过三叉丘系；感觉纤维在脑干交叉后即改为对侧传导，故非左侧头面部，也非双侧支配"},{"q":"关于内分泌系统的描述，错误的是","o":["内分泌系统由内分泌器官组成","所有的内分泌腺都没有排泄导管","不同的内分泌腺分泌不同的激素","内分泌激素经血液循环运送到全身","内分泌腺接受神经系统的调节，也可影响神经系统的功能"],"a":0,"e":"内分泌系统由内分泌腺和分布于其他器官内的内分泌细胞共同组成，仅说由内分泌器官组成并不全面，故该项错误。内分泌腺无导管，又称无管腺，其分泌物即激素直接释放入血，随循环运送到全身靶器官；不同内分泌腺分泌各自的特异性激素；内分泌腺受神经系统调控，又能反过来影响神经功能，构成神经-内分泌调节网络"},{"q":"有关肋间外肌的说法，错误的是","o":["位于各肋间隙的浅层","起自肋骨下缘","受肋间神经支配","提肋，协助吸气","止于下一肋骨上缘"],"a":1,"e":"肋间外肌位于各肋间隙浅层，起自上位肋骨的下缘，纤维斜向前下方，止于下位肋骨的上缘，收缩时提肋助吸气，受肋间神经支配；笼统言‘起自肋骨下缘’未指明上位肋，表述不准确。细究之，起止点的上下位关系是关键：肋间内肌起自下位肋上缘、止于上位肋下缘，用力呼气时降肋，与外肌作用相反，二者不可混淆"},{"q":"隐神经发自","o":["股神经","闭孔神经","正中神经","坐骨神经","阴部神经"],"a":0,"e":"隐神经是股神经的终支，伴大隐静脉下行于小腿内侧，分布于膝、小腿内侧及足内侧缘的皮肤，是全身最长的皮神经。闭孔神经主要支配大腿内收肌及大腿内侧皮肤；正中神经、尺神经、桡神经均为臂丛分支，分布于上肢；阴部神经来自骶丛，分布于会阴部。隐神经属的感觉纤维来源单一，追踪其发源即可锁定股神经"},{"q":"下列器官，何者属于内分泌腺","o":["垂体","卵巢","胰腺","睾丸","前列腺"],"a":0,"e":"垂体是典型的内分泌腺，位于蝶骨垂体窝内，前叶分泌生长激素、促甲状腺激素等多种激素，后叶释放抗利尿激素和催产素，是内分泌系统的中枢。卵巢、睾丸虽分泌性激素，但其主要功能是产生生殖细胞，归为生殖腺；胰腺以外分泌为主，仅胰岛属内分泌部分，为混合腺；前列腺是外分泌腺，分泌前列腺液。故纯内分泌腺首推垂体"},{"q":"左侧内囊膝病变时，最有可能出现","o":["左侧面神经核上瘫","右侧面神经核上瘫","左侧面神经核下瘫","右侧面神经核下瘫","双侧下半部面瘫"],"a":1,"e":"内囊膝有皮质核束通过，支配脑神经运动核，其中至面神经核上部的纤维支配对侧眼裂以下面肌。左侧内囊膝病变损伤未交叉的皮质核束，导致右侧面神经核上瘫，表现为右侧鼻唇沟变浅、口角下垂，而额肌、眼轮匝肌功能保存。核上瘫为对侧中枢性瘫痪，仅累及下部面肌；核下瘫是同侧周围性面瘫，累及全部面肌，二者机制不同"},{"q":"关于肺的说法，错误的是","o":["肺底又称膈面","外侧面又称肋面","右肺分为上、中、下三叶","左肺前缘有心切迹","肺动脉、肺静脉、淋巴管和神经组成肺根"],"a":4,"e":"肺根由主支气管、肺动脉、肺静脉、淋巴管和神经等结构被结缔组织包绕而成，将肺连于纵隔，该项列举遗漏了主支气管这一核心成分，故错误。肺底贴膈又称膈面，外侧面贴肋称肋面，均为正确描述；右肺分上、中、下三叶，左肺因心切迹分上、下二叶，心切迹位于左肺前缘。肺根成分的完整性是理解肺门结构的关键"},{"q":"上鼻甲后上方与蝶骨体之间的凹陷为","o":["上颌窦","上鼻道","蝶筛隐窝","垂体窝","咽隐窝"],"a":2,"e":"蝶筛隐窝位于上鼻甲后上方与蝶骨体之间，是蝶窦的开口所在，位置隐蔽，鼻咽部感染或蝶窦病变常累及此区。上颌窦开口于中鼻道，位置较低；上鼻道是筛窦后小房的开口处，为通道而非隐窝；垂体窝在蝶骨体上面，容纳垂体，属颅腔结构；咽隐窝在鼻咽部咽鼓管圆枕后方，与鼻甲、蝶骨体无直接毗邻"},{"q":"视觉中枢位于","o":["中央后回和中央旁小叶后部","中央前回和中央旁小叶前部","颞横回","额下回后部","距状沟上、下皮质"],"a":4,"e":"视觉中枢位于大脑半球内侧面的距状沟上、下皮质，即纹状区，接受外侧膝状体发出的视辐射纤维，是视觉信息的最高级中枢。中央后回及中央旁小叶后部为躯体感觉中枢；中央前回及中央旁小叶前部为躯体运动中枢；颞横回为听觉中枢；额下回后部为运动性语言中枢。距状沟皮质损伤可致偏盲，定位意义明确"},{"q":"下列结构属于躯体感觉核的是","o":["面神经核","舌下神经","三叉神经脑桥核","迷走神经背核","展神经核"],"a":2,"e":"三叉神经脑桥核又称三叉神经感觉主核，位于脑桥，接受头面部触觉纤维，属一般躯体感觉核。面神经核、舌下神经核、展神经核均为躯体运动核，支配相应肌肉；迷走神经背核为一般内脏运动核，属副交感性质。脑神经核按感觉、运动及内脏机能分柱排列，三叉神经脑桥核以其感觉属性区别于上述运动性核团"},{"q":"下列关于薄束和楔束的描述，正确的是","o":["楔束起自第4胸髓节段以下的脊神经节细胞","薄束起自第5胸髓节段以上的脊神经节细胞","传导同侧的本体觉和精细触觉","终于脊髓板层Ⅰ～Ⅴ","贯穿脊髓全长"],"a":2,"e":"薄束和楔束位于脊髓后索，传导同侧躯干四肢的意识性本体觉和精细触觉，纤维在脊髓不交叉，至延髓的薄束核、楔束核才换元交叉。楔束起自第4胸髓节段以上的脊神经节细胞，薄束起自第5胸髓节段以下，二者界限以胸4为界；它们终于薄束核、楔束核而非脊髓板层Ⅰ～Ⅴ；楔束仅见于胸4以上，并非贯穿脊髓全长"},{"q":"下列关于骨盆的叙述中，正确的是","o":["由髋骨借关节等连结构成","可分为大、小骨盆","大骨盆的内腔称骨盆腔","男性骨盆腔呈圆桶状","女性耻骨下角为锐角"],"a":1,"e":"骨盆以骶岬、弓状线、耻骨梳等围成的界线为界，分为上方的大骨盆和下方的小骨盆，故该项分类正确。骨盆由左右髋骨、骶骨、尾骨及其间的关节韧带共同构成，遗漏骶尾骨即不全面；小骨盆的内腔才称骨盆腔，大骨盆内腔属腹腔一部分；男性骨盆腔呈漏斗状，女性呈圆桶状；女性耻骨下角为钝角，男性为锐角"},{"q":"位于肾窦内的结构","o":["肾柱","肾小盏","肾锥体","肾纤维囊","肾门"],"a":1,"e":"肾小盏包绕肾乳头，接受乳头排出的尿液，与肾大盏、肾盂、肾血管分支及神经、淋巴管等共同位于肾窦内，肾窦是肾门向内扩大的腔隙。肾柱是皮质伸入髓质之间的部分，肾锥体属髓质，二者均为肾实质；肾纤维囊是紧贴肾表面的被膜；肾门是肾内侧缘的凹陷，为血管神经出入处，均不在肾窦之内"},{"q":"颞浅动脉的描述何者有误","o":["是颈内动脉的终支之一","是颈外动脉的终支之一","经过外耳门的前方","颧弓根部前方可压迫止血","主要分布至颞区"],"a":0,"e":"颞浅动脉是颈外动脉的终支之一，而非颈内动脉，故该项错误。它经外耳门前方上行，越过颧弓根部时位置浅表，可在该处压迫止血，主要分布于额、颞部皮肤。颈内动脉经颈动脉管入颅，主要分支为眼动脉、大脑前动脉、大脑中动脉等，不分布于颅外颞区；颈外动脉的另一终支为上颌动脉，分布于面深部及硬脑膜"},{"q":"副交感神经的低级中枢不包括","o":["动眼神经副核","脊髓骶部第2～4节段灰质的骶副交感核","迷走神经背核","上泌涎核","脊髓腰部第1～3节段灰质的侧角"],"a":4,"e":"副交感神经低级中枢位于脑干和脊髓骶部，包括动眼神经副核、上泌涎核、下泌涎核、迷走神经背核及脊髓骶2～4节段的骶副交感核。脊髓腰1～3节段灰质侧角是交感神经低级中枢，发出交感节前纤维，不属于副交感系统。交感中枢位于胸腰段，副交感中枢位于脑干和骶段，二者在中枢部位上呈首尾分布，是记忆的关键"},{"q":"关于肌的起止和作用，下列描述正确的是","o":["四肢肌多起于肢体远端","躯干肌多起于远离正中线的部位","肌在移动骨上的附着点称止点或定点","肌的起止点在一定条件下可以互换","肌在固定骨上的附着点称起点或动点"],"a":3,"e":"肌的起点与止点、定点与动点并非绝对，当运动形式改变、固定骨与移动骨互换时，起止点可相互转化，如引体向上与俯卧撑时同一肌的作用点不同。四肢肌多起于肢体近端、止于远端；躯干肌多起于靠近正中线的部位；肌在固定骨上的附着点称起点或定点，在移动骨上的附着点称止点或动点，两项恰好颠倒"},{"q":"颈内静脉汇入下列何静脉","o":["颈总静脉","头臂静脉","颈外静脉","腋静脉","锁骨下静脉"],"a":1,"e":"颈内静脉与锁骨下静脉在胸锁关节后方汇合成头臂静脉，左右头臂静脉再合成上腔静脉，收集头颈、上肢及胸部的静脉血。颈总静脉并非解剖学标准血管名称；颈外静脉是颈部浅静脉，注入锁骨下静脉；腋静脉是上肢深静脉，续接肱静脉；锁骨下静脉与颈内静脉同为头臂静脉的属支，二者汇合而非互相汇入"},{"q":"右淋巴导管注入部位是","o":["左静脉角","右静脉角","左颈前静脉","右颈前静脉","左锁骨下静脉"],"a":1,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，收集右上半身的淋巴，注入右静脉角，即右颈内静脉与右锁骨下静脉的汇合处。左静脉角是胸导管注入处，收集全身约四分之三区域的淋巴；颈前静脉、左锁骨下静脉均非其注入部位。左右淋巴导管引流范围与注入静脉角的左右对应，是理解淋巴回流的关键"},{"q":"关于肾上腺的描述，错误的是","o":["位于腹膜后方","左肾上腺近似半月形","分皮质和髓质两部分","与肾共同包在肾纤维囊内","分泌的激素可参与调节体内水盐代谢"],"a":3,"e":"肾上腺与肾共同包在肾筋膜内，但二者各有独立的纤维囊，肾上腺并不与肾共同包在肾纤维囊内，故该项错误。肾上腺位于腹膜后隙，左肾上腺近似半月形、右肾上腺呈三角形，实质分皮质和髓质两层：皮质分泌醛固酮、皮质醇等，参与水盐代谢和糖代谢调节，髓质分泌肾上腺素和去甲肾上腺素"},{"q":"不成对的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":0,"e":"人体九条淋巴干中，肠干由腹腔淋巴结的输出管汇成，收集腹腔不成对脏器的淋巴，是唯一不成对的淋巴干，注入乳糜池。颈干、锁骨下干、支气管纵隔干、腰干均为左右成对的淋巴干，分别收集头颈、上肢、胸部和下肢及腹腔成对脏器的淋巴。淋巴干的成对与否取决于其引流区域是否左右对称，肠干因腹腔脏器不成对而单一"},{"q":"舌下神经出脑时，其内侧紧邻","o":["下丘","大脑脚","基底沟","橄榄","锥体"],"a":4,"e":"舌下神经根丝自延髓前外侧沟出脑，其内侧紧邻锥体，外侧为橄榄，是延髓腹侧面重要的神经根标志。下丘位于中脑背侧，与听觉有关；大脑脚在中脑腹侧；基底沟在脑桥腹侧正中，容纳基底动脉；橄榄在舌下神经根外侧。延髓腹侧面由内向外依次为锥体、舌下神经根、橄榄，掌握此排列有助于辨认脑神经出入脑的部位"},{"q":"连结上肢与躯干的关节","o":["肩锁关节","肩关节","胸锁关节","胸肋关节","肋椎关节"],"a":2,"e":"胸锁关节由锁骨内侧端与胸骨柄的锁切迹及第1肋软骨构成，是上肢骨与躯干骨之间唯一的关节连结，上肢借此附着于躯干。肩锁关节连接锁骨与肩胛骨，属上肢骨之间的连结；肩关节是肱骨与肩胛骨的连结；胸肋关节、肋椎关节为肋骨与胸骨、胸椎的连结，均不构成上肢与躯干之间的连接。故胸锁关节是上肢与躯干的唯一骨性联系"},{"q":"属于下丘脑的神经核是","o":["视上核","齿状核","下橄榄核","腹后核","杏仁体"],"a":0,"e":"视上核位于下丘脑，其神经元合成抗利尿激素，经轴突运输至神经垂体释放，是下丘脑重要的神经核。齿状核位于小脑半球深部，属小脑核；下橄榄核在延髓；腹后核是丘脑的感觉中继核；杏仁体位于端脑颞叶深部，属边缘系统。这些核团分别位于小脑、脑干、间脑和端脑的不同平面，唯有视上核归属下丘脑"},{"q":"以下对三叉神经的描述，正确的是","o":["为第Ⅵ对脑神经","三条分支均含有运动纤维","三个分支均经眶上裂出颅","运动纤维支配表情肌","为混合性脑神经"],"a":4,"e":"三叉神经是第Ⅴ对脑神经，含一般躯体感觉和特殊内脏运动两种纤维，属混合性神经，感觉纤维司头面部感觉，运动纤维支配咀嚼肌。第Ⅵ对为展神经，并非三叉神经；三支中仅下颌神经含运动纤维，眼、上颌神经为纯感觉；三支分别经眶上裂、圆孔、卵圆孔出颅；表情肌由面神经支配，三叉神经运动支只管咀嚼肌"},{"q":"位于中脑的结构是","o":["锥体交叉","薄束结节","基底沟","橄榄","大脑脚"],"a":4,"e":"大脑脚位于中脑腹侧，由大脑脚底、黑质和被盖组成，是锥体束等下行纤维的通路，属中脑典型结构。锥体交叉位于延髓与脊髓交界处；薄束结节在延髓背侧，深面为薄束核；基底沟位于脑桥腹侧正中，有基底动脉走行；橄榄是延髓腹外侧的隆起。中脑背侧为四叠体，腹侧为大脑脚，据此可与其他脑干平面区分"},{"q":"关于肝门静脉，下列说法正确的是","o":["收集胃、肠、肝等不成对脏器的血液","行于肝镰状韧带内","注入下腔静脉","经肝门入肝","由肠系膜上、下静脉汇合成"],"a":3,"e":"肝门静脉由肠系膜上静脉和脾静脉在胰颈后方汇合而成，经肝十二指肠韧带上行至肝门入肝，在肝内反复分支终于肝窦。它收集胃、肠、脾、胰、胆囊等不成对脏器的血液，但肝本身并非其收集对象；它行于肝十二指肠韧带而非肝镰状韧带内；其血液入肝毛细血管，不直接注入下腔静脉。经肝门入肝是其在肝门区的重要行程特点"},{"q":"下颌窝是哪块骨上的结构","o":["下颌骨","蝶骨","颞骨","上颌骨","颧骨"],"a":2,"e":"下颌窝位于颞骨鳞部下面、外耳道前方，与下颌骨下颌头构成颞下颌关节，其前方的关节结节参与关节构成。下颌骨本身有下颌头、下颌角、下颌孔等结构，但不构成下颌窝；蝶骨位于颅底中部，有蝶鞍、卵圆孔、棘孔；上颌骨构成上颌窦和硬腭前部；颧骨构成颧弓的一部分。下颌窝归属颞骨，是颅骨辨认的常考点"},{"q":"以下对上颌神经的描述，正确的是","o":["通过圆孔","延续为眶上神经","支配颞肌","分布于口裂以下的皮肤","为混合性神经"],"a":0,"e":"上颌神经是三叉神经第二支，为纯感觉性神经，经圆孔出颅，分布于眼裂与口裂之间的皮肤及上颌牙、鼻腔、口腔黏膜等。眶上神经是眼神经的分支，经眶上切迹出眶；颞肌由下颌神经的咬肌神经支配，不属上颌神经；口裂以下皮肤由下颌神经支配；上颌神经不含运动纤维，故非混合性神经。圆孔是其出颅的标志性孔道"},{"q":"占眼球纤维膜前1/6的结构是","o":["角膜","巩膜","虹膜","脉络膜","视网膜"],"a":0,"e":"眼球纤维膜由致密结缔组织构成，前1/6为角膜，透明无血管，富有神经末梢，是光线进入眼球的第一道屈光结构；后5/6为巩膜，不透明，起保护和支持作用。虹膜、脉络膜属血管膜，分别位于血管膜的前部和后部；视网膜属内膜，含感光细胞。角膜与巩膜在角膜缘移行，前1/6与后5/6的比例是区分二者的关键"},{"q":"关于腹直肌的描述，正确的是","o":["起自剑突和附近肋软骨的前面","腱划与腹直肌鞘后层紧密相连","全长被腱划分成若干个肌腹","后面全部被腹直肌鞘包裹","收缩时，可使脊柱后伸"],"a":2,"e":"腹直肌纵列于腹前壁正中线两侧，被3～4条腱划分成多个肌腹，腱划与腹直肌鞘前层紧密结合，是其形态特征。腹直肌起自耻骨联合和耻骨嵴，止于剑突及第5～7肋软骨前面，起止被颠倒；腱划与鞘前层相连而非后层；鞘后层在脐以下缺如，故后面并非全部被包裹；收缩时使脊柱前屈并增加腹压，不使脊柱后伸"},{"q":"关于肝的描述，正确的是","o":["主要位于右季肋区和左季肋区","主要位于左季肋区和腹上区","大部分位于腹上区和左侧季肋区","大部分被肋弓所覆盖","剑突下触摸不到肝"],"a":3,"e":"肝大部分位于右季肋区和腹上区，小部分延至左季肋区，成人肝上界与膈穹隆一致，下界大部被右侧肋弓掩盖，仅剑突下有小部分露出，可在深吸气时触及，故‘大部分被肋弓覆盖’正确。肝主要位于右季肋区而非左季肋区；说大部分在腹上区和左季肋区均与事实不符；剑突下可触及肝下缘。肝区叩诊与触诊常据此定位"},{"q":"前交通动脉连接","o":["颈内动脉与大脑前动脉","颈内动脉与大脑中动脉","两侧大脑前动脉","两侧颈内动脉","两侧大脑中动脉"],"a":2,"e":"前交通动脉位于视交叉前方，连接左右大脑前动脉，是大脑动脉环前部的重要组成部分，参与调节两侧大脑半球的血液供应。颈内动脉与大脑前动脉、大脑中动脉的连续属于同一侧的延续关系，并非前交通动脉所连接；两侧颈内动脉之间、两侧大脑中动脉之间均无前交通动脉直接相连。后交通动脉则连接颈内动脉与大脑后动脉，与前交通动脉不可混淆"},{"q":"占眼球血管膜后2/3的结构是","o":["虹膜","角膜","睫状体","脉络膜","脉络丛"],"a":3,"e":"眼球血管膜由前向后分为虹膜、睫状体和脉络膜，其中脉络膜占血管膜的后2/3，富含血管和色素，有营养视网膜外层和遮光作用。虹膜位于最前部，呈圆盘状，中央有瞳孔；睫状体为中部增厚部分，含睫状肌，参与调节晶状体曲度；角膜属纤维膜；脉络丛是脑室内的结构，位于脑内而非眼球，与脉络膜名近而实异"},{"q":"齿状线","o":["是肛门内、外括约肌的分界线","肛柱下端与肛瓣边缘的环形线","临床上称为痔环","又称为肛直肠线","肛柱上端的环形线"],"a":1,"e":"齿状线又称梳状线，由各肛柱下端与相邻肛瓣边缘共同围成，呈锯齿状环行，是肛管皮肤与直肠黏膜的分界，也是内、外痔的好发分界标志。肛门内、外括约肌的分界在肛管下段，并非齿状线；齿状线附近称痔环的说法不严谨；肛直肠线是直肠与肛管的移行线，位于齿状线之上；肛柱上端的环线为直肠肛管交界，均非齿状线"},{"q":"关于甲状腺的描述，正确的是","o":["分泌甲状腺素和降钙素","呑咽时，可随喉上、下移动","形态为“C”型，分左右二叶","锥状叶常由左叶或右叶向上伸出","左、右叶后外侧有颈内动脉、颈内静脉、膈神经通过"],"a":1,"e":"甲状腺借甲状腺悬韧带固定于喉软骨，吞咽时随喉上下移动，此特征是临床触诊甲状腺及鉴别颈部肿块的重要依据。甲状腺滤泡分泌甲状腺素，滤泡旁细胞分泌降钙素；其形态呈‘H’形或蝶形，分左右两叶和峡部，并非‘C’形；锥状叶多自左叶向上伸出；左右叶后外侧邻接颈总动脉、颈内静脉和喉返神经，膈神经并不由此通过"},{"q":"关于面动脉的描述何者有误","o":["经咬肌前缘和下颌底相交处进入面部","向上行经口角的外侧","至内眦处更名为内眦动脉","其后方有面静脉伴行","双侧面动脉间无吻合"],"a":4,"e":"面动脉在面部走行中分支丰富，与上、下唇动脉等与对侧同名动脉存在广泛吻合，故‘双侧面动脉间无吻合’的说法错误。面动脉经咬肌前缘与下颌骨下缘相交处转入面部，向上经口角外侧至内眦处改称内眦动脉，其后方有面静脉伴行，主要分布于面部皮肤和表情肌。面部血供的丰富吻合是面部感染易扩散和止血须压迫双侧的原因"},{"q":"发自臂丛外侧束的神经为","o":["腋神经","胸背神经","肌皮神经","尺神经","桡神经"],"a":2,"e":"肌皮神经发自臂丛外侧束，穿过喙肱肌后沿肱二头肌深面下行，支配上臂前群肌，其终支为前臂外侧皮神经，分布于前臂桡侧皮肤。腋神经发自后束，支配三角肌和小圆肌；胸背神经发自后束，支配背阔肌；尺神经发自内侧束；桡神经是后束的延续。臂丛各束发出神经的归属是上肢神经损伤定位的基础"},{"q":"关于肝下界的描述，正确的是","o":["在右腋中线起自第10肋","在左腋中线起自第10肋","在右侧第7、8肋软骨结合处离开右肋弓","在左肋弓第8、9肋软骨结合处进入左季肋区","在剑突下触摸不到肝"],"a":0,"e":"肝下界在右腋中线与第10肋相交，由此向左沿右肋弓下缘前行，至剑突下再转向左，构成肝的体表投影，故该描述正确。左腋中线处肝下界约在第9肋，而非第10肋；肝下界在右第8、9肋软骨结合处离开右肋弓，并非第7、8肋；左侧约在第7、8肋软骨结合处转入左季肋区；成人剑突下常可触及肝下缘"},{"q":"关于肘正中静脉的叙述正确的是","o":["起于手背静脉网","直接汇入肱静脉","属于深静脉","属于浅静脉","连接桡静脉和尺静脉"],"a":3,"e":"肘正中静脉位于肘窝皮下，属上肢浅静脉，连接头静脉与贵要静脉，是临床静脉穿刺和采血的常用部位，故该项正确。它起自头静脉，斜向内上注入贵要静脉，并非起于手背静脉网；贵要静脉、头静脉最终注入腋静脉或肱静脉，肘正中静脉不直接汇入肱静脉；连接桡、尺静脉的是前臂深静脉的伴行血管，与肘正中静脉无关"},{"q":"以下有关颞下颌关节的叙述，正确的是","o":["由下颌骨下颌头与颞骨下颌窝构成","关节内有关节盘","关节囊紧张坚韧","仅能做开口、闭口运动","容易发生后脱位"],"a":1,"e":"颞下颌关节腔内有一块纤维软骨关节盘，介于下颌头与关节窝之间，将关节腔分为上、下两部，增加关节的适配性和运动形式，故该项正确。该关节由下颌头与颞骨的下颌窝及关节结节共同构成，遗漏关节结节即不全面；关节囊较松弛，而非紧张坚韧；它可作多种运动，非仅开口闭口；常见的是前脱位，而非后脱位"},{"q":"静脉角由下列哪两支静脉汇合而成","o":["颈内静脉、颈外静脉","左、右头臂静脉","锁骨下静脉与颈内静脉","锁骨下静脉与颈外静脉","锁骨下静脉与颈总静脉"],"a":2,"e":"静脉角由同侧的颈内静脉与锁骨下静脉在胸锁关节后方汇合而成，是淋巴导管注入静脉的部位，左静脉角接纳胸导管，右静脉角接纳右淋巴导管。颈内静脉与颈外静脉同为颈部静脉，二者不相汇成静脉角；左右头臂静脉由上腔静脉收集，并非静脉角的构成；锁骨下静脉与颈外静脉或颈总静脉的组合均不符解剖事实"},{"q":"完成拇指对掌运动的主要关节是","o":["桡腕关节","腕骨间关节","第1掌指关节","掌骨间关节","拇指腕掌关节"],"a":4,"e":"拇指腕掌关节由第1掌骨底与大多角骨构成，为鞍状关节，可作屈、伸、收、展、旋转及对掌运动，拇指指腹能与其余四指指腹相对即主要完成于此关节。桡腕关节司腕的屈伸和尺桡偏；腕骨间关节、掌骨间关节活动度小，主要起稳定作用；第1掌指关节主要参与拇指的屈伸和对掌的辅助，并非对掌运动的主要关节"},{"q":"关于阑尾，下列说法正确的是","o":["结肠带是寻找阑尾的标志","是腹膜间位器官","以回肠后位多见","由腹腔干供血","没有系膜"],"a":0,"e":"结肠带是结肠纵行肌增厚形成的三条带状结构，均汇集于阑尾根部，手术中沿结肠带向下追踪是寻找阑尾的可靠标志，故该项正确。阑尾是腹膜内位器官，有阑尾系膜，并非间位或无系膜；其常见位置为回盲部后位或盆位，回肠后位并非最多见；阑尾动脉来自回结肠动脉，属肠系膜上动脉系，与腹腔干无关"},{"q":"淋巴导管注入部位是","o":["静脉角","胸骨角","脊肋角","下颌角","下腔静脉"],"a":0,"e":"全身淋巴导管只有胸导管和右淋巴导管两条，分别注入左、右静脉角，即颈内静脉与锁骨下静脉的汇合处，淋巴由此回归血液循环。胸骨角是胸骨柄与体的连接处，为计数肋的标志；脊肋角是肾脏病变的压痛点；下颌角为下颌骨下缘的转折；下腔静脉收集下半身静脉血，均非淋巴导管的注入部位"},{"q":"有关心尖的描述，正确的是","o":["朝向左后下方","由左心房构成","由左心室构成","由左心房和左心室构成","位于左侧第5肋间隙与左侧锁骨中线相交处"],"a":2,"e":"心尖由左心室构成，是心尖搏动的产生部位，朝向左侧前下方，位于左侧第5肋间隙、锁骨中线内侧约1～2cm处，体表可触及搏动。心尖并非朝向左后下方；左心房构成心底后部，不参与心尖；心尖也不是由左心房与左心室共同构成；其位置在锁骨中线内侧而非恰在锁骨中线上，故定位不准确"},{"q":"关于脊髓灰质的描述，错误的是","o":["板层Ⅷ～Ⅸ位于前角","板层Ⅰ～Ⅳ相当于后角","板层Ⅴ～Ⅶ居中间带","由神经元突起和神经胶质组成","板层Ⅹ位于中央管周围"],"a":3,"e":"脊髓灰质是神经元胞体及其树突、轴突和神经胶质细胞聚集之处，中央管周围呈‘H’形，说它仅由神经元突起和神经胶质组成而遗漏胞体，故该项错误。按Rexed板层划分，板层Ⅰ～Ⅳ相当于后角，Ⅴ～Ⅶ居中间带，Ⅷ、Ⅸ位于前角，Ⅹ围绕中央管，各项对应均正确。灰质是反射活动的中枢部位，白质则由上下行纤维束构成"},{"q":"食管腹段的动脉供应来自","o":["胃左动脉","胃右动脉","胃网膜左动脉","胃网膜右动脉","胃短动脉"],"a":0,"e":"食管腹段很短，位于膈食管裂孔以下至贲门之间，其动脉供应主要来自胃左动脉的食管支，静脉则汇入胃左静脉，故该项正确。胃右动脉沿胃小弯右行，主要供应胃小弯右侧；胃网膜左、右动脉分别沿胃大弯走在胃结肠韧带内，供应胃大弯及大网膜；胃短动脉供应胃底，均不负责食管腹段的血液供应"},{"q":"关于鼓膜的描述，下列错误的是","o":["位于外耳道与鼓室之间","构成鼓室外侧壁的大部分","婴儿鼓膜更为倾斜，几乎呈水平位","鼓膜边缘附着在颞骨鼓部和鳞部，鼓膜周缘较厚","鼓膜中心向内凹陷，称鼓膜脐，为砧骨柄末端附着处"],"a":4,"e":"鼓膜中心向内凹陷称鼓膜脐，是锤骨柄末端的附着处，而非砧骨柄，故该项错误。鼓膜位于外耳道与鼓室之间，构成鼓室外侧壁的大部分，边缘附着于颞骨鼓部和鳞部，周缘较厚；婴儿鼓膜倾斜，几近水平位，故耳部感染时更易受累。听小骨中锤骨柄附着于鼓膜脐，砧骨居中，镫骨底封闭前庭窗，三者顺序不容混淆"},{"q":"关于呼吸系统的叙述，正确的是","o":["由呼吸道和肺组成","其功能仅是进行气体交换","鼻、咽、喉、气管称上呼吸道","主支气管及其在肺内的分支称下呼吸道","肺仅有肺泡构成"],"a":0,"e":"呼吸系统由呼吸道和肺组成，呼吸道包括鼻、咽、喉、气管及各级支气管，是气体进出的通道，肺是进行气体交换的器官，故该项正确。呼吸系统除气体交换外，还参与发音、嗅觉及酸碱平衡调节，功能非仅气体交换；上呼吸道指鼻、咽、喉，气管属下呼吸道；下呼吸道包括气管、主支气管及其肺内分支；肺由肺泡和肺内支气管树及间质构成"},{"q":"以下关于脊髓的描述，正确的是","o":["薄束和楔束传导痛温觉","第1胸髓节段～第3腰髓节段侧角有副交感神经低级中枢","皮质脊髓侧束终止于对侧前角运动神经元","脊髓丘脑束起始于脊神经节","白质分为前索、后索和外侧索三部分"],"a":4,"e":"脊髓白质由上行和下行的神经纤维束构成，借脊髓表面的沟裂分为前索、外侧索和后索三部分，故该项正确。薄束、楔束传导本体觉和精细触觉，不传导痛温觉；胸1至腰3节段侧角是交感神经低级中枢，副交感中枢在骶2～4；皮质脊髓侧束交叉后终止于同侧前角运动神经元；脊髓丘脑束起始于后角细胞，而非脊神经节"},{"q":"由肾门深入肾实质之间的腔隙称为","o":["肾柱","肾大盏","肾盂","肾蒂","肾窦"],"a":4,"e":"肾门是肾内侧缘中部的凹陷，由此向内深入肾实质所形成的腔隙称肾窦，内含肾小盏、肾大盏、肾盂、肾血管分支、神经和淋巴管及脂肪组织。肾柱是皮质嵌入髓质锥体之间的部分，属肾实质；肾大盏、肾盂虽位于窦内，但只是其内容物而非腔隙本身；肾蒂是进出肾门结构被结缔组织包绕的总称，肾盂为输尿管上端的膨大"},{"q":"有关心包腔的描述，错误者是","o":["由纤维性心包与浆膜性心包围成","由浆膜性心包的脏层与壁层围成","内有少量的浆液","对心脏有保护作用","与胸膜腔不相通"],"a":0,"e":"心包腔是浆膜性心包脏层与壁层之间的潜在腔隙，内有少量浆液，起润滑和保护作用，与胸膜腔互不相通；说它由纤维性心包与浆膜性心包共同围成，混淆了心包与心包腔的概念，故该项错误。纤维性心包是外层坚韧的结缔组织囊，与浆膜性心包壁层紧密相贴，并不构成心包腔的壁，其余各项均为心包腔的正确描述"},{"q":"肩关节囊内通过的肌腱是","o":["胸大肌肌腱","背阔肌肌腱","肱二头肌长头肌腱","肱二头肌短头肌腱","肱三头肌长头肌腱"],"a":2,"e":"肱二头肌长头起自肩胛骨盂上结节，其肌腱经结节间沟穿出肩关节囊，再向下延续为肌腹，是唯一穿经肩关节囊内的肌腱，也是肩周炎的好发部位。胸大肌、背阔肌肌腱止于肱骨，但不穿过关节囊；肱二头肌短头起自喙突，不入关节囊；肱三头肌长头起自盂下结节，与关节囊关系不若长头肌腱密切"},{"q":"以下骨骼肌，由胫神经支配的是","o":["股二头肌","小腿三头肌","胫骨前肌","腓骨长肌","腓骨短肌"],"a":1,"e":"小腿三头肌由腓肠肌和比目鱼肌组成，由胫神经支配，收缩时使足跖屈，是小腿后群的主要肌。股二头肌属大腿后群腘绳肌，由坐骨神经支配；胫骨前肌属小腿前群，由腓深神经支配；腓骨长肌、腓骨短肌属小腿外侧群，由腓浅神经支配。下肢各群肌的神经支配具有明显规律，后群及足底肌统归胫神经管理"},{"q":"右心室的入口是","o":["右房室口","左房室口","肺动脉口","主动脉口","肺静脉口"],"a":0,"e":"右心室的入口为右房室口，口周有三尖瓣附着，血液自右心房经此口流入右心室；其出口为肺动脉口，内有肺动脉瓣，防止血液反流。左房室口是左心室的入口，有二尖瓣；主动脉口为左心室出口，有主动脉瓣；肺静脉口是左心房的入口，将含氧血送入左心房。房室口与动脉口分别构成心腔的流入道和流出道，瓣膜随之配套"},{"q":"关于椎动脉正确的描述是","o":["向上穿行全部颈椎的横突孔","为颈外动脉的分支之一","参与组成大脑动脉环","经枕骨大孔入颅","发出大脑后动脉"],"a":3,"e":"椎动脉起自锁骨下动脉，向上穿第6至第1颈椎横突孔，经枕骨大孔入颅，在脑桥下缘与对侧椎动脉汇合成基底动脉，主要供应脑干、小脑及大脑后部。它并不穿行全部颈椎横突孔，一般自第6颈椎开始；它是锁骨下动脉的分支而非颈外动脉；参与大脑动脉环的是其延续的基底动脉；大脑后动脉为基底动脉终支，非椎动脉直接发出"},{"q":"受腋神经支配的骨骼肌为","o":["三角肌","肱三头肌","肱肌","喙肱肌","肱桡肌"],"a":0,"e":"腋神经发自臂丛后束，绕过肱骨外科颈支配三角肌和小圆肌，其皮支分布于肩部皮肤；肱骨外科颈骨折易损伤该神经，导致三角肌瘫痪、肩部感觉障碍和‘方肩’畸形。肱三头肌由桡神经支配；肱肌由肌皮神经支配；喙肱肌亦由肌皮神经支配；肱桡肌由桡神经支配。三角肌是腋神经支配的标志性肌，其萎缩是损伤的直接体征"},{"q":"伸髋、屈膝的肌肉是","o":["髂腰肌","股四头肌","阔筋膜张肌","缝匠肌","股二头肌"],"a":4,"e":"股二头肌属大腿后群腘绳肌，起自坐骨结节，止于腓骨头，跨越髋关节和膝关节，收缩时可伸髋、屈膝，屈膝位时还能使小腿旋外。髂腰肌主要屈髋；股四头肌是伸膝肌；阔筋膜张肌协助屈髋、外展并紧张髂胫束；缝匠肌可屈髋、屈膝并使大腿旋外。唯有股二头肌兼具伸髋与屈膝的双重作用，是后群肌的典型代表"},{"q":"舌咽神经的根丝通过颅底什么结构出入颅腔","o":["圆孔","卵圆孔","棘孔","颈静脉孔","枕骨大孔"],"a":3,"e":"舌咽神经为第Ⅸ对脑神经，其根丝自延髓橄榄后沟出脑，与迷走神经、副神经一同经颈静脉孔出颅，支配咽肌、腮腺分泌及舌后三分之一的感觉。圆孔有上颌神经通过；卵圆孔有下颌神经通过；棘孔有脑膜中动脉通过；枕骨大孔有延髓、椎动脉及神经根通过。颈静脉孔是后组脑神经出颅的共同通道，舌咽神经居其中"},{"q":"关于脑膜中动脉的叙述，错误的是","o":["是上颌动脉的分支","营养硬脑膜","经棘孔入颅","其前支经翼点深面","营养软脑膜"],"a":4,"e":"脑膜中动脉是上颌动脉的分支，经棘孔入颅，主要营养硬脑膜，其前支经过翼点内面，此处骨折易损伤该动脉引起硬膜外血肿；说它营养软脑膜错误。软脑膜紧贴脑表面，由颈内动脉和椎动脉的分支供血，与脑膜中动脉无关。明确脑膜各层的血供来源及其与颅骨标志性孔道、翼点的关系，对理解颅内出血机制至关重要"},{"q":"有关节盘的关节是","o":["肩关节","肘关节","髋关节","膝关节","颞下颌关节"],"a":4,"e":"颞下颌关节腔内有一纤维软骨关节盘，介于下颌头与关节窝之间，将关节腔分为上下两部，增加关节的适配性和运动形式，是典型的含关节盘关节。肩关节、肘关节、髋关节均为滑膜关节，腔内无关节盘；膝关节内为半月板，形态与关节盘不同；胸锁关节虽也含关节盘，但不在备选项之列。关节盘与半月板名称相似，需按关节分别记忆"},{"q":"关于肋骨正确的描述是","o":["为长骨","分体和前、后两端","肋头与胸椎横突相关节","肋沟位于各肋内面上缘","前端和胸骨相关节"],"a":1,"e":"肋骨呈弓形，可分为肋体和前、后两端，后端称肋头，与胸椎体相关节，前端借肋软骨与胸骨或上位肋软骨相连，故该描述正确。肋骨属扁骨而非长骨；肋头与胸椎体相关节，与横突相关节的是肋结节；肋沟位于肋骨内面下缘，有肋间血管神经走行；仅上七对肋软骨直接与胸骨相关节，下位肋或借软骨相连或游离"},{"q":"下列关于睾丸的描述，正确的是","o":["表面光滑，周围覆以鞘膜","上端有血管、神经和淋巴管进入","上端和后缘为附睾贴附","分为皮质和髓质两部分","精直小管能产生精子和分泌雄性激素"],"a":2,"e":"附睾贴附于睾丸的上端和后缘，由头、体、尾组成，是精子成熟和贮存的场所。血管、神经和淋巴管经精索自睾丸后缘出入，而非上端；鞘膜脏层覆盖睾丸表面，但在后缘附着处反折；睾丸实质由生精小管和间质构成，不分皮质和髓质；精子由生精小管产生，雄激素由间质细胞分泌，精直小管仅司运输，不具生精和内分泌功能"},{"q":"属于脊髓内的下行纤维束有","o":["薄束","楔束","红核脊髓束","脊髓丘脑前束","三叉丘系"],"a":2,"e":"红核脊髓束起自中脑红核，交叉后沿脊髓外侧索下行，终于脊髓前角运动神经元，属下行运动传导束，故该项正确。薄束、楔束是后索的上行感觉束，传导本体觉和精细触觉；脊髓丘脑前束也是上行束，传导粗触觉；三叉丘系在脑干内上行，传导头面部感觉，唯红核脊髓束为下行纤维束"},{"q":"下面属于面颅骨的是","o":["上鼻甲","中鼻甲","下鼻甲","筛骨","颞骨"],"a":2,"e":"下鼻甲是独立的面颅骨，附着于上颌骨和腭骨内面，能调节鼻腔气流的温湿度，属面颅骨。上鼻甲和中鼻甲并非独立骨，而是筛骨迷路内侧壁的骨片，筛骨属脑颅骨；颞骨位于颅侧壁，参与构成颅盖和颅底，也属脑颅骨。面颅骨共15块，包括上颌骨、颧骨、鼻骨、泪骨、腭骨、下鼻甲、犁骨及下颌骨、舌骨等"},{"q":"虎口周缘感觉功能障碍，最有可能损伤的神经为","o":["腋神经","尺神经","正中神经","桡神经","肌皮神经"],"a":3,"e":"虎口即第1、2掌骨之间的区域，其皮肤由桡神经浅支支配，桡神经损伤后该区感觉减退或消失，是最早出现的感觉障碍部位之一。腋神经支配肩部皮肤；尺神经支配手掌尺侧及小鱼际区；正中神经支配手掌桡侧三个半手指；肌皮神经的终支支配前臂外侧皮肤。虎口区域的神经支配单一而明确，是判断桡神经损伤的重要定位体征"},{"q":"躯干和四肢痛温觉传导通路的第2级神经元是","o":["三叉神经节","三叉神经脊束核","脊髓后角细胞","脊髓侧角细胞","脊神经节"],"a":2,"e":"躯干四肢痛温觉传导通路中，第1级神经元在脊神经节，中枢突入脊髓后终止于后角，第2级神经元即脊髓后角细胞，其轴突交叉至对侧组成脊髓丘脑侧束上行。三叉神经节和三叉神经脊束核司头面部感觉；脊髓侧角细胞为交感节前神经元；脊神经节是第1级神经元所在，都不属于躯干四肢痛温觉通路的第2级神经元"},{"q":"卵巢与子宫角相连的韧带是","o":["卵巢系膜","卵巢固有韧带","卵巢悬韧带","子宫圆韧带","子宫阔韧带"],"a":1,"e":"卵巢固有韧带又称卵巢子宫索，连于卵巢内侧端与子宫角之间，将卵巢固定于子宫。卵巢系膜是卵巢门与阔韧带间的双层腹膜，并非连于子宫角；卵巢悬韧带连接卵巢上端与盆壁，内含卵巢动静脉；子宫圆韧带维持子宫前倾，止于大阴唇；子宫阔韧带为覆盖子宫的腹膜皱襞，后三者均非卵巢与子宫角之间的直接连结"},{"q":"腹主动脉通常不发出以下哪条动脉","o":["卵巢动脉","睾丸动脉","肾上腺中动脉","肾上腺上动脉","膈下动脉"],"a":3,"e":"肾上腺的动脉供应有三源：肾上腺上动脉发自膈下动脉，肾上腺中动脉直接发自腹主动脉，肾上腺下动脉来自肾动脉，故腹主动脉通常不发出肾上腺上动脉。卵巢动脉、睾丸动脉直接起自腹主动脉；肾上腺中动脉亦为其直接分支；膈下动脉是腹主动脉的成对壁支。掌握肾上腺三重血供的来源，是辨认腹主动脉分支归属的关键"},{"q":"不供应大肠的动脉是","o":["中结肠动脉","回结肠动脉","左结肠动脉","右结肠动脉","回肠动脉"],"a":4,"e":"回肠动脉是肠系膜上动脉的分支，供应回肠，不参与大肠供血。中结肠动脉供应横结肠；右结肠动脉供应升结肠；左结肠动脉起自肠系膜下动脉，供应降结肠；回结肠动脉供应回盲部、盲肠及升结肠下份，均属大肠供血系统。大肠的动脉来自肠系膜上、下动脉的结肠分支，而回肠动脉专属小肠，二者来源与分布界限分明"},{"q":"关于鼓室，下列说法正确的是","o":["经咽鼓管与鼻腔相通","镫骨底封闭其前庭窗","与筛窦小房相通","其内空气来自外耳道","有前庭蜗神经通过"],"a":1,"e":"镫骨底借环韧带封闭前庭窗，将振动传入内耳，是鼓室与内耳之间的关键结构。鼓室经咽鼓管与鼻咽相通，而非鼻腔；它经乳突窦与乳突小房相通，不与筛窦直接相连；室内空气来自咽鼓管导通的鼻咽，外耳道与鼓室间隔以鼓膜；前庭蜗神经经内耳道入颅，不通过鼓室，鼓室内走行的是鼓索与岩大神经"},{"q":"可以限制子宫向侧方移位的韧带是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":0,"e":"子宫阔韧带是覆盖子宫前后面的双层腹膜，向两侧延伸至盆壁，可限制子宫向两侧移位，是维持子宫位置的重要韧带。子宫主韧带位于阔韧带基部，连于宫颈与盆壁，主要防止子宫脱垂；子宫圆韧带维持子宫前倾；子宫骶韧带维持子宫前屈。各韧带作用方向不同，阔韧带的横向牵制是防止侧移的关键，与其他韧带的功能不可混同"},{"q":"受正中神经支配的骨骼肌为","o":["肱桡肌","拇收肌","第1～2蚓状肌","尺侧腕屈肌","小鱼际"],"a":2,"e":"正中神经支配第1、2蚓状肌及鱼际肌（除拇收肌外）与前臂大部分屈肌，故该项正确。肱桡肌由桡神经支配；拇收肌由尺神经支配，是鱼际肌中的例外；尺侧腕屈肌和小鱼际肌均由尺神经支配，属手内在肌的尺神经支配区。正中神经与尺神经在手肌的支配上有明确分工，第1、2蚓状肌为正中神经所独有，是常考的鉴别点"},{"q":"在下丘下方出脑的神经为","o":["动眼神经","展神经","滑车神经","视神经","副神经"],"a":2,"e":"滑车神经为第Ⅳ对脑神经，其根丝自中脑下丘下方出脑，绕过大脑脚外侧前行，经眶上裂入眶，支配上斜肌，是唯一自脑干背侧发出的脑神经，损伤后眼球不能向下外方转动。动眼神经自中脑脚间窝出脑；展神经自脑桥延髓沟出脑；视神经连于间脑；副神经根丝自延髓和脊髓上颈段发出，出脑部位均与下丘下方无关"},{"q":"关于咽鼓管描述，下列错误的是","o":["咽鼓管使鼓室的气压与外界的大气压相等，以保持鼓膜内、外的压力平衡","咽鼓管连通鼻咽部与鼓室","咽鼓管骨部向后外开口于咽鼓管鼓室口","咽鼓管软骨部向前内开口于咽鼓管咽口，平时处于开放状态","小儿咽鼓管短而宽，接近水平位，故咽部感染可经咽鼓管侵入鼓室"],"a":3,"e":"咽鼓管软骨部向前内开口于鼻咽部的咽鼓管咽口，平时处于闭合状态，仅吞咽或打哈欠时借腭帆张肌等开放，以平衡鼓室与外界气压，故‘平时开放’一说错误。咽鼓管连通鼻咽与鼓室，使鼓室气压与大气压相等，维持鼓膜内外压力平衡；骨部向后外开口于鼓室口；小儿咽鼓管短宽且近水平，咽部感染易经此侵入鼓室"},{"q":"胸骨线","o":["沿胸骨正中的垂线","沿胸骨外侧缘的垂线","沿胸骨旁线内侧所作的垂线","沿锁骨中线所作的垂线","经腹股沟韧带中点向上所作的垂线"],"a":1,"e":"胸骨线是沿胸骨外侧缘所作的垂直线，是胸部体表标志线之一，用于描述纵隔和胸腔脏器的体表投影。沿胸骨正中的垂线为正中线；胸骨旁线是经胸骨线与锁骨中线之间的中点所作的垂线；锁骨中线经锁骨中点向下；经腹股沟韧带中点向上的垂线为股动脉投影线。各体表标志线的界定是胸部物理诊断和影像定位的基础"},{"q":"下列肌中，使肩关节外展的是","o":["三角肌","大圆肌","斜方肌","前锯肌","肩胛下肌"],"a":0,"e":"三角肌覆盖肩部，起自锁骨外侧段、肩峰和肩胛冈，止于肱骨三角肌粗隆，其中部纤维收缩使肩关节外展，是外展的主要动力肌，前部纤维使肩关节前屈旋内，后部纤维使之后伸旋外。大圆肌使肩关节内收、后伸和旋内；斜方肌作用于肩胛骨，使其上提、后缩；前锯肌使肩胛骨前伸；肩胛下肌使肩关节旋内，均无外展作用"},{"q":"关于桡骨的描述，正确的是","o":["桡骨位于尺骨的外侧","上端有冠突","上端有鹰嘴","下端较小","下端有桡切迹"],"a":0,"e":"桡骨位于前臂外侧（拇指侧），上端为桡骨头，与肱骨小头及尺骨桡切迹相关节；下端膨大，参与构成腕关节。冠突、鹰嘴均为尺骨上部结构；桡骨下端粗大而非较小；桡切迹在尺骨上端，桡骨下端内侧为尺切迹。区分二骨的关键在于：桡骨居外侧、上端小而下端大，尺骨居内侧、上端大而下端小，形态恰成互补"},{"q":"关于上肢浅静脉的叙述正确的是","o":["头静脉沿前臂尺侧上行","贵要静脉注入肘正中静脉","头静脉沿肱二头肌内侧沟上行","肘正中静脉是浅静脉","肘正中静脉注入头静脉"],"a":3,"e":"肘正中静脉位于肘窝皮下，属上肢浅静脉，连接头静脉与贵要静脉，是临床静脉注射和采血的常用部位。头静脉沿前臂桡侧上行，在肱二头肌外侧沟上行注入腋静脉，并非沿尺侧或内侧沟；贵要静脉起于手背静脉网尺侧，注入肱静脉或腋静脉，而非注入肘正中静脉；肘正中静脉注入贵要静脉，不注入头静脉"},{"q":"支配瞳孔开大肌的节前神经元的胞体位于","o":["颈上神经节","颈胸神经节","T1～2节段的前角细胞","T1～2节段的侧角细胞","T1～2节段的后角细胞"],"a":3,"e":"瞳孔开大肌受交感神经支配，其节前神经元胞体位于脊髓胸1～2节段的侧角，节前纤维上行至颈上神经节换元，节后纤维随颈内动脉丛分布于瞳孔开大肌。颈上神经节、颈胸神经节为交感神经节，是节后神经元所在，而非节前胞体；T1～2前角细胞为运动神经元，后角细胞为感觉中间神经元，均不发出交感节前纤维"},{"q":"骶管麻醉的穿刺部位是","o":["骶角","骶管裂孔","骶前孔","骶后孔","骶岬"],"a":1,"e":"骶管裂孔是骶骨背面由第4、5骶椎椎弓未愈合形成的裂口，向上通骶管，是骶管麻醉的穿刺部位，其两侧有骶角作为体表定位标志。骶角是定位标志而非穿刺点本身；骶前孔、骶后孔是骶神经前、后支穿出的孔道，不通行骶管；骶岬是骶骨底前缘的突出部，为骨盆界线的标志，与骶管穿刺无关"},{"q":"关于甲状腺的描述，错误的是","o":["吞咽时甲状腺可随喉上、下移动","甲状腺峡常有向上伸出的锥状叶","甲状腺素的主要作用是促进新陈代谢","甲状腺左、右叶贴于喉下部和气管颈部的前外侧","甲状腺峡位于第5～6气管软骨前方"],"a":4,"e":"甲状腺峡位于第2～4气管软骨环的前方，而非第5～6气管软骨，故该项错误。甲状腺左右叶贴于喉下部和气管颈部的前外侧，吞咽时随喉上下移动；峡部有时向上伸出锥状叶；甲状腺素主要促进新陈代谢和生长发育，提高神经系统兴奋性。掌握甲状腺峡与气管软骨的对应关系，是颈部手术避免误伤气管的解剖基础"},{"q":"连结椎体的结构是","o":["后纵韧带","黄韧带","棘上韧带","棘间韧带","关节突关节"],"a":0,"e":"后纵韧带位于椎体和椎间盘的后方，纵贯脊柱全长，与椎体后面及椎间盘相连，是连结椎体的重要韧带，可限制脊柱过度前屈。黄韧带连结相邻椎弓板；棘上韧带和棘间韧带分别连结各椎棘突的尖端和相邻棘突之间；关节突关节是相邻椎骨上下关节突构成的滑膜关节，属椎弓间的连结，均不直接连结椎体"},{"q":"男性生殖腺是","o":["睾丸","附睾","前列腺","精囊","肾上腺"],"a":0,"e":"睾丸是男性的生殖腺，能产生精子并分泌雄激素，兼具生殖与内分泌功能。附睾是贮存和促进精子成熟的管道，属生殖管道；前列腺和精囊是附属腺，分泌精液成分，属外分泌腺；肾上腺是位于腹膜后的内分泌腺，分泌皮质激素和髓质激素，与生殖无直接关系。生殖腺的本质在于产生生殖细胞并分泌性激素，睾丸与卵巢分别对应男女性"},{"q":"不属于腹膜间位器官的是","o":["子宫","肝","胆","升结肠","横结肠"],"a":4,"e":"横结肠有完整系膜，属腹膜内位器官，活动度大，不属腹膜间位器官。子宫、肝、胆囊、升结肠三面或大部被腹膜覆盖，位置较固定，均属腹膜间位器官。腹膜内位器官几乎全被腹膜包裹且有系膜，如胃、空肠、回肠、阑尾；腹膜外位器官仅一面被覆腹膜，如肾、输尿管、胰。分类依据是被腹膜覆盖的范围与有无系膜"},{"q":"关于子宫动脉的描述中何者有误","o":["发自髂内动脉","行于子宫阔韧带两层之间","在距子宫颈外侧约2cm处输尿管跨过其前方","供应子宫、卵巢、输卵管等","与卵巢动脉的分支吻合"],"a":2,"e":"子宫动脉在距子宫颈外侧约2cm处跨过输尿管的前上方，而非输尿管跨过其前方，故该表述将二者关系颠倒，属错误描述，临床上称为‘桥下流水’。子宫动脉发自髂内动脉，行于子宫阔韧带两层之间，供应子宫、卵巢、输卵管等，并与卵巢动脉分支吻合。手术中辨认子宫动脉与输尿管的交叉关系，是避免结扎或损伤输尿管的关键"},{"q":"躯干和四肢意识性本体感觉传导通路的第2级神经元是","o":["三叉神经脑桥核","三叉神经脊束核","脊髓后角细胞","脊髓前角运动细胞","薄束核和楔束核"],"a":4,"e":"躯干四肢意识性本体感觉通路中，第1级神经元在脊神经节，其轴突组成薄束、楔束上行，第2级神经元为延髓的薄束核和楔束核，发出纤维交叉成内侧丘系，终于丘脑腹后外侧核。三叉神经脑桥核、脊束核司头面部感觉；脊髓后角细胞是痛温觉通路的中继；脊髓前角运动细胞属运动神经元，都不参与该通路"},{"q":"在中耳鼓室内，听小骨由外向内依次是","o":["锤骨 镫骨 砧骨","锤骨 砧骨 镫骨","镫骨 锤骨 砧骨","镫骨 砧骨 锤骨","砧骨 锤骨 镫骨"],"a":1,"e":"鼓室内三块听小骨由外向内依次为锤骨、砧骨、镫骨：锤骨柄附着于鼓膜脐，锤骨头与砧骨体相关节，砧骨长脚连接镫骨小头，镫骨底封闭前庭窗，构成声波传导的杠杆系统。其余排列均打乱了这一由外向内的固定顺序。听小骨之间的连接关系与镫骨底封闭前庭窗的结构相配合，是理解声波由鼓膜传入内耳的关键"},{"q":"肾的被膜从内向外依次为","o":["脂肪囊 纤维囊 肾筋膜","肾筋膜 脂肪囊 纤维囊","纤维囊 脂肪囊 肾筋膜","纤维囊 肾筋膜 脂肪囊","肾筋膜 纤维囊 脂肪囊"],"a":2,"e":"肾被膜紧贴肾表面的是纤维囊，为薄层致密结缔组织；其外为脂肪囊，由疏松结缔组织和脂肪构成，起缓冲固定作用；最外层为肾筋膜，包裹肾与肾上腺并连于腹后壁。把脂肪囊列为最内层或把肾筋膜列为内层均错，三者只按纤维囊、脂肪囊、肾筋膜排列"},{"q":"角膜和虹膜之间的腔隙称","o":["眼球后房","眼球前房","虹膜角膜角","虹膜角膜角隙","前房角"],"a":1,"e":"眼球前房位于角膜后面与虹膜前面之间，内充房水，经虹膜角膜角通向后房。眼球后房在虹膜后方与晶状体前面之间；虹膜角膜角是前房周边部的夹角，为房水回流处；前房角即虹膜角膜角，均非该腔隙本身"},{"q":"用来描述空腔脏器的方位术语是","o":["内、外","内侧、外侧","近侧、远侧","深、浅","近端、远端"],"a":0,"e":"内、外以空腔脏器的腔为中心，近腔者为内、远腔者为外，专用于描述胃、肠、膀胱等中空器官。内侧、外侧以身体正中矢状面为准，表示距正中线的远近；近侧、远侧用于四肢，表示距肢体根部的远近；深、浅以体表为准"},{"q":"卵巢位于","o":["盆腔中央","盆腔前壁","盆腔后壁","盆腔侧壁","盆膈上面"],"a":3,"e":"卵巢位于小骨盆侧壁的卵巢窝内，处在髂外动脉与脐动脉之间，借卵巢悬韧带和卵巢固有韧带固定。盆腔中央为膀胱、子宫等占据；盆腔后壁是直肠所在；盆膈上面为盆腔底，均非卵巢常居之处"},{"q":"支配肱三头肌的神经为","o":["正中神经","尺神经","桡神经","肌皮神经","腋神经"],"a":2,"e":"桡神经发自臂丛后束，沿桡神经沟行于肱骨后面，支配肱三头肌及前臂伸肌群。正中神经主要支配前臂屈肌和手部鱼际肌；尺神经支配尺侧腕屈肌和手内在肌；肌皮神经支配肱二头肌等屈肌；腋神经支配三角肌"},{"q":"关于肱骨内上髁形态的描述，正确的是","o":["活体不能触及","位于肱骨头的内侧","后下有尺神经沟","呈半球形","与解剖颈相接"],"a":2,"e":"肱骨内上髁为下端内侧的显著突起，其后下方有尺神经沟，尺神经由此经过，故活体可清楚触及。半球形是肱骨头的外观；内上髁位于肱骨下端而非肱骨头内侧；它与解剖颈相接也不对，解剖颈属肱骨上端"},{"q":"关于胸导管的描述，正确的是","o":["注入左静脉角","行于胸主动脉后方","由右腰干和肠干合成","收纳身体右侧半淋巴","经膈的食管裂孔入胸腔"],"a":0,"e":"胸导管为全身最大的淋巴管，由左右腰干和肠干汇合而成，穿膈主动脉裂孔入胸腔，最终注入左静脉角，收纳左侧半身及下半身淋巴。只说右腰干和肠干合成遗漏左腰干；收纳右侧半淋巴的是右淋巴导管；经食管裂孔入胸腔也不符"},{"q":"连通第三脑室与第四脑室的结构是","o":["正中孔","外侧孔","中脑水管","室间孔","终池"],"a":2,"e":"中脑水管纵贯中脑，上通第三脑室、下接第四脑室，是脑室系统的重要通道。室间孔连通侧脑室与第三脑室；正中孔和外侧孔为第四脑室通向蛛网膜下腔的出口；终池是脊髓下端蛛网膜下腔的扩大，均不连接第三、四脑室"},{"q":"关于十二指肠悬肌(Treitz韧带)的说法，错误的是","o":["是腹部手术中确认空肠起始的重要标志","由肌组织和结缔组织构成","下端附于十二指肠空肠曲","是区分十二指肠水平部与升部的标志","对十二指肠空肠曲有悬吊、固定的作用"],"a":3,"e":"十二指肠悬肌由肌组织和结缔组织构成，下端附于十二指肠空肠曲，将其悬吊固定于腹后壁，是腹部手术中确认空肠起始的标志。它并不参与划分十二指肠水平部与升部，故该项作为错误描述被选出"},{"q":"对输尿管的描述，错误的是","o":["起自肾盂","开口于膀胱","在小骨盆上缘处，跨过髂血管的后方","有三个生理狭窄","由平滑肌构成"],"a":2,"e":"输尿管起自肾盂，由平滑肌构成，全程有三处生理狭窄，下达膀胱底。在小骨盆上缘处它跨过髂外血管的前方而非后方，这是与髂血管的恒定关系，也是手术中辨认的标志，故该项描述错误"},{"q":"第Ⅲ对脑神经为","o":["滑车神经","动眼神经","三叉神经","展神经","视神经"],"a":1,"e":"脑神经按罗马数字排序，第Ⅲ对为动眼神经，发自中脑，支配大部分眼外肌和瞳孔括约肌。第Ⅱ对是视神经；第Ⅳ对为滑车神经；第Ⅴ对为三叉神经；第Ⅵ对为展神经，均与序号不符"},{"q":"血管吻合的最常见方式是","o":["动脉通过毛细血管与静脉吻合","动脉与动脉之间的吻合","静脉与静脉之间的吻合","动静脉短路","侧支吻合"],"a":0,"e":"全身血管最普遍的连接形式是动脉经毛细血管与静脉相通，血液由此完成物质交换后回流，数量最多、分布最广。动脉间吻合形成动脉网或动脉弓，静脉间吻合成静脉丛，动静脉短路多见于指尖等处，侧支吻合则在主干阻塞时建立侧支循环"},{"q":"关于肩胛骨正确的描述是","o":["关节盂位于肩胛骨内侧缘","肩胛上角平第3肋","肩胛下角平第7肋","肩胛冈的内侧端构成肩峰","肩胛下窝位于肩胛冈下方"],"a":2,"e":"肩胛骨为三角形扁骨，肩胛下角是直立时最下方的角，约平第7肋或第7肋间隙，是计数肋骨的标志。关节盂位于外侧角；肩胛上角平第2肋；肩峰由肩胛冈外侧端构成；肩胛下窝位于前面，冈下窝才在肩胛冈下方"},{"q":"支配肱二头肌的神经为","o":["正中神经","尺神经","桡神经","肌皮神经","腋神经"],"a":3,"e":"肌皮神经发自臂丛外侧束，穿过喙肱肌后沿肱二头肌深面下行，支配肱二头肌、喙肱肌和肱肌。正中神经支配前臂屈肌；尺神经支配尺侧屈肌；桡神经支配伸肌；腋神经支配三角肌和小圆肌"},{"q":"参与组成小网膜的韧带是","o":["肝胃韧带","胃结肠韧带","肝镰状韧带","脾胃韧带","肝圆韧带"],"a":0,"e":"小网膜是肝门至胃小弯和十二指肠上部的双层腹膜，由肝胃韧带和肝十二指肠韧带组成，前者连于肝门与胃小弯。胃结肠韧带和脾胃韧带属于大网膜；肝镰状韧带、肝圆韧带为肝的韧带，不参与小网膜"},{"q":"下面有关跟腱的描述，正确的是","o":["是胫骨后肌的肌腱","止于跟骨结节","是小腿后肌群共同汇合点","断裂后踝关节不能背屈","断裂后足不能外翻"],"a":1,"e":"跟腱由腓肠肌与比目鱼肌的肌腱合并而成，是人体最粗大的肌腱，向下止于跟骨结节，收缩时使足跖屈。它是小腿三头肌的共同肌腱而非全部后肌群；断裂后足不能跖屈、不能提踵，背屈和外翻功能不受累"},{"q":"十二指肠的动脉供应来自","o":["胃网膜左动脉","胃网膜右动脉","胰十二指肠上前、后动脉","胰十二指肠下前、后动脉","胰十二指肠上前、后动脉与胰十二指肠下前、后动脉"],"a":4,"e":"十二指肠的动脉主要来自腹腔干的胰十二指肠上动脉和肠系膜上动脉的胰十二指肠下动脉，二者各分前后支，在十二指肠与胰头之间吻合成动脉弓。胃网膜左、右动脉主要营养胃大弯，不供应十二指肠"},{"q":"以下对视神经的描述，错误的是","o":["为第Ⅱ对脑神经","穿经圆孔入颅","由视网膜节细胞的轴突构成","由特殊躯体感觉纤维组成","一侧视神经损伤出现同侧视野全盲"],"a":1,"e":"视神经为第Ⅱ对脑神经，由视网膜节细胞轴突汇集而成，属特殊躯体感觉纤维，经视神经管入颅，损伤后出现同侧视野全盲。圆孔通过的是上颌神经；视神经不经圆孔，故该项描述错误"},{"q":"受肌皮神经支配的骨骼肌为","o":["肱三头肌","肱二头肌","三角肌","小圆肌","背阔肌"],"a":1,"e":"肌皮神经支配臂前群的肱二头肌、喙肱肌和肱肌，其中肱二头肌为其典型代表。肱三头肌受桡神经支配；三角肌和小圆肌受腋神经支配；背阔肌由胸背神经支配，均不属肌皮神经"},{"q":"枕额肌的作用是","o":["皱额","皱眉","提上脸","皱枕部头皮","睁眼"],"a":0,"e":"枕额肌由枕腹和额腹以帽状腱膜相连，额腹收缩时上提眉弓、使额部皮肤出现横纹，即皱额。皱眉主要由降眉间肌等完成；提上睑和睁眼由上睑提肌负责；枕腹收缩只牵拉头皮向后，不产生额纹"},{"q":"收缩时使额部皮肤出现皱纹的肌肉是","o":["枕额肌","颊肌","眼轮匝肌","口轮匝肌","翼内肌"],"a":0,"e":"枕额肌的额腹位于额部皮下，收缩时上提眉部并使额皮肤形成横纹，是产生额纹的肌肉。颊肌主使颊部紧贴牙列；眼轮匝肌闭眼；口轮匝肌闭口；翼内肌为咀嚼肌，均不产生额纹"},{"q":"呈乳白色的眼球纤维膜是","o":["角膜","巩膜","虹膜","脉络膜","视网膜"],"a":1,"e":"眼球纤维膜分角膜和巩膜，巩膜占后五分之六，由致密结缔组织构成，呈乳白色不透明，起保护和支持作用。角膜透明，虹膜富含色素呈棕褐色，脉络膜富含血管色素呈棕黑色，视网膜为神经层，均非乳白色纤维膜"},{"q":"下列关于精囊的描述，正确的是","o":["位于膀胱底后面，输精管壶腹内侧","是一对长椭圆形器官，表面平滑","具有贮存精子的作用","其排泄管与输精管壶腹的下端汇合成射精管","是男性结扎的常用部位"],"a":3,"e":"精囊位于膀胱底后方、输精管壶腹的外侧，其排泄管与输精管壶腹下端汇合成射精管，穿前列腺开口于尿道前列腺部。贮存精子的是附睾；表面不平呈分叶状；男性结扎部位是输精管，均非精囊"},{"q":"供应胸腹壁的动脉中没有","o":["肋间后动脉、肋间前动脉","肋下动脉、肌膈动脉","腹壁上动脉、腹壁下动脉","膈下动脉、腰动脉","骶外侧动脉、闭孔动脉"],"a":4,"e":"胸腹壁的动脉来源包括肋间后动脉和肋间前动脉、肋下动脉和肌膈动脉、腹壁上动脉和腹壁下动脉，以及膈下动脉、腰动脉等。骶外侧动脉分布于骶部，闭孔动脉主要营养盆壁和大腿内侧肌，不参与胸腹壁供应"},{"q":"下面有关腓肠肌的描述，正确的是","o":["使踝关节背屈、足内翻","使踝关节跖屈、足内翻","使踝关节跖屈、足外翻","能屈膝关节和背屈踝关节","屈膝关节并使足跖屈"],"a":4,"e":"腓肠肌起自股骨内、外侧髁后面，与比目鱼肌合成跟腱止于跟骨结节，跨越膝、踝两关节，故能屈膝并使足跖屈。它不能背屈踝关节，也不主司足内翻或外翻；内翻、外翻由胫骨前肌、腓骨长短肌等完成"},{"q":"有关节唇的关节是","o":["肘关节","桡腕关节","髋关节","膝关节","距小腿关节"],"a":2,"e":"髋关节的关节唇为附着于髋臼缘的纤维软骨环，加深髋臼、增大关节面，属典型关节唇结构。肘关节、桡腕关节、膝关节和距小腿关节均无关节唇；膝关节内有半月板，腕关节有三角纤维软骨，性质不同"},{"q":"关于颈内静脉，下列描述中正确的是","o":["在颈静脉孔处续于乙状窦","在卵圆孔处续于乙状窦","在圆孔处续于乙状窦","在颈静脉孔处续于横窦","在颈静脉孔处续于直窦"],"a":0,"e":"颈内静脉是颈部最粗大的静脉，起自颅底的颈静脉孔，直接续接乙状窦，沿颈动脉鞘下行与锁骨下静脉合成头臂静脉。卵圆孔、圆孔为颅中窝裂孔，通过三叉神经分支；横窦、直窦不在此处直接延续为颈内静脉"},{"q":"阑尾根部的体表投影是","o":["脐与右髂前上棘连线的中、内1/3交点处","脐与右髂前上棘连线的中、外1/3交点处","脐与右髂前下棘连线的中、外1/3交点处","两侧髂结节连线的中、右1/3交点处","两侧髂前上棘连线中点处"],"a":1,"e":"阑尾根部投影在脐与右髂前上棘连线的中、外三分之一交点处，即麦氏点，是阑尾炎压痛的标志。中、内三分之一交点不符；髂前下棘和髂结节连线的定位均无解剖依据；两髂前上棘连线中点也不是阑尾根部"},{"q":"以下对眼神经的描述，错误的是","o":["其分支泪腺神经含有来自面神经的副交感纤维控制泪腺分泌","额神经为眼神经的分支","为三叉神经的分支之一","经眶上裂入眶","为混合性神经"],"a":4,"e":"眼神经是三叉神经第一支，为感觉性神经，经眶上裂入眶，分为额神经、泪腺神经和鼻睫神经，只传导眼及额部感觉。泪腺神经中的副交感纤维来自面神经借其行程，不改其感觉性质，故眼神经为混合神经的说法错误"},{"q":"不能做环转运动的关节是","o":["肩关节","桡腕关节","掌指关节","髋关节","膝关节"],"a":4,"e":"膝关节为屈戌关节，主要做屈、伸运动，半屈膝时可作小幅旋转，因交叉韧带和侧副韧带限制，不能完成环转。肩关节、髋关节为球窝关节，桡腕关节为椭圆关节，掌指关节近似球窝状，均可环转"},{"q":"有关膀胱的描述，正确的是","o":["膀胱各部之间界限明显","充盈时呈卵圆形","膀胱尖朝向前下方","膀胱尖的内面有一膀胱三角","肌层由横纹肌构成"],"a":1,"e":"膀胱是储存尿液的肌性囊，空虚时呈锥体形，充盈时变为卵圆形并上升至腹前壁。膀胱各部无明显界限；膀胱尖朝向前上方；膀胱三角位于膀胱底内面两输尿管口与尿道内口之间；肌层由平滑肌构成"},{"q":"射精管开口于","o":["膀胱三角内","前列腺实质内","尿道前列腺部","尿道膜部","尿道海绵体部"],"a":2,"e":"射精管由输精管末端与精囊排出管汇合而成，长约2cm，穿前列腺实质开口于尿道前列腺部后壁的精阜。A、C项尿道海绵体部与球部位于前尿道；B项膜部为穿尿生殖膈的短段；E项舟状窝为海绵体部末端的膨大"},{"q":"男性尿道可分为","o":["前列腺部、膜部和球部","前列腺部、膜部和海绵体部","前列腺部、膜部、球部和海绵体部","壁内部、膜部和海绵体部","膜部、球部和海绵体部"],"a":1,"e":"男性尿道以尿道括约肌为界分为前、后尿道，解剖上依次分为前列腺部、膜部和海绵体部三段。球部属于海绵体部的一段，不是独立分部；壁内部仅为尿道内口的一段，均不构成标准分区"},{"q":"有系膜相连的器官","o":["回肠","盲肠","升结肠","降结肠","直肠"],"a":0,"e":"回肠与空肠同属小肠，由小肠系膜悬吊于腹后壁，活动度大。盲肠、升结肠和降结肠为腹膜间位或外位器官，位置较固定，无系膜；直肠下段位于盆腔，也无系膜附着"},{"q":"关于肋正确的描述是","o":["上6对肋直接与胸骨相连，故称真肋","呈长条形，属长骨","第8～12肋组成肋弓","肋结节与椎体肋凹相关节","第2肋平对胸骨角"],"a":4,"e":"胸骨角向前突出，两侧平对第2肋，是计数肋骨的重要标志。上7对肋经肋软骨直接连胸骨称真肋，非上6对；第8至第10肋借上位肋软骨组成肋弓；肋结节与胸椎横突肋凹相关节；肋属扁骨，不是长骨"},{"q":"黄骨髓存在于","o":["所有骨的内部","幼儿长骨骨干内部","成人长骨骨干内部","幼儿长骨骨骺内部","成人扁骨内部"],"a":2,"e":"幼年时骨髓均为红骨髓，成年后长骨骨干内的红骨髓被脂肪组织替代变为黄骨髓，失去造血功能。幼儿长骨骨干为红骨髓；骨骺内终身保留红骨髓；成人扁骨内亦为红骨髓"},{"q":"关于喉的描述，错误的是","o":["位于颈前部正中","喉以软骨为支架","上部借韧带和肌与舌骨相连","声门裂是喉腔内最狭窄的部位","既是呼吸道，又是味觉器官"],"a":4,"e":"喉位于颈前正中，以喉软骨为支架，上借韧带和肌与舌骨相连，既是呼吸道又是发音器官，声门裂为喉腔最窄处。味觉由舌黏膜的味蕾感受，喉无味觉功能，故该项为错误描述"},{"q":"男性尿道的第二个狭窄位于","o":["尿道内口","尿道外口","尿道前列腺部","尿道膜部","尿道海绵体部"],"a":3,"e":"男性尿道有三处狭窄，依次为尿道内口、尿道膜部和尿道外口，其中尿道外口最窄。膜部为第二狭窄，位于尿生殖膈内；前列腺部和海绵体部为膨大处而非狭窄，球部属海绵体部"},{"q":"脑干内，接受味觉纤维的神经核是","o":["疑核","孤束核","舌下神经核","舌咽神经核","面神经核"],"a":1,"e":"孤束核位于延髓，接受面神经、舌咽神经和迷走神经传入的味觉纤维及一般内脏感觉纤维。疑核为特殊内脏运动核，支配咽喉肌；舌下神经核支配舌肌；面神经核支配表情肌，均不接收味觉"},{"q":"下列直接汇入下腔静脉的静脉是","o":["脾静脉","肝门静脉","肝静脉","肠系膜上静脉","肠系膜下静脉"],"a":2,"e":"肝静脉起自肝内，直接注入下腔静脉，是肝血引流的主要通道。脾静脉、肠系膜上静脉和肠系膜下静脉先汇入门静脉，经肝窦后才入下腔静脉；肝门静脉本身也不直接注入下腔静脉"},{"q":"咽腔的通道有几个","o":["4","5","6","7","8"],"a":3,"e":"咽为前后略扁的肌性管道，向前分别与鼻腔、口腔相通，向下通食管，并经喉口通喉腔，两侧借咽鼓管咽口通中耳，共七个通道。其鼻部、口部、喉部三段以此为界，是消化道与呼吸道的共同通路"},{"q":"关于骨的描述，错误的是","o":["成人骨共有206块，其中6块听小骨属于感觉器","骨按部位可分为长骨、短骨、扁骨、不规则骨","骨的表面常有有突起、凹陷、膨大等形态结构","骨主要由骨质、骨膜和骨髓构成","骨由有机质和无机质构成"],"a":1,"e":"成人共有206块骨，其中6块听小骨属感觉器，骨由骨质、骨膜、骨髓构成，主要由有机质和无机质组成，表面常有突起、凹陷等形态。长骨、短骨、扁骨、不规则骨是按形态分类，按部位应分颅骨、躯干骨和四肢骨，故该项错误"},{"q":"支配右下肢末端骨骼肌随意运动的大脑皮质区位于","o":["左半球中央前回下部","右半球中央前回下部","左半球中央旁小叶前部","右半球中央旁小叶前部","左半球中央前回中部"],"a":2,"e":"大脑皮质运动区位于中央前回和中央旁小叶前部，身体各部投射呈倒置的人形，下肢末端代表区在中央旁小叶前部，且支配对侧肢体，故右下肢由左半球管理。中央前回下部管理头面，中部管理上肢；右侧半球支配左侧肢体"},{"q":"收集头颈部的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":1,"e":"颈干由头颈部淋巴结的输出管汇成，收集头颈部的淋巴，注入胸导管或右淋巴导管。肠干收集腹腔不成对器官淋巴；腰干收集下肢和盆腹部淋巴；锁骨下干收集上肢淋巴；支气管纵隔干收集胸壁和胸腔器官淋巴"},{"q":"供应大脑半球外侧面的主要动脉是","o":["大脑前动脉","大脑中动脉","大脑后动脉","基底动脉","前交通动脉"],"a":1,"e":"大脑中动脉为颈内动脉的直接延续，主要供应大脑半球外侧面及岛叶，是外侧面的主要供血动脉。大脑前动脉供应额顶叶内侧面；大脑后动脉供应枕叶及颞叶下面；基底动脉供应脑干和小脑；前交通动脉为交通支"},{"q":"男性尿道最短的一部是","o":["尿道壁内部","尿道前列腺部","尿道膜部","尿道海绵体部","尿道球部"],"a":2,"e":"男性尿道膜部穿过尿生殖膈，长约1.5厘米，是三段中最短且最固定的一段，也是第二处狭窄所在。前列腺部较长且管腔最宽；海绵体部最长；球部为海绵体部的膨大，壁内部极短但不列为独立三部"},{"q":"脑脊液产生于","o":["硬脑膜","软脑膜","蛛网膜","脉络丛","蛛网膜粒"],"a":3,"e":"脑脊液主要由脑室内的脉络丛产生，充满脑室和蛛网膜下腔，具有缓冲、保护和营养作用。蛛网膜粒是脑脊液吸收入硬脑膜窦的部位；硬脑膜、软脑膜和蛛网膜为脑膜分层，均不产生脑脊液"},{"q":"收肌结节位于","o":["胫骨上端内侧","胫骨上端外侧","股骨内上髁上方","股骨外上髁上方","股骨内上髁后方"],"a":2,"e":"收肌结节是股骨下端内侧的突起，位于内上髁上方，为大收肌腱附着处，是体表可触及的标志。胫骨上端内、外侧为胫骨髁；股骨外上髁在股骨下端外侧；内上髁后方为内上髁后部，均非收肌结节位置"},{"q":"支配瞳孔括约肌的神经为","o":["眼神经","滑车神经","展神经","副神经","动眼神经"],"a":4,"e":"瞳孔括约肌属平滑肌，由动眼神经内的副交感纤维支配，来自中脑动眼神经副核，经睫状神经节换元后使瞳孔缩小。眼神经为感觉神经；滑车神经支配上斜肌；展神经支配外直肌；副神经支配胸锁乳突肌和斜方肌"},{"q":"胸大肌收缩时","o":["臂外展和旋外","臂内收和旋内","臂外展和后伸","下降肋骨助呼气","臂内收和前屈"],"a":1,"e":"胸大肌起自锁骨内侧半、胸骨和上部肋软骨，止于肱骨大结节嵴，收缩时使肩关节内收、旋内并前屈。臂外展和旋外为三角肌、冈下肌等作用；外展后伸由背阔肌等完成；下降肋骨助呼气非其主要功能"},{"q":"最晚闭合的颅囟是","o":["前囟","后囟","乳突囟","蝶囟","枕囟"],"a":0,"e":"前囟位于冠状缝与矢状缝交界处，出生时约一至二厘米，通常在一岁半左右闭合，是各颅囟中最晚闭合者，可借此判断颅骨发育。后囟出生后两三个月即闭合，蝶囟和乳突囟闭合更早"},{"q":"下列汇入颈内静脉的血管是","o":["耳后静脉","颈外静脉","头静脉","枕静脉","面静脉"],"a":4,"e":"面静脉起自内眦静脉，下行汇入颈内静脉，是颈内静脉的重要属支。耳后静脉和枕静脉多汇入颈外静脉；颈外静脉注入锁骨下静脉；头静脉为上肢浅静脉，注入腋静脉，均不直接汇入颈内静脉"},{"q":"海马位于大脑哪个叶","o":["额叶","颞叶","顶叶","枕叶","岛叶"],"a":1,"e":"海马是位于大脑半球颞叶内侧面的古皮质结构，处于侧脑室下角底，参与记忆形成，属边缘系统。额叶为运动和联络区；顶叶管理躯体感觉；枕叶为视觉中枢；岛叶埋于外侧沟深部，均非海马所在"},{"q":"下列结构中，位于阴囊内的是","o":["前列腺","精囊腺","附睾","射精管","海绵体"],"a":2,"e":"附睾位于阴囊内，紧贴睾丸后缘，由附睾管盘曲而成，具有储存精子并促进其成熟的作用。前列腺、精囊腺和射精管位于盆腔内；海绵体为阴茎的勃起组织，均不在阴囊内"},{"q":"股骨体后面的纵行骨嵴是","o":["大转子","股骨颈","粗线","臀肌粗隆","耻骨肌线"],"a":2,"e":"粗线是股骨体后面纵行的骨嵴，分为内、外唇，向下分为内、外侧髁线，为肌肉附着处。大转子位于股骨颈与体交界处外侧；股骨颈连接股骨头与体；臀肌粗隆为大转子下方的粗糙面；耻骨肌线位于股骨体前面上部"},{"q":"以下对前庭蜗神经描述错误的是","o":["其为第Ⅷ对脑神经","又称位听神经","其经内耳门入颅","蜗神经节由双极神经元组成","前庭神经传导听觉"],"a":4,"e":"前庭蜗神经为第Ⅷ对脑神经，又称位听神经，经内耳门入颅，由前庭神经和蜗神经组成，蜗神经节由双极神经元构成。前庭神经传导位置觉和平衡觉，蜗神经才传导听觉，故前庭神经传导听觉的说法错误"},{"q":"关于腮腺管的描述，正确的是","o":["发自腺的下缘","在颧弓下2横指处越过咬肌表面","穿咬肌开口于腮腺管乳头","开口于与上颌第2磨牙相对的颊黏膜处","开口于与上颌第1磨牙相对的颊黏膜处"],"a":3,"e":"腮腺管自腮腺前缘发出，在颧弓下方约一横指处越过咬肌表面，穿颊肌后开口于上颌第二磨牙相对的颊黏膜腮腺管乳头。发自下缘、穿咬肌后开口、平上颌第一磨牙开口等说法均与行程和开口不符"},{"q":"下列结构，何项是肾皮质构成","o":["肾大盏","肾乳头","肾柱","肾盂","肾窦"],"a":2,"e":"肾柱是肾皮质伸入肾锥体之间的部分，属皮质结构，内含肾小球和血管。肾乳头为肾锥体尖端伸入肾小盏的部分；肾大盏、肾盂和肾窦属于肾的排尿部和集合系统，并非皮质"},{"q":"有关心的描述，何者为错","o":["为循环系统的动力器官","左半心的血富含氧气","右半心的血富含CO2","左、右心房以卵圆孔相通","左、右心室互不相通"],"a":3,"e":"心的左半含动脉血、右半含静脉血，是循环的动力器官，左右心室互不相通。卵圆孔为胎儿期左右心房的通道，出生后闭合为卵圆窝，成人左右心房并不相通，故该项错误"},{"q":"肝的右纵沟前部容纳的是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","动脉韧带"],"a":2,"e":"肝右纵沟前部为胆囊窝，容纳胆囊；后部有下腔静脉通过。左纵沟前部容纳肝圆韧带，后部为静脉韧带；动脉韧带位于肺动脉与主动脉弓之间，不在肝的沟内"},{"q":"双侧收缩使头后仰的肌肉是","o":["胸锁乳突肌","二腹肌","前斜角肌","肩胛舌骨肌","颈阔肌"],"a":0,"e":"胸锁乳突肌起自胸骨柄和锁骨内侧端，止于乳突，单侧收缩使头向同侧屈并转向对侧，两侧同时收缩则使头后仰。二腹肌和肩胛舌骨肌为舌骨相关肌，主下拉舌骨；前斜角肌屈颈；颈阔肌为浅层皮肌"},{"q":"支配表情肌的神经核是","o":["疑核","孤束核","面神经核","展神经核","动眼神经核"],"a":2,"e":"面神经核位于脑桥，属特殊内脏运动核，其轴突组成面神经的运动根，支配全部表情肌。疑核支配咽喉肌；孤束核接受味觉和内脏感觉；展神经核支配外直肌；动眼神经核支配大部分眼外肌"},{"q":"关于颈内动脉，错误的是","o":["是颈总动脉的分支","在颅外没有分支","起始处膨大部是化学感受器","营养脑","营养视器"],"a":2,"e":"颈内动脉起自颈总动脉，在颅外无分支，经颈动脉管入颅营养脑和视器。其起始处的膨大部为颈动脉窦，是压力感受器；颈动脉体才是化学感受器，位于颈总动脉分叉处，故该项张冠李戴"},{"q":"下列不属于硬脑膜窦的是","o":["上矢状窦","下矢状窦","海绵窦","乙状窦","冠状窦"],"a":4,"e":"硬脑膜窦包括上矢状窦、下矢状窦、海绵窦、乙状窦、横窦、直窦等，由硬脑膜两层分开形成。冠状窦位于心的冠状沟内，收集心壁大部分静脉血并注入右心房，属心的静脉结构，不是硬脑膜窦"},{"q":"肺下界在锁骨中线处相交于","o":["第6肋","第7肋","第8肋","第9肋","第10肋"],"a":0,"e":"肺下界在体表投影为：锁骨中线处平第6肋，腋中线处平第8肋，肩胛线处平第10肋。胸膜下界比肺下界低一肋，故第8、第10肋分别为腋中线和肩胛线肺下界，而非锁骨中线水平"},{"q":"关于右心房描述正确的是","o":["参与构成心的右侧缘","有四入口和一出口","壁厚而腔小","出生以后可见卵圆孔","向右前方突出形成右心耳"],"a":0,"e":"右心房位于心的右上部，构成心的右侧缘，向右前方突出形成右心耳。右心房有三个入口和一个出口，壁薄腔大；卵圆孔出生后闭为卵圆窝，成人不复见；壁厚腔小为左心室特征"},{"q":"属于腹膜内位器官的是","o":["胃","膀胱","升结肠","降结肠","输尿管"],"a":0,"e":"胃四周几乎全被腹膜包裹，属腹膜内位器官，活动度较大。膀胱和升、降结肠为腹膜间位器官，仅大部分被覆腹膜；输尿管位于腹膜后隙，属腹膜外位器官，均非内位"},{"q":"关于脑的静脉，以下说法错误的是","o":["一般不与动脉伴行","有瓣膜","分为浅、深两组","浅组收集皮质的静脉血","经硬脑膜窦回流"],"a":1,"e":"脑的静脉一般不与动脉伴行，无瓣膜，分为浅、深两组，浅组收集皮质及皮质下静脉血，深组收集髓质静脉血，最后均汇入硬脑膜窦。有瓣膜是四肢静脉的特点，脑静脉没有瓣膜，故该项错误"},{"q":"属于混合性的神经为","o":["耳大神经","颈横神经","枕小神经","锁骨上神经","膈神经"],"a":4,"e":"膈神经由颈3至颈5脊神经前支组成，含运动纤维支配膈肌，也含感觉纤维分布于胸膜、心包和膈下面，属混合性神经。耳大神经、颈横神经、枕小神经和锁骨上神经均为颈丛的皮支，只传导感觉"},{"q":"下丘脑的主要功能不包括","o":["皮质下内脏活动调节","随意运动调节","体温调节","昼夜节律调节","摄食行为调节"],"a":1,"e":"下丘脑是内脏活动的高级中枢，参与体温、摄食、水平衡、昼夜节律及皮质下内脏活动调节，并联系内分泌与自主神经。随意运动的调节由大脑皮质运动区、基底核和小脑完成，不属下丘脑功能"},{"q":"不属于髋骨体表标志的是","o":["髂前上棘","髂窝","耻骨结节","髂结节","坐骨结节"],"a":1,"e":"髋骨由髂骨、坐骨和耻骨融合而成，髂前上棘、髂结节、耻骨结节和坐骨结节均为可在体表触及的骨性标志。髂窝是髂骨翼内面的浅凹，为肌肉附着处，位置深在，不能触及，不属体表标志"},{"q":"与上颌磨牙邻近的鼻旁窦是","o":["额窦","上颌窦","蝶窦","筛窦前、中小房","筛窦后小房"],"a":1,"e":"上颌窦位于上颌骨体内，窦底与上颌第二前磨牙及第一、二磨牙根尖相邻，故上颌磨牙病变常累及此窦。额窦位于额骨内；蝶窦在蝶骨体内；筛窦前中房开口于中鼻道，后房开口于上鼻道，均不与上颌磨牙紧邻"},{"q":"颅内压增高时，以个哪个结构最有可能被挤入小脑幕切迹与中脑之间而形成脑疝","o":["小脑蚓","小脑扁桃体","小脑下脚","颞横回","海马旁回"],"a":4,"e":"颞叶的海马旁回和钩位于小脑幕切迹上方，颅内压增高时被推入小脑幕切迹与中脑之间，形成小脑幕切迹疝，压迫中脑和动眼神经。小脑扁桃体下疝形成枕骨大孔疝；小脑蚓、下脚和颞横回不是该疝的结构"},{"q":"关于左心房描述正确的是","o":["构成心底","入口为肺动脉口","出口周围有三尖瓣","向左前突出为左心耳","后方无食管通过"],"a":0,"e":"左心房位于右心房左后方，主要构成心底，其后壁有肺静脉口，前下方有左房室口通左心室，口周附二尖瓣。肺动脉口为右心室出口；三尖瓣位于右房室口；左房后方有食管胸段经过，均与该房不符"},{"q":"下列关于肌形态和构造的描述，错误的是","o":["骨骼肌包括肌腹和肌腱两部分","四肢骨骼肌多为短肌","肌腹主要由肌纤维组成","肌腱由胶原纤维组成","肌腹一般以肌腱附着于骨"],"a":1,"e":"骨骼肌由肌腹和肌腱构成，肌腹主要由肌纤维组成，肌腱由胶原纤维构成，肌腹借肌腱附着于骨。四肢肌多为长肌，跨越关节产生大幅运动；短肌多见于躯干深层，故四肢骨骼肌多为短肌的说法错误"},{"q":"关于腋动脉的描述，错误的是","o":["在第1肋外侧缘接锁骨下动脉","在大圆肌下缘续肱动脉","在腋窝内被臂丛三束包裹","其内侧有同名静脉伴行","腋动脉没有分支到胸大肌"],"a":4,"e":"腋动脉在第1肋外侧缘续锁骨下动脉，在大圆肌下缘移行为肱动脉，行于腋窝内被臂丛三束包绕，内侧有腋静脉伴行。其分支胸肩峰动脉、胸外侧动脉营养胸大肌等，故无分支到胸大肌的说法错误"},{"q":"关于胸椎叙述正确的是","o":["关节突呈矢状位","椎体小","椎孔最大","有肋凹","棘突呈方板状"],"a":3,"e":"胸椎椎体侧面和横突末端分别有椎体肋凹和横突肋凹，与肋头、肋结节相关节，是胸椎的特征。胸椎关节突呈冠状位；椎体较大、椎孔较小；棘突向后下方倾斜呈叠瓦状，方板状棘突为腰椎特点"},{"q":"使瞳孔扩大的肌是","o":["眼轮匝肌","瞳孔开大肌","瞳孔括约肌","内直肌","上睑提肌"],"a":1,"e":"瞳孔开大肌位于虹膜放射状排列，受交感神经支配，收缩时牵拉瞳孔缘向外使瞳孔扩大。瞳孔括约肌环状排列，由副交感支配使瞳孔缩小；眼轮匝肌闭眼；内直肌使眼球内收；上睑提肌上提眼睑"},{"q":"感光最敏锐之处是","o":["黄斑","中央凹","视神经盘","视神经乳头","虹膜"],"a":1,"e":"中央凹位于视网膜黄斑中心，此处只有密集的视锥细胞，无视杆细胞，是视力最敏锐的部位。黄斑为中央凹周围区域，敏锐度略低；视神经盘即视神经乳头，为视神经穿出部位，无感光细胞，是生理盲点"},{"q":"房水产生过多，可造成眼内压升高，压迫视网膜，影响视力称","o":["白内障","麦粒肿","霰粒肿","青光眼","沙眼"],"a":3,"e":"房水由睫状体产生，若回流受阻或生成过多致眼内压升高，压迫视网膜和视神经，引起视力下降和视野缺损，称青光眼。白内障为晶状体混浊；麦粒肿是睑腺急性化脓性炎症；霰粒肿为睑板腺囊肿；沙眼由沙眼衣原体引起"},{"q":"关于脑膜中动脉的描述正确的是","o":["是分布到脑的动脉之一","是颈外动脉的直接分支","穿卵圆孔入颅腔","发自上颌动脉","翼点损伤时脑膜中动脉主干也会损伤"],"a":3,"e":"脑膜中动脉起自上颌动脉，经棘孔入颅，主要分布于硬脑膜，其前支经过翼点内面。它不分布于脑实质；穿卵圆孔的是下颌神经；它属颈外动脉的间接分支而非直接分支；翼点骨折易伤其前支而非主干"},{"q":"有关主动脉的描述何者有误","o":["是体循环的动脉主干","其内流动的是含C02量高的血液","全长分升主动脉、主动脉弓和降主动脉","末端在第4腰椎下缘分为左、右髂总动脉","起自左心室的主动脉口"],"a":1,"e":"主动脉是体循环的动脉主干，起自左心室主动脉口，内流动脉血，含氧丰富、二氧化碳少，全长分升主动脉、主动脉弓和降主动脉，末端在第4腰椎下缘分为左右髂总动脉。含二氧化碳高的血液在肺动脉和右心"},{"q":"骶管麻醉的穿刺部位应在","o":["骶前孔","骶后孔","骶管裂孔","骶角","骶岬"],"a":2,"e":"骶管裂孔是骶管下端的开口，由第4、5骶椎椎弓未愈合形成，两侧有骶角，是骶管麻醉的穿刺部位。骶前孔、骶后孔为神经根穿出孔；骶角是定位标志而非穿刺点；骶岬为骶骨上缘前突"},{"q":"有关冠状窦的描述，错误的是","o":["位于心膈面的冠状沟内","心大静脉是其属支之一","收集心的全部静脉血","注入到右心房","有心中和心小静脉注入"],"a":2,"e":"冠状窦位于心膈面冠状沟内，收集心大部分静脉血，主要属支有心大静脉、心中静脉和心小静脉，最终注入右心房。心前静脉等部分静脉直接注入右心房，不经冠状窦，故收集全部静脉血的说法错误"},{"q":"支配三角肌的神经为","o":["腋神经","正中神经","尺神经","桡神经","肌皮神经"],"a":0,"e":"腋神经发自臂丛后束，绕肱骨外科颈至三角肌深面，支配三角肌和小圆肌，并管理肩部皮肤感觉。正中神经支配前臂屈肌；尺神经支配手内在肌；桡神经支配伸肌；肌皮神经支配臂前群屈肌"},{"q":"运动性语言中枢位于","o":["额中回","颞横回","缘上回","角回","Broca区"],"a":4,"e":"运动性语言中枢即说话中枢，位于额下回后部，称Broca区，损伤后能理解语言但不能表达，称运动性失语。额中回后部为书写中枢；颞横回为听觉中枢；缘上回为运用中枢；角回为阅读中枢"},{"q":"支配心肌的副交感神经节前神经元的胞体位于","o":["孤束核","迷走神经背核","上泌涎核","脊髓骶部第2～4节段灰质的骶副交感核","脊髓T1～L3节段的侧角"],"a":1,"e":"心脏的副交感节前神经元胞体位于延髓迷走神经背核，其纤维随迷走神经至心内神经节换元，节后纤维支配心肌，使心率减慢。孤束核接受内脏感觉；上泌涎核支配泪腺等分泌；骶副交感核支配盆腔脏器；侧角为交感中枢"},{"q":"无系膜的肠管是","o":["空肠","盲肠","阑尾","横结肠","乙状结肠"],"a":1,"e":"盲肠位于右髂窝，为腹膜间位器官，位置固定，无系膜。空肠、横结肠和乙状结肠均由系膜悬吊，活动度较大；阑尾也有阑尾系膜，故只有盲肠无系膜"},{"q":"下列结构属于鼓室后壁的是","o":["前庭窗","蜗窗","咽鼓管的开口","面神经管凸","乳突窦的开口"],"a":4,"e":"鼓室后壁又称乳突壁，上部有乳突窦入口，向后通乳突小房，是鼓室后壁的特征结构。前庭窗和蜗窗位于内侧壁；咽鼓管开口位于前壁；面神经管凸也在内侧壁，均不属后壁"},{"q":"下列关于脊髓的描述，正确的是","o":["中央管上直接通第三脑室","主要由灰质构成","灰质围绕在白质周围","白质可分为前索、外侧索和后索","网状结构位于两前角之间"],"a":3,"e":"脊髓白质位于灰质周围，借灰质连合和神经根分为前索、外侧索和后索三系，内含上行和下行的神经纤维束。脊髓中央管上通第四脑室；灰质在内呈蝶形、白质在外；网状结构位于灰质连合周围，均与该描述不符"},{"q":"有关肌的辅助装置的描述，正确的是","o":["浅筋膜又称固有筋膜","滑膜囊都独立存在","人体内长肌腱周围均有腱鞘","肌间隔和筋膜鞘均为深筋膜形成的结构","籽骨不是辅助结构"],"a":3,"e":"深筋膜包裹肌肉并形成肌间隔、筋膜鞘及骨筋膜鞘，构成肌的辅助装置。浅筋膜又称皮下筋膜，固有筋膜为深筋膜；滑膜囊有的与关节腔相通，非都独立；只有长肌腱周围有腱鞘；籽骨属辅助结构"},{"q":"下列关于桡腕关节的叙述中，正确的是","o":["由桡、尺骨下端构成关节窝","由腕骨近侧列的手舟骨、月骨、三角骨和豌豆骨的近侧面组成关节头","关节囊的两侧有桡、尺侧副韧带加强","可做屈伸、收展和环转运动","关节内没有关节盘等辅助结构"],"a":3,"e":"桡腕关节由桡骨下端和尺骨下方的关节盘构成关节窝，舟骨、月骨、三角骨近侧面构成关节头，属椭圆关节，可做屈伸、收展和环转运动。豌豆骨不参与关节头构成；尺骨不直接参与关节窝；关节内有三角纤维软骨盘"},{"q":"下列属于女性内生殖器的是","o":["阴阜","阴蒂","前庭大腺","小阴唇","前庭球"],"a":2,"e":"女性内生殖器包括卵巢、输卵管、子宫、阴道及附属腺，前庭大腺为附属腺，位于前庭两侧，开口于阴道前庭。阴阜、阴蒂、小阴唇和前庭球均为女性外生殖器的组成部分，不属内生殖器"},{"q":"肩胛下角约平对","o":["第2肋","第4肋","第5肋","第6肋","第7肋"],"a":4,"e":"肩胛下角为肩胛骨最下角，直立时约平第7肋或第7肋间隙，是背部计数肋骨和椎骨的标志。第2肋平胸骨角，由前方可触；乳房投影多在第4、5肋间隙；计数时以第7肋为准"},{"q":"成人肾门约平","o":["第11胸推体下缘","第12胸推体中份","第1腰椎体","第2腰椎体下缘","第3腰椎体中份"],"a":2,"e":"肾门是肾内侧缘中部的凹陷，为肾动静脉、神经、淋巴管和肾盂出入处，成人约平第1腰椎体水平。第11、12胸椎位置过高，第2腰椎下缘和第3腰椎过低，均不符合肾门的体表定位"},{"q":"有关迷走神经的叙述，错误的是","o":["为第Ⅹ对脑神经","属混合性神经","特殊内脏运动纤维支配咽喉肌","可分布于外耳道的皮肤","损伤后患者可出现心动过缓症状"],"a":4,"e":"迷走神经为第Ⅹ对脑神经，属混合性神经，特殊内脏运动纤维支配咽喉肌，并分布于外耳道皮肤。其副交感纤维使心率减慢、支气管收缩，损伤后迷走作用减弱，出现心动过速而非心动过缓，故该项错误"},{"q":"两肺根内的结构排列自前向后依次为","o":["上肺静脉、肺动脉和主支气管","肺动脉、上肺静脉和主支气管","肺动脉、主支气管和下肺静脉","上肺静脉、主支气管和肺动脉","主支气管、下肺静脉和肺动脉"],"a":0,"e":"肺根内结构排列有规律，自前向后为上肺静脉、肺动脉、主支气管，故前为静脉、中为动脉、后为支气管。自上而下左右略有差异，但从前向后的静脉、动脉、支气管顺序恒定，其他排列均与前后关系不符"},{"q":"距小腿关节最不稳定的状态是","o":["足背屈","足跖屈","足内翻","足外翻","足背伸"],"a":1,"e":"距小腿关节在足跖屈时，距骨较窄的后部进入踝穴，关节松动，稳定性下降，易发生内翻扭伤。背屈时距骨较宽的前部嵌入踝穴，关节稳定；内翻、外翻为距下关节运动，不是踝关节最不稳定位"},{"q":"关于上腔静脉，下列描述正确的是","o":["入心前接受奇静脉","起自右腰升静脉","半奇静脉直接注入","注入左心房","由颈内静脉和锁骨下静脉汇合而成"],"a":0,"e":"上腔静脉由左右头臂静脉汇合而成，沿升主动脉右侧下行，注入右心房，入心前接受奇静脉。起自右腰升静脉的是奇静脉；半奇静脉注入奇静脉；左右头臂静脉由颈内静脉与锁骨下静脉合成，非上腔静脉"},{"q":"下列哪块肌为主要呼吸肌","o":["胸大肌","膈肌","背阔肌","腹直肌","腹外斜肌"],"a":1,"e":"膈肌为向上膨隆的扁薄阔肌，分隔胸腔与腹腔，是主要的呼吸肌，收缩时穹窿下降增大胸腔容积而吸气。胸大肌、背阔肌为上肢带肌，腹直肌和腹外斜肌主要参与呼气，均非主要吸气肌"},{"q":"旧纹状体是指","o":["基底核","尾状核头","尾状核尾","豆状核的壳","苍白球"],"a":4,"e":"纹状体分新、旧两部分，苍白球在种系发生上出现较早，称旧纹状体；壳和尾状核出现较晚，称新纹状体。基底核还包括豆状核、尾状核、屏状核和杏仁体，尾状核头和尾、豆状核的壳均属新纹状体"},{"q":"运动上眼睑的肌是","o":["上睑提肌","眼轮匝肌","上直肌","下直肌","内直肌"],"a":0,"e":"上睑提肌起自眶上壁，止于上睑板，由动眼神经支配，收缩时上提上睑、开大眼裂。眼轮匝肌由面神经支配，作用是闭眼；上直肌、下直肌和内直肌为眼球外肌，使眼球转动，均不提上睑"},{"q":"食管第三个狭窄约平第几胸椎","o":["8","9","10","11","12"],"a":4,"e":"官方答案为【12】，但依据教材，正确答案为【10】。食管第三狭窄位于穿膈食管裂孔处，约平第10胸椎，距中切牙约40厘米；第12胸椎水平为主动脉裂孔，通过主动脉和胸导管，并非食管狭窄所在"},{"q":"下列属于男性附属腺的是","o":["睾丸","附睾","前列腺","肾上腺","前庭大腺"],"a":2,"e":"男性附属腺包括前列腺、精囊和尿道球腺，其分泌物参与组成精液。睾丸为生殖腺，产生精子并分泌雄激素；附睾为储存和输送精子的管道；肾上腺属内分泌腺；前庭大腺为女性附属腺"},{"q":"头面部浅感觉传导通路的第2级神经元是","o":["三叉神经节","脊神经节","侧角细胞","三叉神经脊束核和脑桥核","薄束核和楔束核"],"a":3,"e":"头面部浅感觉第一级神经元胞体在三叉神经节，其中枢突入脑后，传导痛温觉的止于三叉神经脊束核，传导触觉的止于三叉神经脑桥核，二者为第二级神经元。脊神经节为躯干四肢感觉第一级；薄束核、楔束核为深感觉第二级"},{"q":"关于椎弓的说法，错误的是","o":["位于椎体的后方","呈半环状","与椎体共同围成椎孔","由一对椎弓板构成","相邻椎弓间有黄韧带"],"a":3,"e":"椎弓位于椎体后方，呈半环状，由一对椎弓根和一对椎弓板共同构成，与椎体围成椎孔，并发出七个突起，相邻椎弓间借黄韧带相连。仅说由一对椎弓板构成遗漏椎弓根，也不能说明椎孔的形成，故该项错误"},{"q":"有关颈内动脉的描述，何者正确","o":["在环状软骨上缘发自颈总动脉","在颈部分支很少","经颈动脉管入颅前窝","经颈动脉管入颅中窝","分支营养脑的全部"],"a":3,"e":"颈内动脉在甲状软骨上缘起自颈总动脉，颈部无分支，经颞骨岩部的颈动脉管入颅中窝，主要营养脑前部和视器。环状软骨为喉的标志，非其起点；入颅前窝说法错误；脑的全部由颈内动脉和椎动脉共同供应"},{"q":"有关室间隔的描述，何者错误","o":["分隔左、右心室","分膜部和肌部两部","膜部是缺损的好发部位","肌部内有心房肌","室间隔缺损占先天性心脏病约17、8%"],"a":3,"e":"室间隔分隔左右心室，分膜部和肌部，膜部薄小为室间隔缺损好发部位，肌部由心室肌构成。心房肌位于心房壁，不在室间隔肌部内，故该项错误；室间隔缺损约占先天性心脏病的一定比例，说法可成立"},{"q":"支配瞳孔括约肌的脑神经核是","o":["动眼神经副核","动眼神经核","滑车神经核","展神经核","疑核"],"a":0,"e":"动眼神经副核位于中脑，属副交感核，其节前纤维随动眼神经至睫状神经节换元，节后纤维支配瞳孔括约肌和睫状肌，使瞳孔缩小。动眼神经核支配大部分眼外肌；滑车神经核和展神经核分别支配上斜肌、外直肌；疑核支配咽喉肌"},{"q":"关于大网膜的描述，正确的是","o":["是双层腹膜结构","连于胃大弯与横结肠之间","内有脾动脉通过","包裹腹腔器官","右上缘有一网膜孔"],"a":1,"e":"大网膜自胃大弯和十二指肠上部下垂，连于横结肠，由四层腹膜折叠而成，内含胃网膜左右动脉，具有包裹炎症、限制扩散的作用。双层结构、脾动脉通过、右上缘网膜孔均为小网膜或肝十二指肠韧带的特点"},{"q":"参与构成肋弓的肋软骨是","o":["第7～9肋软骨","第6～9肋软骨","第8～10肋软骨","第8～11肋软骨","第9～12肋软骨"],"a":2,"e":"第8至第10肋软骨依次与上位肋软骨相连，形成肋弓，是胸廓下口的重要标志。第7肋软骨直接连胸骨，参与构成胸廓但不组成肋弓；第11、12肋为浮肋，前端游离，不参与肋弓构成"},{"q":"椎动脉的描述何者有误","o":["发自锁骨下动脉上壁","途经第1～6颈椎横突孔","经枕骨大孔入颅","分布于脑和脊髓","分布至脑的大部分"],"a":4,"e":"椎动脉起自锁骨下动脉上壁，穿第1至第6颈椎横突孔，经枕骨大孔入颅，主要分布于脑干、小脑及大脑枕叶等，与颈内动脉共同构成脑的供血。脑的大部分由颈内动脉供应，椎动脉供血范围较小，故该项错误"},{"q":"关于胃的位置，描述正确的是","o":["胃后壁邻膈、脾","中等充盈时，大部分位于腹上区","临床上胃触诊的部位在剑突下方","贲门位于第12胸椎体的左侧","胃前壁的左侧被肝左叶遮盖"],"a":2,"e":"胃中等充盈时大部分位于左季肋区，小部分在腹上区，临床上胃触诊部位在剑突下方。胃后壁邻接胰、脾、左肾等，不邻膈；贲门约平第11胸椎左侧；胃前壁右侧部被肝左叶遮盖，左侧部与腹前壁相贴"},{"q":"由四层腹膜形成的结构是","o":["肝十二指肠韧带","肝胃韧带","大网膜","子宫阔韧带","小网膜"],"a":2,"e":"大网膜由胃前后壁的腹膜向下延伸，返折至横结肠，共四层腹膜折叠而成。肝十二指肠韧带和肝胃韧带构成小网膜，为双层腹膜；子宫阔韧带为双层腹膜皱襞，均非四层结构"},{"q":"不含味蕾的结构是","o":["丝状乳头","轮廓乳头","软腭的黏膜上皮","叶状乳头","菌状乳头"],"a":0,"e":"舌乳头中丝状乳头数量最多，遍布舌背，表面有角化上皮，不含味蕾，主司一般感觉。菌状乳头、轮廓乳头和叶状乳头均含味蕾，感受味觉；软腭黏膜上皮内也散在味蕾，故只有丝状乳头无味蕾"},{"q":"以下对内脏感觉神经描述错误的是","o":["痛阈较低","定位不准","内脏感觉神经元的细胞形态也是假单极神经元","传导内脏感觉的脑神经节细胞的中枢突终止于孤束核","内脏感觉神经元的周围突是粗细不等的有髓或无髓纤维"],"a":0,"e":"内脏感觉神经元的胞体为假单极神经元，周围突为粗细不等的有髓或无髓纤维，随交感和副交感神经走行，脑神经节细胞的中枢突终止于孤束核。其特点是痛阈较高、对牵拉等刺激敏感且定位不准，故痛阈较低的说法错误"},{"q":"关于脾的描述，正确的是","o":["与右肾相邻","位于右季肋区","长轴与第10肋一致","位于右侧第9～11肋深面","正常情况下在肋弓下可触及脾脏"],"a":2,"e":"脾位于左季肋区胃底与膈之间，被第9至第11肋掩盖，长轴与第10肋一致，正常情况下肋弓下不能触及。脾与左肾、胃底相邻，不在右季肋区或右侧肋深面，故相关描述均错误"},{"q":"对肾的描述，错误的是","o":["是泌尿器官","左肾低于右肾","有三层被膜","内侧缘中部有肾门","内部有肾窦"],"a":1,"e":"肾为泌尿器官，左肾约平第11胸椎至第2腰椎，右肾因受肝影响比左肾低半个椎体，故左肾高于右肾。肾有纤维囊、脂肪囊、肾筋膜三层被膜，内侧缘中部有肾门，内部有肾窦，故左肾低于右肾的说法错误"},{"q":"下列关于脑脊液的描述，正确的是","o":["位于硬脊膜与蛛网膜之间","充满蛛网膜下腔","经室间孔流入硬脑膜窦","经蛛网膜流入下矢状窦","充满硬膜外隙"],"a":1,"e":"脑脊液由脉络丛产生，充满脑室和蛛网膜下腔，最终经蛛网膜粒渗入硬脑膜窦。硬膜外隙位于硬脊膜与椎管骨壁之间，不含脑脊液；硬脑膜与蛛网膜之间为硬膜下隙；室间孔连通脑室，不直接通硬脑膜窦"},{"q":"阑尾动脉来自","o":["中结肠动脉","回结肠动脉","右结肠动脉","空肠动脉","回肠动脉"],"a":1,"e":"阑尾动脉起自回结肠动脉，为回结肠动脉的分支，沿阑尾系膜游离缘至阑尾尖端，是阑尾的血供来源。中结肠动脉供应横结肠；右结肠动脉供应升结肠；空肠动脉、回肠动脉供应空回肠，均不发阑尾动脉"},{"q":"有关心的描述，错误的是","o":["心位于胸腔的中纵隔","心呈倒置的圆锥体","左右心房有卵圆孔相通","心包脏层构成心外膜","窦房结是特殊的心肌"],"a":2,"e":"心位于中纵隔，呈倒置圆锥体，心包脏层构成心外膜，窦房结为特殊分化的心肌。卵圆孔是胎儿期左右心房的通道，出生后闭合形成卵圆窝，成人左右心房不相通，故该项错误"},{"q":"眼动脉来自","o":["颈内动脉","颈外动脉","上颌动脉","面动脉","脑膜中动脉"],"a":0,"e":"眼动脉是颈内动脉穿出海绵窦后发出的分支，经视神经管入眶，供应眼球及眶内结构。颈外动脉主要分支为面动脉、上颌动脉、颞浅动脉等，不发出眼动脉；上颌动脉虽也入眶发出眶下动脉等，但眼动脉本体源自颈内动脉。脑膜中动脉是上颌动脉的分支，供应硬脑膜，面动脉分布面部"},{"q":"使踝关节跖屈和足内翻的肌群是","o":["小腿前群","小腿后群","小腿外侧群","足底肌","足背肌"],"a":1,"e":"小腿后群肌包括小腿三头肌、胫骨后肌、趾长屈肌等，由胫神经支配，收缩时使踝关节跖屈并使足内翻。小腿前群肌使足背屈、内翻；小腿外侧群肌（腓骨长、短肌）使足外翻并协助跖屈；足底肌、足背肌主要作用于足趾，力量弱，不是踝关节运动的主力"},{"q":"胫骨下端的主要骨性标志是","o":["内踝","胫骨粗隆","内侧髁","外侧髁","臀肌粗隆"],"a":0,"e":"胫骨下端内侧向下突出形成内踝，参与构成踝关节，是重要的骨性标志，可在体表触及。胫骨粗隆位于胫骨上端前面，为髌韧带止点；内侧髁、外侧髁位于胫骨上端参与膝关节构成；臀肌粗隆位于股骨而非胫骨，这些均不在胫骨下端"},{"q":"属于腹膜间位器官的是","o":["脾","肝","胃","胰","肾"],"a":1,"e":"肝大部分被腹膜覆盖，仅膈面后部裸区无腹膜，属腹膜间位器官。脾、胃为腹膜内位器官，四周几乎全被腹膜包被；胰和肾为腹膜外位器官，仅前面有腹膜覆盖。腹膜间位器官还包括升结肠、降结肠、胆囊、子宫和膀胱等"},{"q":"与面静脉交通的硬脑膜窦是","o":["上矢状窦","下矢状窦","海绵窦","乙状窦","直窦"],"a":2,"e":"面静脉经眼上静脉、眼下静脉与海绵窦相交通，且面静脉缺少静脉瓣，故面部感染可逆行蔓延至海绵窦引起海绵窦血栓。上矢状窦、下矢状窦、直窦位于大脑镰附近，乙状窦续接横窦并移行为颈内静脉，均不与面静脉直接交通"},{"q":"淋巴干共有几条","o":["共5条","共6条","共7条","共8条","共9条"],"a":4,"e":"全身共有9条淋巴干，即左、右颈干，左、右锁骨下干，左、右支气管纵隔干，左、右腰干和单一的肠干。它们最终汇合成胸导管和右淋巴导管。5、6、7、8条均少于实际数目，其中胸导管接受6条淋巴干（含肠干），右淋巴导管接受3条"},{"q":"下列关于卵巢的描述，正确的是","o":["下端与盆壁之间有卵巢悬韧带","上端与子宫之间有卵巢固有韧带","位于小骨盆腔内","后缘有卵巢系膜","为腹膜外位器官"],"a":2,"e":"卵巢位于小骨盆腔内、髂内外动脉分叉处，为腹膜内位器官。卵巢上端称输卵管端，与卵巢悬韧带相连；下端为子宫端，借卵巢固有韧带连于子宫。卵巢前缘有卵巢系膜附着，后缘游离。腹膜外位之说与卵巢实际被腹膜包被不符，悬韧带和固有韧带的连接部位常被颠倒设错"},{"q":"不属于腹膜外位器官的是","o":["十二指肠水平部","肾","输尿管","输卵管","胰"],"a":3,"e":"输卵管为腹膜内位器官，四周被腹膜包被，故不属于腹膜外位器官。肾、输尿管为典型腹膜外位器官，仅前面覆以腹膜；胰为腹膜外位器官；十二指肠水平部也属腹膜外位。这几者位置较固定、活动度小，与输卵管显著不同"},{"q":"关于主动脉叙述，错误的是","o":["起始于左心室的主动脉口","主动脉弓自右前方弯向左后方","自主动脉弓发出左、右头臂干","根据其行程可分为三部分","下端在第4腰椎高度分叉"],"a":2,"e":"主动脉弓凸缘自右向左发出头臂干、左颈总动脉和左锁骨下动脉三大分支，只有右侧存在头臂干，并不存在'右头臂干'与'左头臂干'并列，此说法错误。主动脉起自左心室主动脉口，弓自右前弯向左后，按升主动脉、主动脉弓、降主动脉分三部，下端在第4腰椎高度分叉，均正确"},{"q":"关于垂体的描述，错误的是","o":["借漏斗连于下丘脑","位于蝶骨的垂体窝内","分腺垂体和神经垂体两部分","腺垂体分远侧部、结节部和中间部","神经垂体能分泌加压素(抗利尿素)和催产素"],"a":4,"e":"神经垂体不含腺细胞，不能合成激素；加压素和催产素由下丘脑视上核、室旁核合成，经轴突运输至神经垂体储存释放，故此说法错误。垂体借漏斗连于下丘脑，位于蝶骨垂体窝内，分腺垂体和神经垂体，腺垂体又分远侧部、结节部和中间部，均正确"},{"q":"在延髓腹侧面上部，紧邻前正中裂的隆起是","o":["薄束结节","楔束结节","锥体","橄榄","下丘"],"a":2,"e":"延髓腹侧面前正中裂两侧的纵向隆起为锥体，由皮质脊髓束构成，其下端纤维大部交叉形成锥体交叉。薄束结节、楔束结节位于延髓背面，是薄束核、楔束核的隆起；橄榄位于锥体外侧，内含下橄榄核；下丘位于中脑，为听觉反射中枢"},{"q":"对膀胱三角的描述，错误的是","o":["膀胱三角底的两端为输尿管的开口","膀胱三角的尖为尿道内口","膀胱三角区的黏膜常保持平滑状态","黏膜层与肌层紧密结合","具有丰富的黏膜下层"],"a":4,"e":"膀胱三角位于两输尿管口与尿道内口之间，其黏膜与肌层紧密相连，缺少黏膜下层，故无论膀胱充盈或排空均保持平滑，'具有丰富黏膜下层'的说法错误。该三角底的两端为输尿管口，尖为尿道内口，是膀胱肿瘤和结核的好发部位"},{"q":"关于小腿三头肌的描述，正确的是","o":["由腓骨长肌和比目鱼肌构成","比目鱼肌起自股骨内、外侧髁","以跟腱止于跟骨结节","主要作用是伸膝关节和使足跖屈","还可使足内翻"],"a":2,"e":"小腿三头肌由腓肠肌内、外侧头和比目鱼肌构成，三头合成跟腱止于跟骨结节，故该描述正确。比目鱼肌起自胫、腓骨后面（不是股骨髁）；腓肠肌起自股骨内、外侧髁；该肌主要使踝跖屈，屈膝由腓肠肌辅助，足内翻主要由胫骨后肌完成"},{"q":"精索内含有","o":["射精管","输精管","附睾管","精曲小管","精囊排泄管"],"a":1,"e":"精索为自腹股沟深环至睾丸上端的柔软索状结构，内含输精管、睾丸动脉、蔓状静脉丛、神经、淋巴管及鞘韧带等，输精管是其核心内容。射精管由输精管末端与精囊排泄管合成并穿前列腺；附睾管位于附睾内，精曲小管位于睾丸内，均不在精索中"},{"q":"皮质下内脏活动中枢是","o":["背侧丘脑","后丘脑","下丘脑","上丘","下丘"],"a":2,"e":"下丘脑是调节内脏活动的高级中枢，内含体温、摄食、饮水、血糖等调节中枢，并通过垂体联系神经与内分泌。背侧丘脑为感觉接替中枢；后丘脑含内侧膝状体、外侧膝状体，分别属听觉和视觉中枢；上丘、下丘分别为视觉和听觉反射中枢，均非内脏活动中枢"},{"q":"声门裂位于","o":["两侧喉室之间","两侧声襞及杓状软骨基底部之间","两侧声韧带之间","两侧前庭襞之间","方形膜的下缘"],"a":1,"e":"声门裂是两侧声襞及杓状软骨基底之间的裂隙，为喉腔最狭窄处，分膜间部和软骨间部。两侧前庭襞之间为前庭裂，位于声门裂上方；两侧喉室是声襞与前庭襞之间的隐窝；声韧带是声襞内的韧带；方形膜下缘构成前庭韧带，均非声门裂本身"},{"q":"下面哪个孔不位于颅中窝","o":["破裂孔","棘孔","颈静脉孔","圆孔","卵圆孔"],"a":2,"e":"颈静脉孔位于颞骨与枕骨之间，属于颅后窝，有舌咽、迷走、副神经及颈内静脉通过，故不位于颅中窝。破裂孔、棘孔、卵圆孔、圆孔均位于颅中窝：卵圆孔通下颌神经，圆孔通上颌神经，棘孔通脑膜中动脉，分别归属明确"},{"q":"呈双凸透镜状，有屈光作用的结构是","o":["晶状体","房水","角膜","玻璃体","虹膜"],"a":0,"e":"晶状体呈双凸透镜状，透明无血管，富有弹性，是眼球屈光系统的重要组成部分，借睫状肌改变曲度以调节焦距。房水为充满眼房的液体；角膜为眼球纤维膜前部的透明部分；玻璃体为胶状物填充于晶状体之后；虹膜为血管膜前部，中央有瞳孔，均非双凸镜状"},{"q":"一侧内侧丘系传导的感觉信息主要是","o":["同侧躯干、四肢意识性深感觉和精细触觉","对侧躯干、四肢意识性深感觉和精细触觉","同侧躯干、四肢意识性浅感觉","对侧躯干、四肢意识性浅感觉","双侧听觉"],"a":1,"e":"内侧丘系由薄束核、楔束核发出的纤维在延髓交叉后上行而成，故一侧内侧丘系传导对侧躯干、四肢的意识性本体感觉和精细触觉，止于丘脑腹后外侧核。同侧深感觉说法与交叉事实不符；痛温觉由脊髓丘系传导，听觉由外侧丘系传导，均不属内侧丘系"},{"q":"发自臂丛后束的神经为","o":["肌皮神经","腋神经","正中神经","尺神经","前臂内侧皮神经"],"a":1,"e":"腋神经发自臂丛后束，与旋肱后动脉伴行穿四边孔，支配三角肌和小圆肌，并管理肩部皮肤感觉。后束还发出桡神经；肌皮神经发自外侧束；正中神经由内、外侧束合成；尺神经和前臂内侧皮神经均发自内侧束，均非后束分支"},{"q":"关于掌浅弓的描述何者有误","o":["位于掌腱膜的深面","位于掌腱膜的浅面","由桡动脉的掌浅支和尺动脉的终支组成","弓上发出指掌侧总动脉","掌浅弓与掌深弓互相吻合"],"a":1,"e":"掌浅弓位于掌腱膜深面、指屈肌腱浅面，由尺动脉终支与桡动脉掌浅支吻合而成，故'位于掌腱膜浅面'有误。该弓发出指掌侧总动脉，并与掌深弓相互吻合。掌深弓由桡动脉终支与尺动脉掌深支构成，位置较掌浅弓更深，二者层次不可混淆"},{"q":"关于腹股沟韧带的叙述，下列正确的是","o":["位于两侧髂前上棘之间","由腹内斜肌腱膜构成","由腹外斜肌腱膜下缘卷曲增厚构成","为腹股沟管前壁","参与腹股沟管浅环的构成"],"a":2,"e":"腹股沟韧带由腹外斜肌腱膜下缘向后、向下卷曲增厚形成，连接髂前上棘与耻骨结节。它并非位于两髂前上棘之间；构成腹股沟管前壁的是腹外斜肌腱膜而非此韧带；参与浅环构成的是腹外斜肌腱膜的裂孔，与该韧带不是同一结构"},{"q":"大腿内收肌群受什么神经支配","o":["臀上神经","臀下神经","闭孔神经","股神经","阴部神经"],"a":2,"e":"大腿内收肌群包括长收肌、短收肌、大收肌、股薄肌和耻骨肌，主要由闭孔神经支配（大收肌坐骨部另受坐骨神经支配）。臀上神经支配臀中、小肌，臀下神经支配臀大肌，股神经支配股四头肌和缝匠肌，阴部神经支配会阴部肌，均不支配内收肌群"},{"q":"直接连结与间接连结的最主要区别是","o":["连结的复杂程度","骨间有无间隙","骨间能否相互活动","骨间距离的远近","以上都不对"],"a":1,"e":"直接连结指骨与骨之间借纤维结缔组织或软骨直接相连，骨间无腔隙，活动度小或不活动；间接连结即滑膜关节，骨之间有腔隙（关节腔），可灵活运动，故最主要区别为骨间有无间隙。连结复杂程度、距离远近、能否活动均非分类的根本依据，能否活动只是有无间隙的结果"},{"q":"关于十二指肠大乳头的叙述，正确的是","o":["副胰管开口于大乳头","位于十二指肠降部的前壁中份","是十二指肠纵襞下端的圆形隆起","距中切牙约55cm","位于小乳头的上方"],"a":2,"e":"十二指肠大乳头是降部后内侧壁十二指肠纵襞下端的圆形隆起，为胆总管与胰管的共同开口处。副胰管开口于其上方的小乳头；大乳头位于降部后内侧壁而非前壁；距中切牙约75cm，55cm的说法错误；小乳头在大乳头上方，故大乳头位于小乳头下方"},{"q":"下列关于精索的描述，正确的是","o":["起于附睾尾","远端连于膀胱底","内含有射精管","穿过腹股沟管","全长可分为四部"],"a":3,"e":"精索自腹股沟管深环经腹股沟管出浅环，终于睾丸上端，故穿过腹股沟管。精索起于腹股沟管深环而非附睾尾，远端连于睾丸而非膀胱底；其内容为输精管、睾丸动脉等而不含射精管；精索分段并非固定为四部，这些表述均不准确"},{"q":"耻骨联合属于","o":["韧带连结","纤维连结","软骨连结","骨性结合","间接连结"],"a":2,"e":"耻骨联合由两侧耻骨联合面之间的纤维软骨盘连接而成，属直接连结中的软骨连结，女性在分娩时稍松弛以利胎儿娩出。颅骨的缝属纤维连结；桡、尺骨间借骨间膜相连，腕骨间多为微动关节；骨性结合如骶椎融合，间接连结则具关节腔，均与耻骨联合不同"},{"q":"下列关于皮质脊髓侧束的描述，正确的是","o":["支配对侧前角运动神经元","逐渐终于对侧板层Ⅳ～Ⅸ","所有纤维都终于中间神经元","在脊髓侧索前部下行","一侧损伤出现同侧肢体随意运动障碍"],"a":4,"e":"皮质脊髓束在延髓锥体交叉后，大部分纤维进入脊髓侧索形成皮质脊髓侧束，支配同侧前角运动神经元，故一侧损伤表现为同侧肢体随意运动障碍。该束在脊髓侧索后部下行，终于同侧前角；部分纤维经中间神经元中继，但并非全部；支配对侧的说法与锥体交叉后的走行不符"},{"q":"关于鼻腔，下列说法正确的是","o":["经鼻后孔通喉腔","鼻中隔由软骨构成","鼻腔被鼻中隔分为左、右两个腔","外侧壁有4个鼻道","中鼻甲下方是下鼻道"],"a":2,"e":"鼻腔由鼻中隔分为左、右两腔，各腔经鼻后孔通鼻咽，经鼻前孔通外界。鼻中隔由骨和软骨共同构成；外侧壁有上、中、下三个鼻甲及其下方的三个鼻道，而非四个；中鼻甲下方为中鼻道，下鼻道位于下鼻甲下方，这些部位常被混淆设错"},{"q":"主要由神经元细胞体构成的结构是","o":["神经束","纤维束","神经核","白质","神经"],"a":2,"e":"神经核是中枢神经系统内形态与功能相似的神经元胞体聚集成团的结构，故主要由胞体构成。神经束和神经由轴突聚集而成，属周围神经纤维集合；纤维束为中枢内轴突集合；白质由大量有髓神经纤维组成，均主要由轴突而非胞体构成"},{"q":"右心室内有","o":["右心耳","梳状肌","二尖瓣","动脉韧带","乳头肌"],"a":4,"e":"右心室腔内有肉柱、乳头肌、腱索和三尖瓣，前乳头肌尖端借腱索连于三尖瓣，故右心室内有乳头肌。右心耳和梳状肌位于右心房；二尖瓣位于左心室；动脉韧带连于主动脉弓与肺动脉干之间，均不在右心室内"},{"q":"直接发自椎动脉的动脉是","o":["小脑上动脑","大脑后动脉","后交通动脉","大脑中动脉","小脑下后动脉"],"a":4,"e":"小脑下后动脉是椎动脉颅内段最大的分支，直接起自椎动脉，供应小脑后下部及延髓。小脑上动脉起自基底动脉；大脑后动脉为基底动脉终支；后交通动脉连于颈内动脉与大脑后动脉之间；大脑中动脉是颈内动脉终支，均非椎动脉直接发出"},{"q":"左心室舒张时","o":["二尖瓣开放","三尖瓣关闭","主动脉瓣开放","肺动脉瓣开放","右心室收缩"],"a":0,"e":"左心室舒张时室内压低于左房压，二尖瓣开放，血液由左心房流入左心室，此时主动脉瓣关闭以防血液反流。三尖瓣开闭属右心活动；主动脉瓣、肺动脉瓣在心室收缩时开放、舒张时关闭；左右心室舒缩同步，左室舒张时右室亦舒张，'右心室收缩'不成立"},{"q":"位于眼球前方的眼副器是","o":["球结膜","角膜","巩膜","眼睑","外直肌"],"a":3,"e":"眼副器包括眼睑、结膜、泪器和眼球外肌等，其中眼睑位于眼球前方，起保护眼球的作用。角膜、巩膜属眼球壁纤维膜，不是眼副器；球结膜是贴于眼球表面的结膜部分，位于眼球表面而非单纯前方；外直肌位于眼球外侧，牵引眼球向外，均不合题意"},{"q":"肺动脉干起始于","o":["左心室","右心室","左心房","右心房","毛细血管"],"a":1,"e":"肺动脉干起自右心室的动脉圆锥，向左上后方走行，在主动脉弓下方分为左、右肺动脉，将静脉血输送至肺。主动脉起自左心室；左、右心房接纳回心血而不发出动脉；毛细血管是物质交换场所，均非肺动脉干的起始部位"},{"q":"使瞳孔转向上内的肌是","o":["上直肌","上斜肌","下斜肌","下直肌","上睑提肌"],"a":0,"e":"上直肌收缩使瞳孔转向上内方，由动眼神经支配。上斜肌使瞳孔转向下外；下斜肌使瞳孔转向上外；下直肌使瞳孔转向下内；上睑提肌作用是上提眼睑而非转动眼球，各眼外肌作用方向易混淆，需按肌名与止点方位判断"},{"q":"有关骨的构造，正确的说法是","o":["骨干由松质构成","骨骺由密质构成","骨膜有血管无神经","骨髓有神经无血管","骨膜过度缺损，影响骨折愈合"],"a":4,"e":"骨膜富含血管、神经和成骨细胞，对骨有营养、生长和修复作用，骨折时骨膜内成骨细胞参与骨痂形成，故过度缺损会影响愈合。骨干主要由密质构成，骨骺以松质为主；骨膜既有血管也有神经；骨髓同样含血管和神经，这些说法均与事实相反"},{"q":"限制脊柱过度后伸的韧带是","o":["前纵韧带","后纵韧带","黄韧带","棘间韧带","棘上韧带"],"a":0,"e":"前纵韧带位于椎体和椎间盘前面，坚韧，可限制脊柱过度后伸。后纵韧带位于椎体后面，主要限制脊柱过度前屈；黄韧带连接相邻椎弓板，协助限制前屈并维持直立；棘间韧带连于相邻棘突之间，棘上韧带纵行连接棘突尖，作用各异"},{"q":"关于胃后动脉描述正确的是","o":["分布至胃小弯","分布至胃大弯","分布至胃底","分布至胃的幽门部","分布至胃体后壁上部"],"a":4,"e":"胃后动脉多起自脾动脉，经网膜囊后壁至胃后壁，主要分布于胃体后壁上部及胃底附近。胃小弯由胃左、右动脉分布；胃大弯由胃网膜左、右动脉供应；幽门部由胃右动脉和胃十二指肠动脉分支供应，各动脉分布区域不同"},{"q":"屈肘并协助屈肩关节的肌是","o":["旋前圆肌","旋后肌","肱二头肌","指深屈肌","指伸肌"],"a":2,"e":"肱二头肌长头起自肩胛骨盂上结节，短头起自喙突，止于桡骨粗隆，跨越肩、肘两关节，故可屈肘并协助屈肩，前臂旋后时屈肘力最强。旋前圆肌使前臂旋前；旋后肌使前臂旋后；指深屈肌屈指；指伸肌伸指伸腕，均不能屈肩"},{"q":"鼻泪管开口于","o":["额窦","上颌窦","蝶窦","筛窦","下鼻道的外侧壁"],"a":4,"e":"鼻泪管下端开口于鼻腔下鼻道外侧壁的前部，泪液由此自泪囊排入鼻腔。上颌窦、额窦、蝶窦、筛窦均为鼻旁窦，各有其位于鼻腔的开口部位，如中鼻道、上鼻道等，但都与鼻泪管的开口无关，不能混淆泪道与鼻旁窦的引流"},{"q":"上消化道不包括","o":["十二指肠","口腔","胃","空肠","咽"],"a":3,"e":"临床上以十二指肠末端为界，口腔、咽、食管、胃和十二指肠属上消化道，空肠及其以下至肛管为下消化道。空肠位于腹腔内，属小肠的中段，由肠系膜上动脉的分支供血，淋巴引流至肠系膜淋巴结，不属上消化道的范畴"},{"q":"右主支气管的特点是","o":["走向较水平","细而短","细而长","粗而长","粗而短"],"a":4,"e":"右主支气管较左主支气管粗、短且陡直，与气管中线延长线夹角小，故异物易坠入右侧。左主支气管细而长、走向较水平；走向水平、细而短、粗而长等组合均与右主支气管的实际形态不符，左右支气管的粗细长短差异是常考点"},{"q":"听觉中枢位于","o":["缘上回","角回","颞横回","额下回","扣带回"],"a":2,"e":"听觉中枢位于颞叶的颞横回（41、42区），接受内侧膝状体发出的听辐射纤维。缘上回和角回属顶下小叶，参与语言、认知等功能；额下回后部为运动性语言中枢；扣带回属边缘系统，与情绪、内脏活动有关，均非听觉中枢"},{"q":"具有屈髋关节和屈膝关节的肌是","o":["股直肌","缝匠肌","半腱肌","股二头肌","股四头肌"],"a":1,"e":"缝匠肌起自髂前上棘，斜向内下止于胫骨上端内侧面，是全身最长的肌，跨越髋、膝两关节，收缩时屈髋又屈膝，并使大腿外旋外展、小腿内旋。股直肌屈髋而伸膝；半腱肌、股二头肌伸髋屈膝；股四头肌主要伸膝，均不能同时屈髋屈膝"},{"q":"以下属于内脏感觉神经核的是","o":["疑核","孤束核","舌下神经核","三叉神经脊束核","前庭神经核"],"a":1,"e":"孤束核位于延髓，接受面神经、舌咽神经、迷走神经传入的味觉和内脏感觉纤维，属内脏感觉核。疑核为特殊内脏运动核，支配咽喉肌；舌下神经核为躯体运动核；三叉神经脊束核接受头面部痛温觉；前庭神经核接受平衡觉，均非内脏感觉核"},{"q":"左心室的入口是","o":["右房室口","左房室口","肺动脉口","主动脉口","肺静脉口"],"a":1,"e":"左心室入口为左房室口，口周有二尖瓣附着，血液由左心房经此口流入左心室。右房室口是右心室入口；肺动脉口为右心室出口，主动脉口为左心室出口；肺静脉口开于左心房，将含氧血送回左房，均非左心室入口"},{"q":"关于腮腺，下列说法中正确的是","o":["是最大的消化腺","开口于口腔前庭","开口于舌下阜和舌下襞","有数条腮腺导管","开口于上颌第2磨牙"],"a":1,"e":"腮腺是最大的唾液腺，其导管横过咬肌表面，开口于平对上颌第2磨牙的颊黏膜，颊黏膜属口腔前庭，故此说法正确。最大的消化腺是肝而非腮腺；舌下阜和舌下襞是下颌下腺、舌下腺的开口处；腮腺只有一条腮腺导管，且开口于颊黏膜而非磨牙本身"},{"q":"下列哪个Brodmann区是躯体感觉中枢（第一躯体感觉区）","o":["3，1，2区","4区","17区","22区","40区"],"a":0,"e":"第一躯体感觉区位于中央后回和中央旁小叶后部，相当于Brodmann 3、1、2区，接受丘脑腹后核投射，管理对侧躯体感觉。4区为第一运动区；17区为视区；22区为听区及语言中枢；40区为缘上回，属顶下小叶，均非第一躯体感觉区"},{"q":"躯干和四肢痛温觉传导通路的第3级神经元是","o":["后角细胞","三叉神经脊束核","薄束核","丘脑腹后内侧核","丘脑腹后外侧核"],"a":4,"e":"躯干、四肢痛温觉传导通路的第一级神经元在脊神经节，第二级在脊髓后角，第三级为丘脑腹后外侧核，其轴突经内囊投射至中央后回。薄束核属深感觉传导；三叉神经脊束核管理头面部痛温觉；丘脑腹后内侧核接受头面部感觉；后角细胞为二级神经元"},{"q":"下面有关臀大肌的描述，正确的是","o":["只起自髂骨的外面","使髋关节后伸和外旋","使髋关节的前屈和外旋","能内旋大腿","属于大腿肌后群"],"a":1,"e":"臀大肌起自髂骨翼外面和骶骨背面，止于髂胫束和股骨臀肌粗隆，是强有力的伸髋肌，并使髋关节外旋，故该描述正确。该肌并非只起自髂骨；其作用是后伸而非前屈，也不能内旋大腿；臀大肌属髋肌后群（臀肌），不属大腿肌后群"},{"q":"关于颈内静脉，下列描述错误的是","o":["与锁骨下静脉汇合成头臂静脉","由乙状窦延续而成","行于颈外动脉外侧","起于颈静脉孔","有颅内和颅外属支"],"a":2,"e":"颈内静脉在颈部行于颈总动脉和颈内动脉的外侧，与颈外动脉关系并非如此，'行于颈外动脉外侧'的说法错误。颈内静脉在颈静脉孔处续接乙状窦，与锁骨下静脉汇合成头臂静脉，有颅内、颅外属支，这些描述均正确"},{"q":"下列静脉中，缺乏静脉瓣的静脉是","o":["贵要静脉","头静脉","股静脉","大隐静脉","面静脉"],"a":4,"e":"面静脉起自内眦静脉，与眼静脉交通进入海绵窦，全程缺少静脉瓣，面部感染可借眼静脉逆行至颅内，故为缺乏静脉瓣者。贵要静脉、头静脉为上肢浅静脉，股静脉、大隐静脉为下肢静脉，均有较多静脉瓣，以防止血液反流"},{"q":"心的正常起搏点是","o":["窦房结","结间束","房室结","房室束","Purkinje纤维网"],"a":0,"e":"窦房结位于上腔静脉与右心房交界处的心外膜下，是心的正常起搏点，自动产生节律性兴奋并传导至全心。结间束为房内传导束；房室结为次级起搏点并延搁兴奋；房室束及Purkinje纤维网属心室内传导系统，正常情况下不主导心律"},{"q":"有关交感神经交通支的描述，错误的是","o":["分白交通支和灰交通支","每个交感干神经节与相应的脊神经直接都有交通支相连","白交通支属于节前纤维","灰交通支属于节后纤维","灰交通支只存在于T1～L3各脊神经的前支与相应的交感干神经节之间"],"a":4,"e":"灰交通支由节后纤维构成，存在于全部31对脊神经与交感干神经节之间；只有白交通支（节前纤维）仅见于T1～L3，故该说法错误。交通支分白、灰两种；每个交感干神经节与相应脊神经间有交通支相连；白交通支属节前纤维，灰交通支属节后纤维"},{"q":"受尺神经支配的骨骼肌为","o":["第1～2蚓状肌","第2～3蚓状肌","第3～4蚓状肌","第1、4蚓状肌","第2、4蚓状肌"],"a":2,"e":"手肌的蚓状肌中，第1、2蚓状肌由正中神经支配，第3、4蚓状肌由尺神经支配，故受尺神经支配者为第3～4蚓状肌。第1～2、第2～3及第1、4等组合均与正中、尺神经在手肌的分布规律不符，尺神经主要支配手内在肌的大部分"},{"q":"通常卵子受精的部位是","o":["输卵管壶腹","输卵管峡","输卵管子宫部","输卵管伞","输卵管漏斗"],"a":0,"e":"输卵管壶腹是输卵管最长、最宽且弯曲的部分，卵子排出后在此与精子相遇受精，受精卵再移行入子宫着床。输卵管峡短而直，是结扎常用部位；子宫部为穿过子宫壁的一段；输卵管伞和漏斗位于外侧端，主要司拾卵，均非受精部位"},{"q":"肛管内皮肤与黏膜的分界线是","o":["齿状线","肛梳","直肠下横襞","肛柱","白线"],"a":0,"e":"齿状线由肛瓣与肛柱下端共同围成，是肛管内皮肤与黏膜的分界线，线上线下在胚胎来源、上皮类型、神经支配和血供上均不同。肛梳为齿状线以下的光滑区域；肛柱为肛管上段的纵行皱襞；直肠下横襞位于直肠；白线为肛管下端的环形线"},{"q":"颧弓是由下面哪些骨组成的","o":["上颌骨与颞骨","颞骨与蝶骨","蝶骨与颧骨","颧骨与颞骨","上颌骨与颧骨"],"a":3,"e":"颧弓由颧骨的颞突与颞骨的颧突共同构成，位于面部两侧，是重要的骨性标志。上颌骨参与构成眶下缘、上颌体和硬腭，不与颞骨直接组成颧弓；蝶骨位于颅中窝底，与颧弓无关，含上颌骨或蝶骨的组合均不正确"},{"q":"注入肾静脉的血管是","o":["膈下静脉","左睾丸静脉","右睾丸静脉","腰升静脉","腰静脉"],"a":1,"e":"左睾丸静脉以直角注入左肾静脉，而右睾丸静脉直接以锐角注入下腔静脉，故注入肾静脉者为左睾丸静脉。膈下静脉注入下腔静脉；腰升静脉、腰静脉多注入下腔静脉或参与侧支循环，均不注入肾静脉，左右睾丸静脉注入部位的差异是常考点"},{"q":"下列结构中，位于直肠壶腹内的是","o":["肛柱","齿状线","肛梳","肛瓣","直肠横襞"],"a":4,"e":"直肠壶腹为直肠下段的膨大部分，其内有直肠横襞（Houston瓣），常有3个，是直肠镜检查的标志。肛柱、肛瓣位于肛管上段；齿状线是肛管内皮肤与黏膜分界；肛梳为齿状线以下区域，均属肛管结构，不在直肠壶腹内"},{"q":"尿道前列腺部是","o":["尿道最长的一段","前尿道的一部分","尿道最狭窄的一段","尿道最短的一段","尿道的起始部"],"a":4,"e":"男性尿道分前列腺部、膜部和海绵体部，前列腺部为起始部，穿过前列腺，管腔最宽，有射精管和前列腺导管开口。尿道最长的一段是海绵体部；最狭窄处为尿道内口、膜部及外口，膜部最短且最固定；前尿道指海绵体部，均不合题意"},{"q":"坐位时，腹膜腔的最低点是","o":["肝肾隐窝","盲肠后隐窝","耻骨后间隙","直肠子宫陷凹","膀胱子宫陷凹"],"a":3,"e":"女性坐位或直立时，腹膜腔最低处为直肠子宫陷凹（Douglas腔），位于直肠与子宫之间，积液易积于此，可经阴道后穹穿刺。肝肾隐窝为仰卧位时上腹最低处；膀胱子宫陷凹位于膀胱与子宫之间；耻骨后间隙不属腹膜腔，这些部位均非坐位最低点"},{"q":"止于背侧丘脑腹后内侧核的纤维束是","o":["内侧丘系","脊髓丘系","三叉丘系","薄束","楔束"],"a":2,"e":"三叉丘系由头面部感觉传导的二级纤维交叉后上行，止于背侧丘脑腹后内侧核，转司头面部感觉。内侧丘系、脊髓丘系主要止于腹后外侧核，管理躯干四肢感觉；薄束、楔束是脊髓后索内上行的纤维束，经薄束核、楔束核中继，均不直接止于腹后内侧核"},{"q":"肾蒂内主要结构从前向后依次为","o":["肾动脉 肾静脉 肾盂","肾静脉 肾动脉 肾盂","肾盂 肾静脉 肾动脉","肾动脉 肾盂 肾静脉","肾盂 肾动脉 肾静脉"],"a":1,"e":"肾蒂内结构由前向后依次为肾静脉、肾动脉、肾盂，静脉居前、动脉居中、肾盂居后，是肾蒂解剖的要点。将肾动脉列于肾静脉之前，或把肾盂置于最前，均与肾蒂内的实际排列不符，肾静脉位于最前是辨认肾蒂结构的标志"},{"q":"产生泪液的结构是","o":["泪点","上泪小管","下泪小管","泪囊","泪腺"],"a":4,"e":"泪腺位于眶上壁外侧部的泪腺窝内，分泌泪液，湿润角膜和结膜，并有冲洗、杀菌作用。泪点为泪液排出的小孔；上、下泪小管为引流泪液的管道；泪囊位于泪囊窝，暂存并引流泪液，均属泪道而非分泌结构"},{"q":"传导表情肌随意运动信息的纤维束是","o":["三叉神经脊束","内侧丘系","脊髓丘系（脊髓丘脑束）","皮质核束","皮质脊髓束"],"a":3,"e":"皮质核束（皮质延髓束）起自大脑皮质运动区，下行至脑干，支配脑神经运动核，其中面神经核上部支配表情肌的随意运动，故传导表情肌随意运动者为皮质核束。皮质脊髓束支配躯干四肢肌；内侧丘系、脊髓丘系为感觉传导束；三叉神经脊束为感觉纤维束，均不支配表情肌"},{"q":"关于颈总动脉描述正确的是","o":["双侧均发自主动脉弓","在舌骨大角平面分为颈内、颈外动脉","其内侧有颈内静脉","分叉处有颈动脉窦和颈动脉小球","头面部出血时可在甲状软骨外侧压迫该动脉"],"a":3,"e":"颈总动脉在甲状软骨上缘平面分为颈内、颈外动脉，分叉处有颈动脉窦（压力感受器）和颈动脉小球（化学感受器），故该描述正确。左颈总动脉起自主动脉弓，右颈总动脉起自头臂干；分叉平面不在舌骨大角；颈内静脉位于其外侧；压迫止血应在环状软骨水平"},{"q":"牙式表示的是","o":["恒牙","乳牙","乳牙和恒牙","乳牙或恒牙以及牙的位置","牙的位置"],"a":3,"e":"牙式（牙位记录）以符号和数字标明乳牙或恒牙的类别及其在牙弓中的位置，如恒牙用1～8表示，乳牙用罗马数字或字母表示，故其既表示牙种又表示位置。仅指恒牙、仅指乳牙或仅指位置的说法都片面，不能完整概括牙式的含义"},{"q":"有关主动脉弓的描述，正确的是","o":["在右侧第3胸肋关节高度弓形弯向左侧","其壁内有压力感受器","在第5胸椎下缘续降主动脉","弓的凸缘发出左、右颈总动脉及锁骨下动脉","以上描述均正确"],"a":1,"e":"主动脉弓壁内有压力感受器，可感受血压变化并参与心血管调节，弓下缘还有主动脉小球（化学感受器），故该描述正确。主动脉弓在右侧第2胸肋关节高度弓形弯向左后；至第4胸椎下缘续降主动脉；弓凸缘发出头臂干、左颈总动脉、左锁骨下动脉，各分支并不左右对称"},{"q":"关于肱三头肌的描述，正确的是","o":["长头起于关节盂的上方","止于桡骨粗隆","使前臂旋后","是伸肘关节的肌","长头可屈肩关节"],"a":3,"e":"肱三头肌长头起自肩胛骨盂下结节，外侧头、内侧头起自肱骨后面，三头合成肌腱止于尺骨鹰嘴，是伸肘关节的主要肌，故该描述正确。长头起于盂下结节而非关节盂上方；止于尺骨鹰嘴而非桡骨粗隆；作用为伸肘而非旋后；长头可协助伸肩而非屈肩"},{"q":"关于桡动脉描述错误的是","o":["为肱动脉两个终支之一","行于前臂的外侧肌之间","在肱桡肌与桡侧腕屈肌腱间桡动脉位置表浅","桡动脉的拇主要动脉不参与掌浅弓的组成","桡动脉的掌浅支参与掌深弓的组成"],"a":4,"e":"桡动脉掌浅支与尺动脉终支吻合构成掌浅弓，参与掌深弓的是桡动脉终支与尺动脉掌深支，故'掌浅支参与掌深弓'错误。桡动脉为肱动脉终支之一，行于前臂外侧肌之间，在肱桡肌与桡侧腕屈肌腱之间位置表浅，是触摸脉搏的常用部位，拇主要动脉不参与掌浅弓"},{"q":"下列关于骶副交感核的描述，正确的是","o":["位于第1胸髓节段～第3腰髓节段中间带的内侧部","位于第2～4髓骶节段中间带的内侧部","位于第1胸髓节段～第3腰髓节段中间带的外侧部","位于第2～4髓骶节段中间带的外侧部","是副交感节后神经元胞体"],"a":3,"e":"骶副交感核位于脊髓第2～4骶节段中间带外侧部，其内为副交感节前神经元胞体，发出的纤维随盆内脏神经支配盆腔脏器。第1胸髓至第3腰髓中间带外侧部为交感神经中间外侧核；中间带内侧部无此核团；该核属节前而非节后神经元，故位置与性质均需辨明"},{"q":"关于头臂静脉，下列描述中错误的是","o":["右侧有右淋巴导管注入","左侧有胸导管注入","由同侧颈总静脉与锁骨下静脉合成","左、右各一条","注入上腔静脉"],"a":2,"e":"头臂静脉由同侧的颈内静脉与锁骨下静脉在胸锁关节后方汇合而成，并非由'颈总静脉'合成，故此说法错误。头臂静脉左右各一，左侧接受胸导管注入，右侧接受右淋巴导管注入，左、右头臂静脉汇合成上腔静脉，这些描述均正确"},{"q":"属于软骨连结的是","o":["颅骨的缝","桡、尺骨间的连结","腕骨间的连结","椎间盘","第2肋与胸骨间的连结"],"a":3,"e":"椎间盘位于相邻椎体之间，由外围的纤维环和中央的髓核构成，属纤维软骨，是软骨连结的典型代表。颅骨的缝为纤维连结；桡、尺骨间主要借骨间膜（韧带连结）相连；腕骨间多为微动的滑膜关节；第2肋与胸骨间为胸肋关节，属间接连结"},{"q":"使足外翻的肌肉是","o":["腓肠肌","胫骨前肌","胫骨后肌","腓骨长肌","比目鱼肌"],"a":3,"e":"腓骨长肌与腓骨短肌位于小腿外侧群，受腓浅神经支配，收缩时使足外翻并协助跖屈，故使足外翻者为腓骨长肌。腓肠肌和比目鱼肌（小腿三头肌）主要使足跖屈；胫骨前肌、胫骨后肌使足内翻，与外翻作用相反"},{"q":"上腔静脉注入到下列何处","o":["右心房","左心房","无名静脉","左心室","右心室"],"a":0,"e":"上腔静脉由左、右头臂静脉汇合而成，沿升主动脉右侧下行，注入右心房上部，收集头颈、上肢及胸壁的静脉血。左心房接纳肺静脉血；无名静脉即头臂静脉，是上腔静脉的属支而非其注入处；左心室、右心室为心室，不直接接受腔静脉回流"},{"q":"下面有关胸锁乳突肌的描述，正确的是","o":["表面无肌覆盖","仅起自胸骨柄","止于颞骨的乳突","两侧收缩使头前屈","该肌一侧收缩使头歪向对侧"],"a":2,"e":"胸锁乳突肌起自胸骨柄和锁骨内侧段，向后上止于颞骨乳突及枕骨上项线外侧部，故止于乳突正确。该肌表面有颈阔肌等覆盖，并非无肌覆盖；起点不只胸骨柄；一侧收缩使头向同侧屈、脸转向对侧，两侧收缩使头后仰，均非前屈"},{"q":"关于甲状旁腺的描述，正确的是","o":["呈“H”形","左、右各一个","位于甲状腺前方","功能与甲状腺相同","可参与调节体内钙、磷的代谢"],"a":4,"e":"甲状旁腺为扁椭圆形小体，通常上下两对共4个，贴于甲状腺后面，分泌甲状旁腺激素，调节体内钙、磷代谢，故该描述正确。呈'H'形的是甲状腺而非甲状旁腺；甲状旁腺为两对而非各一；位于甲状腺后方而非前方；其功能与调节钙磷的甲状腺（滤泡旁细胞降钙素）不同"},{"q":"具有3个运动轴的关节是","o":["肩关节","肘关节","桡腕关节","膝关节","距小腿关节"],"a":0,"e":"肩关节由肱骨头与肩胛骨关节盂构成，属球窝关节，可绕额状轴、矢状轴和垂直轴运动，即屈伸、内收外展、旋内旋外，为三轴关节。肘关节主要为屈伸并含旋转，属二轴；桡腕关节、距小腿关节为二轴；膝关节以屈伸为主并少许旋转，均非三轴"},{"q":"被射精管穿过的结构是","o":["睾丸","精囊","附睾","前列腺","尿道球腺"],"a":3,"e":"射精管由输精管末端与精囊排泄管汇合而成，向前下穿过前列腺实质，开口于尿道前列腺部的精阜，故被射精管穿过者为前列腺。射精管不穿过睾丸、附睾；精囊是构成射精管的结构之一而非被穿过者；尿道球腺位于尿道膜部两侧，与射精管无关"},{"q":"与直肠子宫陷凹相邻的是","o":["阴道前穹","阴道后穹","阴道左穹","阴道右穹","膀胱颈"],"a":1,"e":"直肠子宫陷凹位于直肠与子宫之间，是腹膜腔最低处，其前方与阴道后穹相邻，临床可经阴道后穹穿刺引流积液或积血。阴道前穹与膀胱子宫陷凹相邻；左、右穹及膀胱颈与该陷凹不直接相邻，部位关系需辨清"},{"q":"下列哪个器官的静脉血未汇入肝门静脉","o":["胃","脾","肾","胰","十二指肠"],"a":2,"e":"肾静脉直接注入下腔静脉，其静脉血不经过肝门静脉，故未汇入肝门静脉者为肾。胃的静脉血经胃左、右静脉汇入门静脉；脾静脉、胰静脉、十二指肠静脉均参与构成或直接注入肝门静脉，最终经肝血窦回流，与肾静脉去向不同"},{"q":"下列关于胸廓的叙述中，错误的是","o":["由12块胸椎、肋和胸骨连结而成","成人近似圆锥体","上部狭窄，下部宽阔","其前后径大于横径","其下口宽阔而被膈肌封闭"],"a":3,"e":"成人胸廓近似圆锥形，上窄下宽，其横径（左右径）大于前后径，故'前后径大于横径'错误。胸廓由12块胸椎、12对肋和胸骨连结而成；下口宽阔由膈封闭；这些描述正确，前后径与横径的大小关系是胸廓形态的常考点"},{"q":"右淋巴导管收集的淋巴液范围是","o":["右半身","人体右上1/3","人体右上2/3","人体右上1/4","人体右上3/4"],"a":3,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干汇合而成，收集右上肢、右半头颈和右胸部的淋巴，约占全身淋巴的1/4，其余3/4由胸导管收集。右半身、人体右上1/3、2/3、3/4等比例均与右淋巴导管实际收集范围不符"},{"q":"下列关于脊髓节段与椎骨关系的描述，正确的是","o":["第3腰髓节段平对第2腰椎","第7胸髓节段平对第7胸椎","第5颈髓节段平对第5颈椎","骶尾节段平对第2腰椎","第2胸髓节段平对第1胸椎"],"a":4,"e":"脊髓节段与椎骨的对应关系中，下颈髓和第1～4胸髓平对上一椎骨，故第2胸髓平对第1胸椎。第3腰髓平对第10～12胸椎而非第2腰椎；第7胸髓平对第5胸椎；第5颈髓平对第4颈椎；骶尾髓平对第1腰椎，各项均与实际对应关系不符"},{"q":"关于右冠状动脉描述正确的是","o":["发自主动脉弓","分为前室间支和旋支","行走在冠状沟的左侧","在室间隔与左冠状动脉相吻合","不分支营养窦房结"],"a":3,"e":"右冠状动脉起自升主动脉右窦，行于右侧冠状沟，发出后室间支等分支，其分支在室间隔与左冠状动脉的前室间支相吻合，故该描述正确。冠状动脉起自升主动脉而非主动脉弓；分前室间支和旋支的是左冠状动脉；右冠状动脉行于右侧冠状沟；其常发分支营养窦房结"},{"q":"解剖学姿势下两侧髋骨的最低处是","o":["髂前上棘","髂前下棘","髂后下棘","坐骨棘","坐骨结节"],"a":4,"e":"解剖学姿势下，髋骨由髂骨、坐骨、耻骨融合而成，坐骨结节位于坐骨下端，是站立坐姿时承重的骨性突起，为两侧髋骨最低处。髂前上棘、髂前下棘、髂后下棘位于髂骨，位置较高；坐骨棘位于坐骨大、小切迹之间，均非最低点"},{"q":"大脑内，属于连合纤维的是","o":["胼胝体","皮质脊髓束","丘脑中央辐射","视辐射","听辐射"],"a":0,"e":"胼胝体是连接左右大脑半球的最大连合纤维束，由连合两半球皮质的轴突构成，故属连合纤维。皮质脊髓束为下行投射纤维；丘脑中央辐射、视辐射、听辐射均为投射纤维，连接丘脑或感官与大脑皮质，均不属连合左右半球的纤维"},{"q":"有关女性尿道的描述，正确的是","o":["前方邻接阴道","后方邻接直肠","穿尿生殖膈","开口于阴道口与肛门之间","尿道阴道括约肌为平滑肌"],"a":2,"e":"女性尿道短而直，起自尿道内口，向前下穿过尿生殖膈，开口于阴道前庭的尿道外口，故穿尿生殖膈正确。其前方邻接耻骨联合而非阴道；后方邻接阴道而非直肠；开口于阴道前庭而非阴道口与肛门之间；尿道阴道括约肌为骨骼肌而非平滑肌"},{"q":"咽鼓管咽口位于","o":["咽鼓管圆枕后上方","下鼻道后部","口咽部","中耳鼓室","咽鼓管圆枕前下方"],"a":4,"e":"咽鼓管咽口位于鼻咽侧壁、咽鼓管圆枕的前下方，咽鼓管向后外通中耳鼓室，以调节鼓室内外气压。咽鼓管圆枕后上方为咽隐窝，是鼻咽癌好发部位；下鼻道后部有鼻泪管开口；口咽部为中咽部分；咽口并不在鼓室，这些部位互相邻近但不同"},{"q":"关于直肠的说法，正确的是","o":["内有直肠纵襞","上端接降结肠","在男性，通过直肠指诊可触及前列腺","有骶曲和尾曲","向下通过肛门续于肛管"],"a":2,"e":"直肠指诊时，男性可经直肠前壁触及前列腺，女性可触及子宫颈，故该描述正确。直肠上端在第3骶椎平面接乙状结肠而非降结肠；直肠有骶曲和会阴曲而非尾曲；直肠内有直肠横襞而非纵襞；直肠向下穿盆膈续于肛管，而非经肛门直接延续"},{"q":"需要两侧同时运动的关节是","o":["肩关节","肘关节","髋关节","膝关节","颞下颌关节"],"a":4,"e":"颞下颌关节由下颌头与颞骨下颌窝构成，两侧关节必须同时运动，共同完成张口、闭口及咀嚼动作，故需两侧同时运动的是颞下颌关节。肩、肘、髋、膝关节均为四肢单关节，可单独活动，一侧运动时另一侧不必须参与，与该关节的联动性不同"},{"q":"关于小网膜的描述，正确的是","o":["仅位于肝门与胃小弯之间","由四层腹膜形成","即肝胃韧带","内有胃左动脉和胃右动脉","与大网膜相连续"],"a":3,"e":"小网膜是肝门与胃小弯、十二指肠上部之间的双层腹膜，分为肝胃韧带和肝十二指肠韧带，其中走行胃左动脉和胃右动脉，故该描述正确。小网膜不限于肝门与胃小弯之间；由两层而非四层腹膜形成；包含肝胃韧带和肝十二指肠韧带两部分，与大网膜并非直接相连续"},{"q":"关于肋间后动脉，错误的是","o":["12对肋间后动脉均来自主动脉胸部","分布于第3～11肋间隙的肋间后动脉来自主动脉胸部","分布于第1～2肋间隙的肋间后动脉来自锁骨下动脉","第12对肋间后动脉行于12肋下缘称肋下动脉","肋下动脉也来自主动脉胸部"],"a":0,"e":"第1、2肋间后动脉起自锁骨下动脉，第3～11肋间后动脉起自主动脉胸部，第12对为肋下动脉也起自主动脉胸部，故'12对均来自主动脉胸部'错误。胸主动脉发出第3～11肋间后动脉及肋下动脉，锁骨下动脉发出第1、2肋间后动脉，来源需分辨"},{"q":"脑室系统中，不包含脉络丛的结构是","o":["第三脑室","第四脑室","侧脑室","中脑水管","室间孔"],"a":3,"e":"中脑水管为连接第三、第四脑室的细管，管壁无脉络丛；脉络丛存在于侧脑室、第三脑室和第四脑室，负责产生脑脊液，故不含脉络丛者为中脑水管。侧脑室脉络丛最发达，第三、第四脑室脉络丛位于其顶壁，脉络丛经室间孔相互延续，而中脑水管仅为细长通道"},{"q":"在蜗顶处，前庭阶与鼓阶借下列哪个结构彼此相通","o":["蜗管","蜗窗","蜗孔","前庭水管外口","前庭窗"],"a":2,"e":"耳蜗内前庭阶和鼓阶在蜗顶处借蜗孔彼此相通，蜗孔是蜗轴顶端的细小开口，使外淋巴液循环沟通。蜗管为膜迷路，内含内淋巴，居前庭阶与鼓阶之间；蜗窗为鼓阶通中耳的开口，被第二鼓膜封闭；前庭窗通前庭阶；前庭水管外口位于颞骨岩部后面，均非两阶相通处"},{"q":"上颌神经不分布于","o":["上颌牙和牙龈","上颌窦黏膜","舌前2/3的黏膜","口腔顶","睑裂与口裂之间的皮肤"],"a":2,"e":"舌前2/3黏膜的一般感觉由下颌神经的舌神经支配，味觉由面神经鼓索支配，均不属上颌神经，故上颌神经不分布于舌前2/3黏膜。上颌神经分布于上颌牙及牙龈、上颌窦黏膜、口腔顶及睑裂与口裂之间的皮肤，这些区域均在其分支范围内"},{"q":"一侧皮质脊髓束下行不经过","o":["内囊前肢","内囊后肢","中脑大脑脚","脑桥基底部","延髓锥体"],"a":0,"e":"皮质脊髓束起自大脑皮质运动区，经内囊后肢下行，继而穿过中脑大脑脚、脑桥基底部和延髓锥体，在锥体交叉后进入脊髓，故其下行不经过内囊前肢。内囊前肢主要通过额桥束等纤维，内囊后肢才有皮质脊髓束及感觉投射纤维通过，二者不可混淆"},{"q":"关于纤维性心包，下列说法错误的是","o":["包裹在心及其大血管根部外面","是坚韧的结缔组织囊","与浆膜性心包壁层紧贴","与膈肌中心腱愈着","心包积液时伸缩性较大"],"a":4,"e":"纤维性心包由坚韧的结缔组织构成，伸缩性小，心包积液时不易扩张，易压迫心脏导致心脏压塞，故'伸缩性较大'错误。纤维性心包包裹心及大血管根部外面，与浆膜性心包壁层紧贴，并在下方与膈肌中心腱愈着，这些描述均正确"},{"q":"内侧丘系交叉位于","o":["延髓","脑桥","中脑","间脑","内囊"],"a":0,"e":"薄束核、楔束核发出的纤维在延髓中央灰质腹侧交叉，称为内侧丘系交叉，交叉后纤维上行形成内侧丘系，故交叉位于延髓。脑桥、中脑为内侧丘系上行经过的部位；间脑为其终止换元处（丘脑腹后外侧核）；内囊为其投射至皮质的通路，均非交叉部位"},{"q":"关于肾上腺的描述，正确的是","o":["左、右各一，均为肾形","肾上腺位于腹膜腔内","左侧呈半月形，右侧呈三角形","左、右肾上腺均位于肾脏下端","肾上腺皮质激素又称肾上腺素"],"a":2,"e":"肾上腺位于腹膜后隙、肾的上端，左肾上腺呈半月形，右肾上腺呈三角形，故该描述正确。肾上腺左右各一但形态不同，并非均为肾形；其位于腹膜后而非腹膜腔内；位于肾上端而非下端；肾上腺皮质分泌皮质激素，肾上腺素由髓质分泌，二者不同"},{"q":"上腔静脉由下列的什么静脉汇合而成","o":["头臂静脉","锁骨下静脉","颈内静脉","头臂干","颈外静脉"],"a":0,"e":"上腔静脉由左、右头臂静脉在右侧第1胸肋结合处后方汇合而成，收集上半身静脉血注入右心房。锁骨下静脉与颈内静脉汇合成头臂静脉；颈外静脉注入锁骨下静脉；头臂干为动脉，与静脉回流无关，这些结构层次不同"},{"q":"关于大隐静脉，下列说法正确的是","o":["起于足背静脉网外侧","经内踝后方上行","静脉瓣很少","注入股静脉","属于深静脉"],"a":3,"e":"大隐静脉起自足背静脉网内侧，经内踝前方上行，是全身最长的浅静脉，最终穿隐静脉裂孔注入股静脉，故该描述正确。其起于足背静脉网内侧而非外侧；经内踝前方而非后方；有较多静脉瓣；属浅静脉而非深静脉"},{"q":"使脑脊液渗入上矢状窦的结构是","o":["正中孔","外侧孔","室间孔","蛛网膜粒","中脑水管"],"a":3,"e":"蛛网膜粒是蛛网膜突入上矢状窦等硬脑膜窦内的绒毛状突起，脑脊液经蛛网膜粒渗入静脉窦，回归血液循环。正中孔、外侧孔为第四脑室通向蛛网膜下隙的开口；室间孔通侧脑室与第三脑室；中脑水管连通第三、第四脑室，均非脑脊液回流入窦的结构"},{"q":"舌下神经管位于下面哪块颅骨上","o":["额骨","颞骨","枕骨","筛骨","蝶骨"],"a":2,"e":"舌下神经管位于枕骨大孔外侧的枕骨髁上方，有舌下神经通过，故位于枕骨。额骨构成颅前窝和眶上壁；颞骨岩部有颈动脉管、内耳门等；筛骨有筛孔通嗅神经；蝶骨有视神经管、圆孔、卵圆孔等，均不含舌下神经管"},{"q":"喉炎时易发生水肿的部位是","o":["喉室","声门裂","声门下腔","喉口","前庭裂"],"a":2,"e":"声门下腔位于声襞与环状软骨下缘之间，其黏膜下组织疏松，炎症时易发生水肿，水肿可阻塞喉腔引起呼吸困难，故喉炎易水肿部位为声门下腔。喉室为声襞与前庭襞间的隐窝；声门裂为喉腔最狭窄处；喉口为喉的入口；前庭裂位于前庭襞之间，均非水肿好发处"},{"q":"现代人体解剖学的创始人是","o":["Vesalius","Galen","Harvey","Hippocrates","Schwann"],"a":0,"e":"维萨里（Vesalius）发表《人体构造》，以人体实物解剖为基础，纠正了长期沿用的盖伦学说，被视为现代人体解剖学的创始人。盖伦（Galen）为古罗马医学家，其学说多基于动物解剖；哈维（Harvey）发现血液循环；希波克拉底（Hippocrates）为医学之父；施旺（Schwann）提出细胞学说"},{"q":"坐骨神经出盆腔的部位是","o":["闭孔","坐骨小孔","骶管裂孔","梨状肌上孔","梨状肌下孔"],"a":4,"e":"坐骨神经为全身最粗大的神经，自骶丛发出后经梨状肌下孔出盆腔，在臀大肌深面下行至大腿后部，故出盆腔部位为梨状肌下孔。闭孔有闭孔神经、血管通过；坐骨小孔有阴部神经等通过；骶管裂孔为骶管下端开口；梨状肌上孔有臀上神经、血管通过"},{"q":"骨损伤后能参与修复的结构是","o":["骨质","骨骺","骨膜","骨髓","关节面的软骨"],"a":2,"e":"骨膜覆盖于骨表面（关节面除外），内含血管、神经和成骨细胞，骨折后成骨细胞增殖形成骨痂，参与骨的修复，故能参与修复者为骨膜。骨质为骨的主体但无修复能力；骨骺为长骨两端；骨髓主要造血；关节面软骨损伤后再生能力差，均非修复主力"},{"q":"下颌下腺和舌下腺共同开口在","o":["舌盲孔","舌系带","舌下襞","舌下阜","伞襞"],"a":3,"e":"下颌下腺导管与舌下腺大导管共同开口于舌下阜，舌下腺小导管则开口于舌下襞，故两者共同开口处为舌下阜。舌盲孔为甲状舌管残余，位于舌根部；舌系带为舌下正中的黏膜皱襞；伞襞为舌下襞内侧的小皱襞，均非两腺共同开口"},{"q":"关于斜方肌，下列描述正确的是","o":["起于枕外隆突和上部腰椎棘突","止于肩胛骨的上角","收缩时使肩胛骨外展","两侧同时收缩，可使肩胛骨向脊柱靠拢","下部肌纤维收缩，可上提肩胛骨"],"a":3,"e":"斜方肌起自枕外隆突、项韧带和全部胸椎棘突，止于锁骨外侧部、肩峰和肩胛冈，两侧收缩使肩胛骨向脊柱靠拢，故该描述正确。起点不含上部腰椎棘突；止点不在肩胛骨上角；收缩使肩胛骨后缩而非外展；下部肌纤维使肩胛骨下降而非上提"},{"q":"胆囊动脉","o":["胆囊动脉由腹腔干发出","胆囊动脉由肝总动脉发出","胆囊动脉由肝固有动脉左支发出","胆囊动脉经肝胆三角至胆囊","胆囊动脉伴胆囊管至胆囊"],"a":3,"e":"胆囊动脉多起自肝固有动脉右支，经由胆囊管、肝总管与肝下面围成的肝胆三角（Calot三角）至胆囊，故该描述正确。胆囊动脉不起自腹腔干或肝总动脉主干；一般起自肝固有动脉右支而非左支；其走行需经肝胆三角辨认，与胆囊管的毗邻关系是手术要点"},{"q":"关于呼吸道的叙述，正确的是","o":["咽既是呼吸道，也是消化道","上呼吸道只有呼吸功能","上呼吸道包括口腔、鼻、咽","咽和喉属于下呼吸道","肺和支气管为下呼吸道"],"a":0,"e":"咽位于鼻咽、口咽、喉咽，是呼吸与消化两用的管道，食物经咽入食管，空气经咽入喉，故咽既是呼吸道也是消化道。上呼吸道包括鼻、咽、喉，不包括口腔，且具有嗅觉、发音等功能；喉和气管、支气管属下呼吸道；肺是气体交换器官而非呼吸道"},{"q":"关于肝上界的描述，正确的是","o":["在右腋中线起自第7肋","在右腋中线起自第11肋","在左锁骨中线起自第7肋","在右锁骨中线起自第6肋","在右锁骨中线起自第7肋"],"a":0,"e":"肝上界与膈穹窿一致，在右锁骨中线平第5肋，在右腋中线平第7肋，在右肩胛线平第10肋，故在右腋中线起自第7肋正确。右腋中线第11肋为肝下界附近；左锁骨中线第7肋并非肝上界标志；右锁骨中线应为第5肋而非第6、7肋"},{"q":"产生精子的部位是","o":["精曲小管","精囊腺","输精管","前列腺","附睾"],"a":0,"e":"精曲小管（生精小管）位于睾丸实质内，是产生精子的部位，精子在此发生并逐步成熟，后经精直小管、睾丸网排入附睾。精囊腺分泌精液成分；输精管输送精子；前列腺分泌前列腺液；附睾是精子储存和成熟的场所，均不产生精子"},{"q":"左右心室收缩时","o":["二尖瓣开放","三尖瓣开放","主动脉瓣开放","肺动脉瓣关闭","心房也收缩"],"a":2,"e":"心室收缩期室内压升高，超过动脉压时主动脉瓣和肺动脉瓣开放，血液由心室射入动脉，同时二尖瓣、三尖瓣关闭以防反流，故心室收缩时主动脉瓣开放。二尖瓣、三尖瓣在心室舒张时开放；肺动脉瓣在右心室收缩时开放而非关闭；左右心室舒缩同步，心房此时处于舒张状态"},{"q":"颈外静脉汇入下列哪个静脉","o":["颈内静脉","头臂静脉","颈总静脉","腋静脉","锁骨下静脉"],"a":4,"e":"颈外静脉是颈部最大的浅静脉，由下颌后静脉后支与耳后静脉等汇合而成，沿胸锁乳突肌表面下行，最终注入锁骨下静脉，故汇入锁骨下静脉。颈内静脉为另一种颈部深静脉；头臂静脉由颈内静脉与锁骨下静脉合成；腋静脉为上肢静脉延续，均非颈外静脉注入处"},{"q":"坐骨大切迹位于","o":["坐骨棘的上方","坐骨棘的下方","髂前上棘下方","髂前上棘上方","髂后上棘上方"],"a":0,"e":"坐骨大切迹位于坐骨棘与髂后下棘之间，即坐骨棘的上方，有梨状肌、坐骨神经等通过；坐骨小切迹位于坐骨棘下方，有阴部神经等通过。髂前上棘、髂后上棘为髂骨的标志，与坐骨大切迹位置不同，上下切迹以坐骨棘为界，易混淆"},{"q":"下面关于面肌的描述，错误的是","o":["全是皮肌","有开闭眼、口、鼻孔的作用","人类特别发达","能显示喜、怒、哀、乐","枕额肌、颊肌、颞肌都属于面肌"],"a":4,"e":"颞肌属于咀嚼肌，由下颌神经支配，并非面肌，故'枕额肌、颊肌、颞肌都属于面肌'错误。面肌为皮肌，起于皮肤止于皮肤，由面神经支配，可开闭眼、口、鼻孔并表达喜怒哀乐，人类面部表情肌特别发达；枕额肌、颊肌确属面肌"},{"q":"眼神经不分布于","o":["眼球","硬脑膜","鼻背部的皮肤","下睑的皮肤","泪腺"],"a":3,"e":"眼神经为三叉神经第一支，分布于眼球、硬脑膜、泪腺、鼻背皮肤及上睑皮肤等，下睑皮肤由上颌神经的眶下神经支配，不属眼神经分布区。眼球、硬脑膜、鼻背皮肤、泪腺均在眼神经分支范围内，而下睑与上颌神经关系明确，是眼神经与上颌神经分布的常见鉴别点"},{"q":"有关骨髓腔的描述，正确的是","o":["位于骨骺内","位于长骨的骨干内","成人骨髓腔内含红骨髓","小儿骨髓腔内含黄骨髓","骨髓腔逐渐萎缩变小"],"a":1,"e":"骨髓腔是长骨骨干内的管状腔隙，成人主要容纳黄骨髓。骨骺内为松质骨，无成形骨髓腔，A项归属错误；成人骨髓腔内为黄骨髓，红骨髓主要保留在扁骨与长骨骺端，C项把两者颠倒；小儿骨髓腔内为红骨髓，随年龄渐被黄骨髓替代，D项亦颠倒。骨髓腔随骨干生长并不萎缩，E项不对"},{"q":"胸主动脉的分支中没有","o":["肋间后动脉","肋下动脉","肋间前动脉","膈上动脉","食管支、心包支"],"a":2,"e":"胸主动脉壁支包括肋间后动脉、肋下动脉和膈上动脉，脏支有食管支、心包支、支气管支等。肋间前动脉实为胸廓内动脉的分支，走行于肋间隙前部，并非发自胸主动脉，C项为本题所选。肋间后动脉才起自胸主动脉并向后走行，与肋间前动脉一前一后常被混淆；膈上动脉、食管支与心包支均为胸主动脉直接分支"},{"q":"关于腹膜腔的描述，正确的是","o":["是一个与体外不通的浆膜间隙","由脏、壁两层腹膜互相移行而成","腹、盆腔脏器有的位于腹膜腔之内，有的位于腹膜腔之外","内有大部分器官","是区分内位器官和外位器官的分界线"],"a":1,"e":"腹膜腔由脏腹膜与壁腹膜相互移行围成，是潜在的浆膜间隙，B项正确。A项与体外不通不符，女性可经生殖管道与外界相通。C项错在器官是位于腹腔而非腹膜腔内，内位器官被腹膜包裹才突入腹膜腔。D项腹腔内并非大部分器官都在腹膜腔内。E项区分内外位器官依据是腹膜覆盖程度，而非分界线"},{"q":"关于胃壁的说法，错误的是","o":["肌层只有两层平滑肌","分四层","最内层是黏膜层","外膜为浆膜","幽门处有幽门瓣"],"a":0,"e":"胃壁由内向外分黏膜、黏膜下层、肌层、浆膜四层，最内层为黏膜，外膜为浆膜，幽门处黏膜形成幽门瓣。胃的肌层较特殊，除内环、外纵两层外还有最内层斜行肌，共三层平滑肌，A项称仅两层与实际不符，为错误项。B、C、D、E所述分层、黏膜位置、浆膜外膜及幽门瓣均正确"},{"q":"锥体交叉位于","o":["中脑上部","中脑下部","脑桥","延髓上部","延髓下部"],"a":4,"e":"锥体交叉位于延髓下部，是延髓锥体内大部分皮质脊髓束纤维交叉至对侧形成的结构，交叉后进入脊髓。中脑上、下部与脑桥均无此结构，A、B、C项部位过高。延髓上部有锥体但不发生交叉，交叉集中在延髓下端近枕骨大孔处，故D项不如E项准确"},{"q":"使瞳孔缩小的肌是","o":["外直肌","内直肌","上直肌","瞳孔括约肌","瞳孔开大肌"],"a":3,"e":"瞳孔括约肌呈环形排列于虹膜游离缘，收缩时使瞳孔缩小，受动眼神经副交感纤维支配。瞳孔开大肌为放射状肌，收缩使瞳孔散大，受交感神经支配，E项作用相反。外直肌、内直肌、上直肌均为眼球外肌，司眼球转动，与瞳孔口径变化无关，A、B、C项均不参与瞳孔缩小"},{"q":"对外耳道的叙述，下列错误的是","o":["是从外耳门至鼓膜的管道","外2/3为软骨部，内1/3为骨部","骨性都是颞骨鳞部和鼓部围成的短管","婴儿的外耳道几乎全部由软骨支持","外耳道表面的皮肤富含感觉神经末梢"],"a":1,"e":"外耳道是起自外耳门止于鼓膜的管道，外侧约1/3为软骨部，内侧约2/3为骨部，骨部由颞骨鳞部与鼓部围成。题干将比例写为外2/3软骨部、内1/3骨部，正好颠倒，B项为错误项。婴幼儿外耳道骨部未发育，几乎全由软骨支持，D项成立；外耳道皮肤富含感觉神经末梢且与骨膜紧贴，C、E正确"},{"q":"伸肘时，臂与前臂之间形成的向外侧的钝角是","o":["颈干角","提携角","倾斜角","肘后三角","外侧角"],"a":1,"e":"提携角是伸肘并前臂旋后时，肱骨纵轴与尺骨纵轴之间向外侧形成的钝角，正常约10°～15°，女性略大。颈干角为股骨颈与股骨干之间的角，属下肢骨，A项不符。倾斜角、外侧角非前臂专属命名，肘后三角是肱骨内、外上髁与尺骨鹰嘴构成的三角形结构，用于判断肘关节脱位，C、D、E项所指各异"},{"q":"关于口腔，下列说法正确的是","o":["由上、下牙龈分为前外侧部和后内侧部","为牙与唇、颊之间的空隙","牙与腭之间的空隙","上、下牙咬合时，口腔前庭与固有口腔不相通","借咽峡与口咽相通"],"a":4,"e":"口腔向后经咽峡与口咽相交通，咽峡由腭帆后缘、左右腭舌弓及舌根围成，E项正确。A项错在划分依据：口腔前庭与固有口腔的分界是上、下牙弓，而非牙龈。B、C项仅描述局部间隙，不是口腔的分部。D项错误，上、下牙咬合时二者仍可借最后磨牙后方的间隙相通"},{"q":"尺神经损伤容易导致以下哪块肌肉瘫痪","o":["肱桡肌","拇收肌","拇短展肌","拇短屈肌","指浅屈肌"],"a":1,"e":"拇收肌受尺神经深支支配，尺神经损伤后该肌瘫痪，拇指内收无力，Froment征阳性，B项正确。拇短展肌、拇短屈肌主要由正中神经支配，C、D项不属尺神经。肱桡肌由桡神经支配，指浅屈肌由正中神经支配，A、E项神经归属不同"},{"q":"小脑水平切面的白质中，呈皱缩口袋状的神经核是","o":["球状核","闩状核","顶核","齿状核","下橄榄核"],"a":3,"e":"齿状核是小脑核中最大者，位于小脑半球白质中心，切面呈皱缩的口袋状，门朝前内侧，传出纤维经小脑上脚出小脑，D项正确。顶核位于小脑蚓部白质内，靠近中线，C项位置不符。球状核与栓状核位于齿状核内侧，体积小，A、B项形态位置均不同。下橄榄核位于延髓，不属小脑核，E项明显错误"},{"q":"关于股四头肌的描述，正确的是","o":["股直肌起自髂前上棘","止于胫骨、腓骨上端","能伸髋关节","能屈膝关节","肌腱向下延续为髌韧带"],"a":4,"e":"股四头肌腱包绕髌骨后向下延续为髌韧带，止于胫骨粗隆，E项正确。股直肌起自髂前下棘而非髂前上棘，A项起点描述错误。四肌腱经髌韧带止于胫骨粗隆，不附着腓骨，B项不对。股四头肌主要功能为伸膝，仅股直肌可协助屈髋，不能伸髋，C项混淆。屈膝主要由腘绳肌完成，D项属拮抗作用"},{"q":"参与构成距小腿关节的骨是","o":["胫骨、腓骨、跟骨","胫骨、腓骨、距骨","胫骨、距骨","腓骨、距骨","胫骨、跟骨"],"a":1,"e":"距小腿关节即踝关节，由胫骨下端、腓骨下端与距骨滑车构成，屈伸运动为主，B项正确。跟骨参与距跟关节构成，不直接构成踝关节，A、E项含跟骨属错误。C项缺腓骨、D项缺胫骨，均不完整，踝关节为胫腓骨共同夹持距骨的踝穴结构，二者缺一不可"},{"q":"关于前列腺的描述，正确的是","o":["与膀胱底相邻","有尿道穿过","为男性生殖腺之一","能分泌少量的雄激素","体的前面有一前列腺沟"],"a":1,"e":"前列腺包绕尿道起始部，尿道前列腺部穿经其实质，B项正确。前列腺底邻接膀胱颈，而非膀胱底，A项部位表述不准。前列腺为男性附属腺体，并非生殖腺，也不分泌雄激素，C、D项错误。前列腺沟位于腺体后面，直肠指诊可触及，E项说前面与事实相反"},{"q":"关于腹膜腔的描述，错误的是","o":["由脏、壁两层腹膜互相移行而成","腔内有少量的浆液","男性腹膜腔为封闭的腔隙","女性腹膜腔与体外相通","腹腔脏器、盆腔脏器均位于腹膜腔之内"],"a":4,"e":"腹膜腔是脏、壁腹膜间的潜在间隙，仅有内位器官突入其内，外位与间位器官位于腹膜腔之外，故E项均位于腹膜腔之内错误。腔内含少量浆液起润滑作用，B项成立。男性腹膜腔完全封闭，C项正确；女性可经输卵管、阴道与外界相通，D项成立。A项所述脏壁腹膜移行形成腹膜腔亦正确"},{"q":"管理右下肢末端一般感觉的大脑皮质区位于","o":["左半球中央后回下部","右半球中央后回下部","左半球中央旁小叶后部","右半球中央旁小叶后部","左半球中央后回中部"],"a":2,"e":"一般躯体感觉中枢位于中央后回和中央旁小叶后部，身体各部分呈倒置排列，下肢末端代表区在中央旁小叶后部，且为对侧支配，右下肢由左侧半球管理，C项正确。中央后回下部管理头面部，A、B项部位偏低。右半球管理左侧肢体，B、D项侧别错误。中央后回中部管理上肢与躯干，E项不符下肢末端定位"},{"q":"不属于腹膜内位器官的是","o":["胃","乙状结肠","胆囊","空肠","横结肠"],"a":2,"e":"胆囊仅底、体前壁被腹膜覆盖，属腹膜间位器官，不属于内位器官，C项为所选。胃、空肠、乙状结肠、横结肠表面几乎全被腹膜包裹并有一定活动度，均为内位器官，A、B、D、E项归属正确。内位与间位的区别在于腹膜覆盖是否完整及活动度大小，胆囊因贴附于肝下面而活动受限"},{"q":"支配臂前群肌的神经为","o":["正中神经","尺神经","桡神经","肌皮神经","腋神经"],"a":3,"e":"肌皮神经发自臂丛外侧束，穿喙肱肌后行于肱二头肌与肱肌之间，支配臂前群肌，D项正确。正中神经主要支配前臂屈肌群和手肌，A项不符。桡神经支配臂后群及前臂伸肌，C项属后群。尺神经支配前臂尺侧屈肌和手内在肌，B项不属臂前群。腋神经支配三角肌与小圆肌，E项管理肩部"},{"q":"从颅底的眶上裂通过的脑神经为","o":["嗅神经","视神经","迷走神经","舌下神经","动眼神经"],"a":4,"e":"眶上裂通过动眼神经、滑车神经、展神经及三叉神经眼神经，故动眼神经经此入眶，E项正确。嗅神经经筛孔入颅，A项通道不同。视神经经视神经管入眶，B项不符。迷走神经经颈静脉孔出颅，C项位置在颅后。舌下神经经舌下神经管出颅，D项亦非眶上裂"},{"q":"在脑干的腹侧面，延髓与脑桥的分界标志是","o":["锥体","橄榄","锥体交叉","延髓脑桥沟","基底沟"],"a":3,"e":"延髓脑桥沟是脑干腹侧面延髓与脑桥之间的横行沟，自内侧向外侧依次有展神经、面神经、前庭蜗神经根出脑，为二者分界标志，D项正确。锥体与锥体交叉位于延髓腹侧中线，A、C项是延髓本身结构。橄榄位于锥体外侧，B项仍在延髓范围。基底沟位于脑桥腹侧中线，是脑桥自身标志，E项不属分界"},{"q":"前臂的旋转运动","o":["由肘关节单独完成","由桡腕关节单独完成","由肘关节和桡腕关节共同完成","由桡尺近侧关节、前臂骨间膜和桡尺远侧关节共同完成","由肩关节和肘关节、腕关节共同完成"],"a":3,"e":"前臂旋前、旋后是桡骨围绕尺骨的运动，需桡尺近侧关节、桡尺远侧关节与前臂骨间膜三者协同完成，D项正确。肘关节司屈伸，桡腕关节司腕部屈伸与侧屈，均不参与前臂旋转，A、B、C项混淆了关节功能。肩关节活动范围虽大，但与前臂旋转无直接关系，E项范围过大"},{"q":"以下对下颌神经的叙述，错误的是","o":["是三叉神经三大分支中最粗大的一支","为混合性神经","其自颅底的圆孔出颅","耳颞神经为其分支","其分支咀嚼肌神经属运动性神经"],"a":2,"e":"下颌神经为三叉神经最粗大的分支，属混合性神经，经卵圆孔出颅，其分支咀嚼肌神经为运动性，耳颞神经为其分支。题干称经圆孔出颅有误，圆孔是上颌神经的通道，C项为错误项。A、B、D、E所述粗细、性质、分支与功能均符合下颌神经特点。卵圆孔与圆孔相邻而职能不同，是常见设错点"},{"q":"组成喙肩弓的结构是","o":["喙突、喙肩韧带","喙突、喙肩韧带、肩峰","喙突、喙锁韧带、肩峰","喙突、喙肱韧带、肩峰","喙肩韧带、肩峰"],"a":1,"e":"喙肩弓由肩胛骨喙突、喙肩韧带与肩峰共同构成，位于肩关节上方，可防止肱骨头向上方脱位，B项正确。A项缺肩峰，E项缺喙突，均不完整。喙锁韧带连接喙突与锁骨，属锁骨连结结构，C项不参与喙肩弓。喙肱韧带为盂肱关节囊的加强韧带，D项名称与归属均不同"},{"q":"外踝位于","o":["胫骨下端","胫骨上端","腓骨上端","腓骨下端","股骨下端"],"a":3,"e":"外踝为腓骨下端向下突出的部分，位置较内踝低且偏后，与距骨构成踝关节外侧壁，D项正确。胫骨下端内侧突起为内踝，A项属内踝。胫骨上端参与膝关节构成，B项部位在上。腓骨上端为腓骨头，不形成外踝，C项混淆上下端。股骨下端构成膝关节，与踝部无关，E项错误"},{"q":"临床上确认空肠起始部的标志是","o":["十二指肠上曲","十二指肠纵襞","十二指肠悬肌","十二指肠升部","十二指肠下曲"],"a":2,"e":"十二指肠悬肌即Treitz韧带，由十二指肠升部固定于腹后壁，是手术中确认空肠起始部的重要标志，C项正确。十二指肠上曲、下曲为十二指肠的弯曲部，A、E项不作此标志。十二指肠纵襞是降部后内侧壁的纵行皱襞，其上有十二指肠大乳头开口，B项功能不同。十二指肠升部是十二指肠末段而非空肠起始标志，D项不符"},{"q":"关于小脑延髓池的描述错误的是","o":["位于小脑与延髓之间","位于硬膜外隙内","位于蛛网膜下隙内","临床上可在此进行穿刺，抽取脑脊液","是脑蛛网膜下隙扩大部分"],"a":1,"e":"小脑延髓池为小脑与延髓之间蛛网膜下隙扩大形成，内充脑脊液，临床可经此穿刺取脑脊液，故B项位于硬膜外隙内错误。硬膜外隙位于椎管骨膜与硬脊膜之间，不含脑脊液。A、C、D、E所述位置、属蛛网膜下隙、穿刺用途与扩大形成均正确"},{"q":"关于肱骨形态的描述，何者错误","o":["位于臂部，分为一体两端","上端有球形的肱骨头","上端与体交界处稍细，称为外科颈","肱骨体后面有桡神经沟","内上髁后方有尺神经沟"],"a":1,"e":"肱骨位于臂部，分为一体两端，上端有朝向内上的肱骨头，头与体交界处稍细为外科颈，体后面有桡神经沟通过，内上髁后方有尺神经沟容纳尺神经。肱骨头实际呈半球形而非正球形，B项以球形描述不够准确，为本题错误项。A、C、D、E所述位置、外科颈、桡神经沟与尺神经沟均符合肱骨形态"},{"q":"骶丛位于","o":["腰方肌深面","腰大肌深面","腰大肌浅层","梨状肌前面","梨状肌后面"],"a":3,"e":"骶丛由腰骶干和骶、尾神经前支组成，位于盆腔内梨状肌前面、骶骨与梨状肌之间，E项正确。腰方肌深面、腰大肌深面为腰丛相关位置，A、B项不符。腰大肌浅层无此神经丛，C项错误。梨状肌后面为臀上、下血管与神经出入梨状肌下孔处，并非骶丛所在，D项方向相反"},{"q":"嗅神经通过颅底什么结构进入颅腔","o":["枕骨大孔","圆孔","棘孔","卵圆孔","筛孔"],"a":4,"e":"嗅神经由鼻腔嗅黏膜内的嗅细胞轴突组成，穿筛骨筛板的筛孔进入颅腔，终止于嗅球，E项正确。枕骨大孔有延髓与椎动脉通过，A项不符。圆孔通过上颌神经，B项错误。棘孔有脑膜中动脉通过，C项非神经通道。卵圆孔通过下颌神经，D项属三叉神经另一分支"},{"q":"子宫肿瘤的好发部位是","o":["子宫底","子宫体","子宫峡","子宫颈","子宫角"],"a":3,"e":"子宫颈是子宫肿瘤最常见的发生部位，尤其宫颈阴道部鳞状上皮与柱状上皮交界处为宫颈癌好发区，D项正确。子宫底、体为宫体癌相对好发区，但整体发病率低于宫颈，A、B项不是最好发。子宫峡为宫体与宫颈之间的狭窄部，C项非肿瘤好发。子宫角为输卵管入口处，E项不符"},{"q":"肝的左纵沟后半部容纳的是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","镰状韧带"],"a":1,"e":"肝左纵沟前半部由肝圆韧带占据，后半部为静脉韧带所在，故静脉韧带位于左纵沟后半部，B项正确。肝圆韧带位于前半部，A项前后位置颠倒。胆囊位于肝下面的胆囊窝，C项属右纵沟前部。下腔静脉位于右纵沟后部的腔静脉沟，D项归右半。镰状韧带位于肝膈面，构成左纵沟前部，E项与静脉韧带位置不同"},{"q":"可伸肘关节，并能协助伸肩关节的肌肉是","o":["肱二头肌","肱三头肌","喙肱肌","肱桡肌","桡侧腕屈肌"],"a":1,"e":"肱三头肌为伸肘的主要肌，其长头起自肩胛骨盂下结节，跨越肩关节，可协助肩关节后伸与内收，B项正确。肱二头肌为屈肘、屈肩肌，作用相反，A项不符。喙肱肌主司肩关节前屈内收，C项不伸肘。肱桡肌为屈肘肌，D项作用相反。桡侧腕屈肌屈腕屈肘，E项不能伸肘关节"},{"q":"下列关于蛛网膜下隙的描述，错误的是","o":["位于硬脊膜与蛛网膜之间","位于蛛网膜与软膜之间","脊髓蛛网膜下隙与脑蛛网膜下隙相通","内充满脑脊液","脊髓下端蛛网膜内有脊髓马尾"],"a":0,"e":"蛛网膜下隙位于蛛网膜与软膜之间，内充满脑脊液，脊髓与脑的蛛网膜下隙彼此相通，故A项位于硬脊膜与蛛网膜之间错误。硬脊膜与蛛网膜之间仅为潜在的硬膜下隙，无脑脊液。B、C、D、E所述位置、相通、脑脊液内容及马尾位于脊髓下端蛛网膜下隙内均正确"},{"q":"以下对白交通支的叙述正确的是","o":["发自椎旁神经节","发自椎前神经节","离开脊神经到交感干","属节后纤维","连于交感干与31对脊神经前支之间"],"a":2,"e":"白交通支为交感神经节前纤维，起自脊髓侧角，随脊神经前支出椎间孔后离开脊神经进入交感干，因有髓鞘而色白，C项正确。白交通支发自脊髓侧角而非椎旁或椎前神经节，A、B项来源错误。其内含节前纤维，D项节后纤维属灰交通支。E项把连接范围扩大到31对脊神经前支，实际仅见于胸1至腰3节段，范围描述不准"},{"q":"关于足背动脉的描述，不正确的是","o":["是胫前动脉的延续","行于拇长深肌腱内侧","在内、外踝连线中点处可摸其搏动","其足底深支参与形成足底动脉弓","中医学称之为“趺阳脉”"],"a":1,"e":"足背动脉为胫前动脉的延续，在踝前位于拇长伸肌腱与趾长伸肌腱之间，实际行于拇长伸肌腱外侧，故B项行于拇长深肌腱内侧方向错误。其在内、外踝连线中点可触及搏动，C项正确。足底深支参与构成足底动脉弓，D项成立；中医称趺阳脉，E项亦对；A项延续关系正确"},{"q":"下列关于射精管的描述，正确的是","o":["穿尿道膜部","穿前列腺实质","有贮存精子的功能","开口于尿道球部","开口于尿道海绵体部"],"a":1,"e":"射精管由输精管壶腹末端与精囊腺排泄管汇合而成，穿经前列腺实质后开口于尿道前列腺部，B项正确。其穿过的是前列腺部而非尿道膜部，A项部位错误。射精管无贮存精子功能，贮存主要在附睾与精囊，C项不符。开口于尿道前列腺部而非球部或海绵体部，D、E项开口位置错误"},{"q":"牵拉肩胛骨向前的是","o":["胸大肌","肩胛下肌","前锯肌","斜方肌","菱形肌"],"a":2,"e":"前锯肌起自上位肋骨外面，止于肩胛骨内侧缘和下角，收缩时拉肩胛骨向前紧贴胸廓，并可上回旋，C项正确。胸大肌主要作用于肱骨，使肩关节内收内旋，A项不直接牵拉肩胛骨。肩胛下肌为肩袖肌，稳定肩关节，B项作用不同。斜方肌使肩胛骨后缩、上提，D项方向相反。菱形肌拉肩胛骨向后上，E项亦为后缩肌"},{"q":"有关动脉的描述，错误的是","o":["由心室发出","输送血液离心","越分越细","移行为毛细血管","腔内全是动脉血"],"a":4,"e":"动脉是引导血液离开心脏的血管，由心室发出，越分越细，最终移行为毛细血管，故A、B、C、D项描述正确。但动脉内并非全是动脉血，肺动脉内流的是静脉血，E项以偏概全为错误项。动脉血与静脉血的区分依据是含氧量，而非血管名称，肺动脉与肺静脉是常见反例"},{"q":"下列关于脊髓丘脑束的描述，正确的是","o":["起自脊髓灰质板层Ⅰ～Ⅴ","是后根外侧部细纤维的直接延续","经灰质连合至对侧外侧索和前索上行","传导同侧的痛、温觉和粗触压觉","一侧损伤时出现对侧痛、温觉障碍"],"a":4,"e":"脊髓丘脑束传导痛、温觉和粗触压觉，其纤维在脊髓内经白质前连合交叉至对侧后上行，故一侧损伤表现为损伤平面以下对侧痛、温觉障碍，E项正确。该束起自脊髓灰质后角细胞，并非板层Ⅰ～Ⅴ的笼统表述，A项不准。B项描述的是后索薄束、楔束。C项交叉后在对侧索上行但灰质连合表述不确切。D项同侧与交叉事实相反"},{"q":"腕桡侧副韧带和腕尺侧副韧带加强的关节是","o":["桡腕关节","腕骨间关节","腕掌关节","肘关节","腕中关节"],"a":0,"e":"桡腕关节由桡骨下端与舟骨、月骨、三角骨构成，其周围有腕桡侧副韧带和腕尺侧副韧带加强，A项正确。腕骨间关节位于腕骨之间，由骨间韧带连接，B项不符。腕掌关节由远侧腕骨与掌骨底构成，C项非此二韧带所加强。肘关节的侧副韧带为桡侧、尺侧副韧带，名称相似但部位不同，D项混淆。腕中关节为腕骨间关节的一部分，E项不符"},{"q":"关于胃的叙述，正确的是","o":["幽门管与角切迹之间的部分，称幽门窦","在中等充盈时，位于右季肋区","分为胃弯、胃体和胃窦","角切迹将胃窦分为幽门窦和幽门管","胃入口称幽门，出口称贲门"],"a":0,"e":"胃幽门部以中间沟为界分为幽门窦与幽门管，幽门窦位于角切迹与幽门管之间，A项正确。中等充盈时胃大部位于左季肋区与腹上区，B项右季肋区错误。胃分为贲门部、胃底、胃体和幽门部，C项分部名称不对。角切迹是胃体与幽门部的分界标志，D项把分界关系说反。胃入口为贲门、出口为幽门，E项正好颠倒"},{"q":"可以维持子宫前倾位的主要结构是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":2,"e":"子宫圆韧带起自子宫角，经腹股沟管止于大阴唇，主要作用是维持子宫前倾位，C项正确。子宫阔韧带限制子宫向两侧移动，A项作用不同。卵巢悬韧带为固定卵巢的韧带，B项与子宫位置无关。子宫主韧带固定子宫颈、防止子宫脱垂，D项不主司前倾。子宫骶韧带牵拉宫颈向后上，维持子宫前屈，E项为前屈而非前倾"},{"q":"展神经通过颅底什么结构入眶","o":["筛孔","眶上裂","圆孔","卵圆孔","棘孔"],"a":1,"e":"展神经起自脑桥展神经核，经海绵窦后穿眶上裂入眶，支配外直肌，B项正确。筛孔为嗅神经通道，A项不符。圆孔通过上颌神经，C项错误。卵圆孔通过下颌神经，D项属三叉神经分支。棘孔有脑膜中动脉通过，E项非脑神经路径。眶上裂同时通过动眼、滑车、展神经及眼神经，为眼神经与眼动脉入眶要道"},{"q":"关于食管的说法，正确的是","o":["分为颈、胸两部分","位于气管与甲状腺峡部之间","下端在第9胸椎处接胃","上端在第6颈椎下缘处与咽相续","颈部位于喉的后方"],"a":3,"e":"食管上端平第6颈椎下缘与咽相接，下端平第11胸椎高度接胃贲门，D项正确。食管分颈、胸、腹三部，A项遗漏腹部。食管位于气管后方、脊柱前方，与甲状腺峡无此邻接关系，B项位置错误。下端约在第11胸椎而非第9胸椎，C项平面偏高。颈段食管位于喉与气管后方，E项表述含混且非最佳"},{"q":"视觉传导通路中节细胞发出的轴突不构成","o":["视神经","视交叉外侧部纤维","视交叉中间部纤维","视束","视辐射"],"a":4,"e":"视网膜节细胞的轴突在视网膜内汇成视神经，经视交叉后延续为视束，终止于外侧膝状体换元，故视神经、视交叉与视束的纤维均为节细胞轴突，A、B、C、D项均属其构成。视辐射是外侧膝状体换元后投射至视皮质的纤维，并非节细胞轴突直接形成，E项为本题所选"},{"q":"卵巢固有韧带位于卵巢的","o":["上端","下端","内侧面","外侧面","前缘"],"a":1,"e":"卵巢固有韧带连于卵巢下端与子宫角之间，故其位于卵巢下端，B项正确。卵巢上端又称输卵管端，与输卵管漏斗及伞相接，A项端别相反。内侧面与外侧面为卵巢的两个面，C、D项非韧带附着端。前缘为卵巢系膜缘、有血管神经出入，E项为系膜附着处，均非固有韧带所在"},{"q":"对内脏神经系统内容描述错误的是","o":["内脏神经系统按照分布部位的不同可分为中枢部和周围部","内脏神经系统的周围部主要分布于内脏、心血管、平滑肌和腺体","内脏运动神经又分为交感神经和副交感神经两部分","内脏运动神经受人的意志控制","内脏感觉神经的初级神经元位于脑神经节和脊神经节内"],"a":3,"e":"内脏运动神经又称自主神经，分为交感与副交感神经，其活动一般不受人的意志直接支配，故D项受意志控制错误。内脏神经按分布分中枢部与周围部，A项正确；周围部主要分布于内脏、心血管、平滑肌和腺体，B项成立；内脏感觉神经初级神经元位于脑、脊神经节内，E项亦正确"},{"q":"颅后窝占位性病变，或小脑幕下颅内压增高，可能导致部分小脑经枕骨大孔突出。下列哪一个小脑结构最有可能与此有关","o":["小脑蚓","小脑扁桃体","小脑上脚","小脑中脚","小脑下脚"],"a":1,"e":"小脑扁桃体位于小脑半球下面后内侧，紧邻枕骨大孔，颅后窝占位或小脑幕下压力增高时，可经枕骨大孔向下疝出，形成小脑扁桃体疝，压迫延髓生命中枢，B项正确。小脑蚓位于正中，A项不易疝出。小脑上、中、下脚为小脑与脑干相连的纤维束，位置深在，C、D、E项均非疝出结构"},{"q":"眼上静脉和眼下静脉注入","o":["上矢状窦","下矢状窦","横窦","海绵窦","内眦静脉"],"a":3,"e":"眼上静脉与眼下静脉均向后穿眶上裂注入海绵窦，海绵窦位于蝶鞍两侧，故D项正确。上矢状窦位于大脑镰上缘，A项不符。下矢状窦行于大脑镰下缘，B项错误。横窦位于枕骨内面，承接乙状窦，C项位置不同。内眦静脉位于面部内眦处，与眼静脉相交通并注入面静脉，E项为引流去向而非眼静脉注入处"},{"q":"一侧内侧丘系来自","o":["同侧脊神经节中枢突","对侧后角细胞轴突","对侧薄束核和楔束核轴突","薄束和楔束的纤维交叉后","白质前连合的纤维交叉后"],"a":2,"e":"薄束与楔束上行至延髓分别终止于薄束核与楔束核，核内神经元轴突在延髓交叉后上行形成内侧丘系，故一侧内侧丘系主要来自对侧薄束核、楔束核轴突，C项正确。A项脊神经节中枢突构成后索，并非内侧丘系来源。D项薄束楔束为一级纤维，其本身不交叉。E项白质前连合交叉属脊髓丘脑束，B项后角细胞轴突亦属脊髓丘脑束"},{"q":"关于膀胱的叙述，正确的是","o":["位于骨盆腔内，在耻骨联合的后方","男性膀胱底邻前列腺","女性膀胱底邻接直肠","男性膀胱下方邻接盆膈","是腹膜外位器官"],"a":0,"e":"空虚膀胱位于小骨盆腔前部，在耻骨联合后方，充盈时可上升至腹腔，A项正确。男性膀胱底邻接精囊腺与输精管壶腹，下方邻接前列腺，B项把邻接前列腺归为膀胱底不准确。女性膀胱底邻接子宫与阴道，而非直肠，C项错误。D项男性膀胱下方邻接前列腺与盆膈，表述不确切。膀胱为腹膜间位器官，E项外位错误"},{"q":"临床上关于子宫下段说法正确的是","o":["由非孕时的子宫峡部伸展形成","孕中期的子宫颈扩展为宫腔的一部分","临产后子宫颈伸展可达7～10cm","为临产后的子宫颈","孕16周扩展成宫腔的一部分"],"a":0,"e":"子宫下段由非孕时的子宫峡部于妊娠晚期逐渐伸展拉长形成，临产后可延长至7～10cm，成为产道一部分，A项正确。B项把子宫颈扩展误作下段，宫颈扩张为宫口开大，并非下段来源。C、D项将下段等同于子宫颈，混淆了宫颈与峡部。E项时间描述不准，峡部主要在孕晚期及临产后伸展，而非单纯孕16周"},{"q":"躯体运动中枢位于","o":["中央后回和中央旁小叶后部","中央前回和中央旁小叶前部","颞横回","额下回后部","角回"],"a":1,"e":"躯体运动中枢主要位于中央前回和中央旁小叶前部，为锥体系发源区，身体代表区呈倒置安排，B项正确。中央后回与中央旁小叶后部为躯体感觉中枢，A项属感觉区。颞横回为听觉中枢，C项不符。额下回后部为运动性语言中枢，D项司语言表达。角回为视觉性语言中枢，E项参与阅读"},{"q":"位于侧脑室下角底壁，严重受损时可导致记忆障碍的结构是","o":["杏仁体","豆状核","海马","外侧膝状体","尾状核尾"],"a":2,"e":"海马位于侧脑室下角底壁，属边缘系统，参与学习与记忆形成，双侧严重损伤可致近事记忆障碍，C项正确。杏仁体位于侧脑室下角前端上方，主要与情绪有关，A项功能位置不同。豆状核、尾状核尾属纹状体，参与运动调节，B、E项不符。外侧膝状体为视觉中继核，D项不涉记忆"},{"q":"关于锁骨形态的描述，正确的是","o":["呈“～”形弯曲","内端扁平","外端粗大","内侧2/3凸向后","骨折多在中、内1/3交界处"],"a":0,"e":"锁骨呈～形弯曲，内侧2/3凸向前、外侧1/3凸向后，A项正确。内端即胸骨端粗大，外端即肩峰端扁平，B、C项将两端形态说反。锁骨骨折多发生在中、外1/3交界处，而非中、内1/3，E项部位描述错误。D项内侧2/3凸向后与事实相反，实际凸向前"},{"q":"关于硬膜外隙的描述，正确的是","o":["位于硬脊膜与蛛网膜之间","位于椎管内面骨膜与硬脊膜之间","位于大脑脚之间","内有马尾和脑脊液","与颅腔相通"],"a":1,"e":"硬膜外隙位于椎管内面骨膜与硬脊膜之间，内含脂肪组织与椎内静脉丛，为硬膜外麻醉注药部位，B项正确。硬脊膜与蛛网膜之间为硬膜下隙，A项位置错误。大脑脚之间为脚间窝，属脑内结构，C项无关。马尾与脑脊液位于蛛网膜下隙，D项内容错误。硬膜外隙上端在枕骨大孔处闭合，不与颅腔相通，E项错误"},{"q":"位于颅腔内的内分泌器官是","o":["胸腺","甲状腺","松果体","肾上腺","甲状旁腺"],"a":2,"e":"松果体位于间脑后部、第三脑室后方，处于颅腔内，可分泌褪黑素，C项正确。胸腺位于上纵隔前部，A项不在颅内。甲状腺与甲状旁腺位于颈部，B、E项位置不符。肾上腺位于腹膜后隙、肾上方，D项在腹腔。颅腔内内分泌器官主要为松果体与垂体，本题选项中仅松果体符合"},{"q":"肋膈隐窝由下列哪些结构转折形成","o":["肋胸膜与膈胸膜","肋胸膜与纵隔胸膜","纵隔胸膜与膈胸膜","纵隔胸膜与脏胸膜","肋胸膜与胸膜顶"],"a":0,"e":"肋膈隐窝由肋胸膜与膈胸膜相互转折移行形成，是胸膜腔位置最低、容量最大的隐窝，吸气时肺下缘也不能完全充满，A项正确。肋胸膜与纵隔胸膜转折形成肋纵隔隐窝，B项不符。纵隔胸膜与膈胸膜转折为膈纵隔隐窝，C项不同。脏胸膜与壁胸膜在肺根处移行，D项非隐窝构成。胸膜顶为壁胸膜向上突入颈根部部分，E项不形成肋膈隐窝"},{"q":"关于喉的描述，正确的是","o":["环甲肌收缩时紧张声带","环甲肌由喉返神经支配","甲状软骨、环状软骨之间只借韧带连结","会厌位于喉的后方","喉室位于前庭襞上方"],"a":0,"e":"环甲肌起自环状软骨弓，止于甲状软骨下缘，收缩时使甲状软骨前倾，从而紧张并伸长声带，A项正确。环甲肌由喉上神经外支支配，喉返神经支配除环甲肌外的喉内肌，B项神经归属错误。甲状软骨与环状软骨之间除韧带外还有环甲肌相连，C项只借韧带不符。会厌位于喉入口前上方，D项位置错误。喉室位于前庭襞与声襞之间，E项前庭襞上方不对"},{"q":"由膝关节囊滑膜层形成的结构是","o":["前交叉韧带","后交叉韧带","翼状襞","胫侧副韧带","腓侧副韧带"],"a":2,"e":"翼状襞由膝关节囊滑膜层向关节腔内折叠突出形成，内含脂肪组织，充填于关节腔空隙，C项正确。前、后交叉韧带为关节内纤维韧带，由致密结缔组织构成，非滑膜形成，A、B项不符。胫侧副韧带、腓侧副韧带为关节囊外的纤维加强结构，D、E项来源不同。滑膜层还可形成髌上囊等，但交叉、侧副韧带均属纤维性结构"},{"q":"膈的主动脉裂孔位置高度","o":["平第8胸椎","平第9胸椎","平第10胸椎","平第11胸椎","平第12胸椎"],"a":4,"e":"主动脉裂孔位于膈脚之间，平第12胸椎高度，有主动脉与胸导管通过，E项正确。平第8胸椎为腔静脉孔，通过下腔静脉，A项对应错误。平第9、10胸椎接近食管裂孔，B、C项不符。平第11胸椎无主要裂孔，D项不对。三个裂孔中主动脉裂孔位置最低，食管裂孔居中，腔静脉孔最高"},{"q":"有关静脉的描述，错误的是","o":["起于毛细血管网","引导血液回心","越合越粗","注入到心房","均有静脉瓣"],"a":4,"e":"静脉起于毛细血管网，逐级汇合越合越粗，引导血液回心并最终注入心房，A、B、C、D项描述正确。但并非所有静脉都有静脉瓣，四肢静脉瓣膜发达，而头颈部静脉、上腔静脉及肝门静脉等多无瓣膜，E项以偏概全为错误项。静脉瓣的作用是防止血液逆流，下肢静脉曲张与瓣膜功能不全相关"},{"q":"关于胸椎的特点是","o":["横突上有横突孔","棘突分叉","上、下关节突不明显","棘突水平伸向后方","椎体侧面后部有肋凹"],"a":4,"e":"胸椎椎体侧面后部有上、下肋凹，与肋头相关节，横突末端前面有横突肋凹与肋结节相关节，E项正确。横突孔为颈椎特有结构，A项不符。棘突分叉见于颈椎，B项错误。上、下关节突明显存在，C项不明显不对。胸椎棘突向后下方倾斜、呈叠瓦状排列，并非水平伸向后方，D项描述错误"},{"q":"关于脊髓的描述，错误的是","o":["上端在枕骨大孔处与小脑相连","有颈膨大和腰骶膨大","呈扁的圆柱形","脊髓表面有6条纵沟","新生儿脊髓下端平第3腰椎"],"a":0,"e":"脊髓上端在枕骨大孔平面与延髓相续，而非与小脑相连，故A项错误。脊髓有颈膨大和腰骶膨大，分别发出上、下肢神经，B项正确。脊髓呈前后稍扁的圆柱形，表面有前正中裂、后正中沟等6条纵沟，C、D项成立。新生儿脊髓下端约平第3腰椎，成人平第1腰椎下缘，E项符合新生儿特点"},{"q":"膝关节后交叉韧带的作用是","o":["防止胫骨前移","防止胫骨后移","防止膝关节过伸","限制膝关节旋内","限制膝关节旋外"],"a":1,"e":"后交叉韧带起自胫骨髁间隆突后方，止于股骨内侧髁外面，作用是限制胫骨向后移位，B项正确。前交叉韧带限制胫骨前移，A项属前交叉韧带功能。防止膝关节过伸主要靠髌韧带及关节囊与交叉韧带共同限制，C项非后交叉韧带主要作用。限制旋转主要靠半月板与侧副韧带，D、E项不符"},{"q":"关于纵隔的描述，正确的是","o":["位于胸膜腔内","容纳心和肺","两侧界是纵隔胸膜","下界是壁腹膜","上宽下窄"],"a":2,"e":"纵隔是两侧胸膜腔之间的间隙，两侧界为纵隔胸膜，C项正确。纵隔位于胸膜腔之外，而非胸膜腔内，A项错误。纵隔容纳心及大血管、气管、食管等，但不容纳肺，肺位于胸膜腔内，B项不符。纵隔下界为膈而非壁腹膜，D项错误。纵隔整体上窄下宽，E项上宽下窄说反"},{"q":"紧贴于肾实质表面的是","o":["肾筋膜前层","肾筋膜后层","肾纤维囊","肾脂肪囊","脏腹膜"],"a":2,"e":"肾的被膜由内向外依次为纤维囊、脂肪囊和肾筋膜，纤维囊紧贴肾实质表面，薄而致密，正常易剥离，C项正确。脂肪囊位于纤维囊外面，为包绕肾的脂肪层，D项位置偏外。肾筋膜分前、后层包绕肾与肾上腺，位于最外层，A、B项不符。脏腹膜仅覆盖肾前面一部分，肾大部分在腹膜后，E项错误"},{"q":"腹腔干及其分支不分布到","o":["肝、胆囊","胰和脾","胃和部分十二指肠","大网膜和小网膜及食管腹段","空肠和回肠"],"a":4,"e":"腹腔干发出胃左动脉、肝总动脉和脾动脉，分布至胃、肝、胆囊、胰、脾及大、小网膜的食管腹段与部分十二指肠，A、B、C、D项均在其分布范围内。空肠与回肠由肠系膜上动脉供血，不属于腹腔干分布区域，E项为本题所选。腹腔干、肠系膜上动脉与肠系膜下动脉是腹主动脉三大不成对脏支，供血区域自上而下依次衔接"},{"q":"关于回肠的叙述，正确的是","o":["黏膜内有孤立、集合淋巴滤泡","血管较丰富，颜色较红润","黏膜环状皱襞密而高","占小肠远侧的2/3","管径细、壁厚"],"a":0,"e":"回肠黏膜内除孤立淋巴滤泡外，尚有集合淋巴滤泡，为回肠特征，A项正确。血管丰富、颜色红润、环状皱襞密而高为空肠特点，B、C项属空肠。回肠约占小肠远侧的3/5，D项2/3表述不准。回肠管径较细、壁较薄，E项壁厚与空肠比较不符。空、回肠的淋巴滤泡差异是二者鉴别要点"},{"q":"关于甲状腺的动脉正确的是","o":["甲状腺上动脉发自颈外动脉","甲状腺下动脉直接发自锁骨下动脉","甲状腺中动脉发自颈内动脉","甲状腺最下动脉发自主动脉","两侧甲状腺的动脉间无吻合"],"a":0,"e":"甲状腺上动脉起自颈外动脉起始部，向前下走行至甲状腺上极，A项正确。甲状腺下动脉多起自甲状颈干而非直接发自锁骨下动脉，B项不确切。甲状腺中动脉并非恒定的甲状腺供血动脉命名，C项不符。甲状腺最下动脉出现率较低，多起自头臂干或主动脉弓，D项笼统称发自主动脉不准。同侧上下动脉及左右动脉间均有吻合，E项无吻合错误"},{"q":"组成射精管的是","o":["输精管末端和附睾管","输精管末端和睾丸输出小管","输精管末端和前列腺排泄管","输精管末端和精囊排泄管","输精管末端和尿道球腺排泄管"],"a":3,"e":"射精管由输精管壶腹末端与精囊腺的排泄管汇合而成，穿入前列腺实质后开口于尿道前列腺部，D项正确。附睾管、睾丸输出小管为精子输送与贮存通路上游结构，不参与射精管构成，A、B项不符。前列腺排泄管开口于尿道前列腺部，不参与射精管，C项错误。尿道球腺排泄管开口于尿道球部，E项亦不参与"},{"q":"有关红骨髓的描述，正确的是","o":["成人存在于髓腔内","不存在于板障内","胎儿期造血，成年期不造血","髂骨、胸骨、椎骨内终生保存红骨髓","各个年龄都可转化为黄骨髓"],"a":3,"e":"胎儿及婴幼儿骨髓腔内均为红骨髓，成年后长骨骨髓腔内红骨髓渐被黄骨髓替代，但髂骨、胸骨、椎骨等扁骨和不规则骨内终生保留红骨髓，为临床骨髓穿刺部位，D项正确。成人髓腔内主要为黄骨髓，A项不符。板障内终生含红骨髓，B项不存在错误。成年期红骨髓仍具造血功能，C项错误。E项各年龄都可转化表述不准"},{"q":"成年后失去功能的内分泌器官是","o":["睾丸","垂体","胰腺","肾上腺","松果体"],"a":4,"e":"松果体在儿童期分泌褪黑素，参与抑制性早熟，成年后逐渐钙化、功能明显减退，被视为成年后失去功能的内分泌器官，E项正确。睾丸终身分泌雄激素并生成精子，A项不符。垂体、肾上腺与胰腺的胰岛成年后均持续发挥重要内分泌功能，B、C、D项均仍有功能。松果体钙化斑还是颅脑影像的定位标志"},{"q":"关于胰的描述，正确的是","o":["是人体最大的消化腺","可分为头、颈、体","只有外分泌功能","胰头被十二指肠包绕","胰管与肝总管汇合，开口十二指肠大乳头"],"a":3,"e":"胰头被十二指肠降部与水平部呈C形包绕，胰头癌可压迫胆总管致黄疸，D项正确。人体最大的消化腺是肝，胰为第二大消化腺，A项不符。胰分头、颈、体、尾四部，B项遗漏胰尾。胰既有外分泌胰液又有内分泌胰岛功能，C项只有外分泌错误。胰管与胆总管汇合后开口于十二指肠大乳头，而非肝总管，E项名称错误"},{"q":"肾实质包括","o":["肾盂","肾窦","肾皮质","肾动脉","肾大盏"],"a":2,"e":"肾实质分为肾皮质与肾髓质两部分，皮质位于外层，富含肾小球，故C项肾皮质属于肾实质。肾窦为肾门向内扩大的腔，容纳肾盂、肾盏、血管等，并非实质，B项不符。肾盂与肾大盏属肾内收集尿路的管道结构，位于肾窦内，A、E项不属实质。肾动脉为血管，D项亦非肾实质成分。髓质主要由肾锥体构成"},{"q":"椎前神经节不包括","o":["颈胸神经节","主动脉肾神经节","腹腔神经节","肠系膜下神经节","肠系膜上神经节"],"a":0,"e":"椎前神经节位于脊柱前方，包括腹腔神经节、主动脉肾神经节、肠系膜上神经节和肠系膜下神经节，B、C、D、E项均属之。颈胸神经节即星状神经节，由颈下神经节与第1胸神经节融合而成，位于交感干上，属椎旁神经节，不属于椎前神经节，A项为本题所选。椎旁与椎前神经节的区别在于位置及与交感干的关系"},{"q":"对视网膜具有支撑作用的结构是","o":["房水","巩膜","晶状体","玻璃体","角膜"],"a":3,"e":"玻璃体为无色透明胶状物，填充于晶状体后面与视网膜之间，占眼球内容物大部分，对视网膜起支撑作用，D项正确。房水为充满眼房的透明液体，营养角膜与晶状体并维持眼压，A项作用不同。巩膜、角膜为眼球壁纤维膜外层，起保护与维持形态作用，B、E项属眼球壁。晶状体为双凸透镜状结构，主司折光与调节，C项不支撑视网膜"},{"q":"使髋关节后伸并旋外的肌肉是","o":["臀大肌","髂腰肌","臀中肌","股直肌","股二头肌"],"a":0,"e":"臀大肌起自髂骨翼外面与骶尾骨后面，止于髂胫束与股骨臀肌粗隆，收缩时使髋关节后伸并旋外，A项正确。髂腰肌为屈髋肌，B项作用相反。臀中肌主要使髋关节外展，前部纤维可内旋，C项不符。股直肌为屈髋伸膝肌，D项不后伸髋。股二头肌可伸髋屈膝，但旋外作用不显著，E项不如A项贴切"},{"q":"关于甲状旁腺，错误的是","o":["左、右各1个","扁椭圆形小体","位于甲状腺侧叶后面","分泌激素可调节钙磷代谢","不慎被切除后，会经常出现手足抽搐"],"a":0,"e":"甲状旁腺通常为扁椭圆形小体，贴附于甲状腺侧叶后面，一般有上、下两对共4个，分泌甲状旁腺激素调节钙磷代谢，手术误切可致低钙抽搐，故A项左右各1个数目错误。B、C、D、E所述形态、位置、功能与误切后果均正确。甲状旁腺数目与位置变异较多，手术中需注意保护"},{"q":"全身最粗大的淋巴管道是","o":["胸导管","左、右颈干","右淋巴导管","左、右锁骨下干","左、右支气管纵隔干"],"a":0,"e":"胸导管是全身最粗大的淋巴管道，起自乳糜池，注入左静脉角，收集全身约3/4区域的淋巴，A项正确。右淋巴导管较短，收集右上肢、右半头颈及右胸部淋巴，C项非最粗大。颈干、锁骨下干、支气管纵隔干为局部淋巴干，管径均远小于胸导管，B、D、E项不符。胸导管与右淋巴导管共同构成淋巴回流的最终通路"},{"q":"关于盲肠的说法，错误的是","o":["是大肠的起始部","具有结肠带、结肠袋和肠脂垂","是腹膜间位器官","在回盲口的下方有阑尾的开口","一般位于右髂窝内"],"a":2,"e":"盲肠为大肠起始部，位于右髂窝内，具有结肠带、结肠袋和肠脂垂三种特征性结构，回肠末端突入盲肠处形成回盲口，其下方有阑尾开口，A、B、D、E项均正确。盲肠表面几乎全被腹膜包裹，活动度较大，属腹膜内位器官，而非间位器官，C项为错误项。腹膜间位器官如肝、胆囊、膀胱等仅部分被腹膜覆盖"},{"q":"关于内脏学的描述，正确的是","o":["各系统与外界不相通","包括消化、呼吸、泌尿、生殖四大系统","大部分内脏器官位于胸膜腔、腹膜腔内","消化管的管壁由3层组织构成","胸膜、腹膜与会阴不属内脏学范畴"],"a":1,"e":"内脏学包括消化、呼吸、泌尿和生殖四大系统，主要研究内脏器官的形态、位置与结构，B项正确。内脏器官多与外界相通，A项不相通错误。大部分内脏器官位于胸腔、腹腔和盆腔内，而胸膜腔、腹膜腔为潜在腔隙，脏器并不位于其中，C项概念混淆。消化管管壁由黏膜、黏膜下层、肌层和外膜四层构成，D项三层错误。胸膜、腹膜与会阴均属内脏学范畴，E项错误"},{"q":"脊髓中间外侧核的叙述，正确的是","o":["是交感神经节后神经元胞体","存在于脊髓全长","是交感神经低级中枢","位于板层Ⅷ","发出纤维组成盆内脏神经"],"a":2,"e":"脊髓中间外侧核位于胸1至腰3节段脊髓灰质侧角，为交感神经的低级中枢，内含交感节前神经元胞体，C项正确。其发出节前纤维经白交通支入交感干，为节前而非节后神经元，A项错误。该核仅见于T1至L3节段，并非脊髓全长，B项不对。其位于灰质侧角，D项板层Ⅷ不符。盆内脏神经起自骶髓副交感核，E项属副交感"},{"q":"动脉圆锥位于","o":["左心室入口下方","右心室入口下方","主动脉口下方","肺动脉口下方","肺动脉口上方"],"a":3,"e":"动脉圆锥又称漏斗部，是右心室向左上方延伸出的锥形部分，位于肺动脉口下方，其上端通肺动脉干，D项正确。左心室入口为二尖瓣口，其下方无动脉圆锥，A项不符。右心室入口为三尖瓣口，B项位置错误。主动脉口下方为主动脉前庭，属左心室流出道，C项不符。E项肺动脉口上方与动脉圆锥实际位置相反"},{"q":"下列哪条不是肠系膜上动脉的分支","o":["空、回肠动脉","回结肠动脉","左结肠动脉","右结肠动脉","中结肠动脉"],"a":2,"e":"肠系膜上动脉分支包括空、回肠动脉，回结肠动脉，右结肠动脉和中结肠动脉，A、B、D、E项均属之。左结肠动脉起自肠系膜下动脉，分布于降结肠，不属于肠系膜上动脉分支，C项为本题所选。肠系膜上、下动脉分支在结肠处通过边缘动脉相互吻合，中结肠动脉与左结肠动脉的吻合是结肠血供的重要侧支"},{"q":"主动脉的第1个分支为","o":["支气管动脉","头臂动脉","左颈总动脉","冠状动脉","肋间后动脉"],"a":3,"e":"主动脉自左心室发出后，升主动脉根部发出的第一对分支即为左、右冠状动脉，分布于心，D项正确。头臂干、左颈总动脉与左锁骨下动脉为主动脉弓的三大分支，位置在冠状动脉之后，B、C项非第一分支。支气管动脉多起自胸主动脉，A项位置靠后。肋间后动脉为胸主动脉壁支，E项更靠后"},{"q":"听觉感受器是下列哪个结构","o":["椭圆囊斑","球囊斑","膜壶腹","螺旋器","耳蜗"],"a":3,"e":"螺旋器即Corti器，位于蜗管鼓壁的基底膜上，由支持细胞与毛细胞构成，是听觉感受器，D项正确。椭圆囊斑与球囊斑为位觉感受器，感受直线加速度与静态平衡，A、B项不符。膜壶腹内的壶腹嵴感受旋转加速度，C项属位觉感受器。耳蜗为听觉器官整体，内含蜗管与螺旋器，但感受器特指螺旋器，E项范围过大"},{"q":"位于中脑内的脑神经核是","o":["动眼神经副核","三叉神经运动核","疑核","红核","黑质"],"a":0,"e":"动眼神经副核位于中脑上丘平面，属一般内脏运动核，发出纤维支配瞳孔括约肌与睫状肌，A项正确。三叉神经运动核位于脑桥，B项不符。疑核位于延髓，支配咽喉肌，C项错误。红核与黑质虽位于中脑，但属锥体外系核团，并非脑神经核，D、E项不符合脑神经核限定"},{"q":"属于肾髓质的结构是","o":["肾柱","肾小盏","肾锥体","肾小球","肾盂"],"a":2,"e":"肾髓质主要由15至20个肾锥体构成，锥体底朝向皮质、尖端即肾乳头伸入肾小盏，C项正确。肾柱为肾皮质伸入肾锥体之间的部分，属皮质结构，A项不符。肾小盏、肾盂为肾内收集尿液的管道，位于肾窦内，B、E项不属髓质。肾小球位于肾皮质内，D项属皮质。肾柱与肾锥体的区别是皮质与髓质区分的关键"},{"q":"输精管结扎术最常选择的部位是","o":["沿睾丸后缘行走的一段","附睾头与腹股沟浅环之间的部位","行经腹股沟管内","在盆腔中行走的部分","输精管壶腹"],"a":1,"e":"输精管依行程分为睾丸部、精索部、腹股沟部和盆部，其中精索部位于附睾头与腹股沟浅环之间，位置表浅、易于触及，为输精管结扎术常用部位，B项正确。沿睾丸后缘行走的一段为睾丸部，位置深且不固定，A项不便手术。腹股沟管内与盆腔内段位置深在，C、D项不适用。输精管壶腹位于盆部末端，E项更不适宜"},{"q":"关于掌深弓的描述，错误的是","o":["位于骨间肌的浅面","位于指深屈肌腱的深面","由桡动脉的终支和尺动脉的掌深支组成","发出掌心动脉与掌浅弓相吻合","位于指浅屈肌腱的浅面"],"a":4,"e":"掌深弓位于指深屈肌腱深面、骨间肌浅面，由桡动脉终支与尺动脉掌深支吻合而成，发出掌心动脉与掌浅弓吻合，A、B、C、D项均正确。E项位于指浅屈肌腱的浅面实为掌浅弓的位置，掌浅弓由尺动脉终支与桡动脉掌浅支构成，位置较浅，与掌深弓所在层次不同，故E项为错误项"},{"q":"关于气管杈的叙述，正确的是","o":["位于左主支气管分支的分叉处","气管杈位于第7气管软骨环","位于右主支气管分支的分叉处","气管至胸骨角平面分为左、右主支气管，其分杈处称气管杈","位于肺叶支气管的分叉处"],"a":3,"e":"气管在胸骨角平面约平第4胸椎下缘分为左、右主支气管，分叉处称气管杈，其内腔正中有一向上突起的气管隆嵴，是支气管镜检的重要标志，D项正确。气管杈位于气管下端分叉处，而非左或右主支气管再分支处，A、C项位置错误。气管杈平第4胸椎而非第7气管软骨环，B项平面不符。肺叶支气管为二级支气管，E项层级错误"},{"q":"何层结构可以缓冲外力对肾的震荡","o":["肾筋膜前层","脂肪囊","肾筋膜后层","纤维囊","脏腹膜"],"a":1,"e":"脂肪囊为包绕肾的脂肪组织层，位于纤维囊外面，厚而柔软，可缓冲外力对肾的震荡并固定肾的位置，B项正确。肾筋膜前、后层形成包裹肾的鞘，主要起固定作用，A、C项不符。纤维囊紧贴肾实质，薄而致密，主要起保护与被膜作用，D项缓冲作用弱。脏腹膜仅覆盖肾前面，E项与缓冲震荡无关。肾被膜由内向外为纤维囊、脂肪囊、肾筋膜"},{"q":"不属于肌的辅助装置的是","o":["筋膜","滑膜囊","肌间隔","籽骨","腱鞘"],"a":3,"e":"肌的辅助装置包括筋膜、滑膜囊和腱鞘，具有保护、减少摩擦等作用，筋膜可形成肌间隔，A、B、C、E项均属之。籽骨为嵌入肌腱内的小骨，可改变肌腱牵引方向、减少摩擦，属于骨而非肌的辅助装置，D项为本题所选。籽骨多见于手、足等处，髌骨为人体最大的籽骨。筋膜分为浅筋膜与深筋膜，深筋膜可形成肌间隔"},{"q":"喉腔可分为","o":["喉前庭、喉室、声门下腔","喉室、喉中间腔、声门下腔","前庭裂、喉中间腔、声门下腔","喉口、喉中间腔、声门下腔","喉前庭、喉中间腔、声门下腔"],"a":4,"e":"喉腔以前庭襞和声襞为界分为喉前庭、喉中间腔和声门下腔三部，E项正确。喉室为喉中间腔向两侧前庭襞与声襞之间突出的隐窝，并非独立分区，A、B项将其列为分部不妥。前庭裂为两侧前庭襞之间的裂隙，C项名称错误。喉口为喉腔上口，D项非分部名称。声门下腔位于声襞下方，向下通气管"},{"q":"关于肱动脉描述正确的是","o":["在胸大肌下缘续腋动脉","沿肱二头肌深方下行","沿肱二头肌外侧缘下行","至桡骨颈平面分为尺动脉和桡动脉","在肱二头肌腱的外侧可摸到肱动脉的搏动"],"a":3,"e":"肱动脉为腋动脉的延续，沿肱二头肌内侧沟下行，至桡骨颈平面分为桡动脉与尺动脉，D项正确。其在大圆肌下缘而非胸大肌下缘续接腋动脉，A项界限错误。肱动脉行于肱二头肌内侧沟，B项深方、C项外侧缘描述均不符。肱动脉搏动在肱二头肌腱内侧可触及，为测血压听诊部位，E项外侧方向错误"},{"q":"骶骨的正确描述是","o":["有5对骶前孔","由4块骶椎融合而成","与第4腰椎相关节","骶管内有脊髓通过","于骶角处可寻骶管裂孔进行神经阻滞麻醉"],"a":4,"e":"骶骨由5块骶椎融合而成，有4对骶前孔和骶后孔，骶管容纳脊髓末端以下的蛛网膜下隙与骶神经根。骶角是骶管裂孔两侧向下的突起，为骶管阻滞麻醉的定位标志，E项正确。骶骨有4对骶前孔而非5对，A项数目错误。骶骨由5块骶椎融合，B项4块错误。骶骨与第5腰椎相关节，C项不符。成人脊髓下端止于第1腰椎下缘，D项脊髓通过错误"},{"q":"下列静脉，直接汇入肝门静脉的是","o":["肾静脉","胃左静脉","精索内静脉","直肠上静脉","奇静脉"],"a":1,"e":"肝门静脉主要由肠系膜上静脉与脾静脉汇合而成，其直接属支有胃左静脉、胃右静脉、胆囊静脉、附脐静脉及肠系膜下静脉等，胃左静脉直接汇入门静脉，B项正确。肾静脉与精索内静脉直接汇入下腔静脉，A、C项不符。直肠上静脉先汇入肠系膜下静脉再入门静脉，非直接属支，D项不对。奇静脉注入上腔静脉，E项属体循环静脉系统"},{"q":"颈内动脉系与基底动脉系的吻合支是","o":["大脑后动脉","前交通动脉","后交通动脉","大脑中动脉","大脑前动脉"],"a":2,"e":"后交通动脉连于颈内动脉与大脑后动脉之间，是颈内动脉系与基底动脉系在脑底部吻合的重要通路，构成大脑动脉环，C项正确。前交通动脉连接左右大脑前动脉，均属颈内动脉系，B项不符。大脑后动脉为基底动脉终支，属椎-基底动脉系，A项非吻合支。大脑中动脉、大脑前动脉均为颈内动脉分支，D、E项不连接两系"},{"q":"心的体表投影描述正确的是","o":["左上点在左侧第2肋软骨下缘1cm处","右上点在右侧第3肋软骨下缘1cm处","左下点在左侧第5肋间隙距胸骨左侧缘7～9cm处","左下点在左侧第5肋间隙，左侧锁骨中线内侧1～2cm处","右下点在右侧第5胸肋关节处"],"a":3,"e":"心尖即左下点投影于左侧第5肋间隙、左锁骨中线内侧1至2cm处，此处可触及心尖搏动，D项正确。左上点在左侧第2肋软骨下缘距胸骨左缘约1.2cm，A项表述偏差。右上点在右侧第3肋软骨上缘距胸骨右缘约1cm，B项下缘不符。C项距胸骨左缘7至9cm定位不准。右下点在右侧第6胸肋关节处，E项第5胸肋关节错误"},{"q":"男性尿道的外括约肌位于","o":["尿道内口周围","尿道前列腺部周围","尿道膜部周围","尿道海绵体部周围","尿道外口周围"],"a":2,"e":"尿道外括约肌为骨骼肌，环绕尿道膜部，可随意控制排尿，C项正确。尿道内括约肌为平滑肌，位于尿道内口周围，属不随意肌，A项属内括约肌。前列腺部与海绵体部周围无此括约肌，B、D项不符。尿道外口处无环形括约肌结构，E项错误。尿道膜部穿过尿生殖膈，是最短、最固定的一段，也是外括约肌所在处"},{"q":"手术中寻找阑尾的可靠方法","o":["沿盲肠内侧缘寻找","沿回肠末端寻找","沿结肠带寻找","以McBurney点为标志","沿大网膜移动的方向寻找"],"a":2,"e":"盲肠与结肠表面有三条结肠带，它们在阑尾根部汇合，故手术中沿结肠带向下追踪可可靠找到阑尾根部，C项正确。阑尾根部位于回盲口下方，而非盲肠内侧缘，A项方向不准。回肠末端可作为寻找回盲部的参考，但不如结肠带可靠，B项非最佳方法。McBurney点仅为体表投影压痛点，D项不能作为术中直接寻找依据。大网膜移动方向与阑尾位置无固定关系，E项不可靠"},{"q":"关于鼻咽的说法，下列选项中正确的是","o":["上达颅底，下至咽峡","后壁上有咽鼓管咽口连鼓室","咽隐窝是鼻咽癌的好发部位","咽鼓管圆枕与下鼻甲续连","咽隐窝是蝶窦的开口"],"a":2,"e":"咽隐窝位于鼻咽侧壁、咽鼓管圆枕后方与咽后壁之间，是鼻咽癌的好发部位，C项正确。鼻咽上达颅底、下至软腭游离缘平面而非咽峡，A项下界错误。咽鼓管咽口位于鼻咽侧壁，咽隐窝在此处而非后壁，B项位置不符。咽鼓管圆枕向后下与下鼻甲不续连，D项解剖关系错误。蝶窦开口于蝶筛隐窝，不在咽隐窝，E项明显错误"},{"q":"锁骨下静脉直接汇入下列何静脉","o":["颈总静脉","头臂静脉","颈内静脉","上腔静脉","颈外静脉"],"a":1,"e":"锁骨下静脉是腋静脉的延续，与颈内静脉在胸锁关节后方汇合成头臂静脉，故锁骨下静脉直接汇入头臂静脉，B项正确。颈总静脉并非颈内静脉与锁骨下静脉汇合后的标准命名，A项不存在。颈内静脉与锁骨下静脉是并列汇合关系，C项非汇入目标。上腔静脉由左右头臂静脉汇合而成，D项为下一级。颈外静脉注入锁骨下静脉，E项方向相反"},{"q":"临床上采血，常在下列耳的哪个部位","o":["耳屏","耳轮","耳垂","对耳屏","以上都不对"],"a":2,"e":"耳垂组织较厚、血管丰富且痛觉相对不敏感，临床常在此处行末梢采血，C项正确。耳屏为耳甲前方的小突起，A项非采血部位。耳轮为耳廓外缘卷曲部分，B项不合。对耳屏为耳屏对侧的小突起，D项亦不用于采血。耳廓主要由软骨构成，仅耳垂含较多结缔组织与脂肪，适宜针刺采血，E项以上都不对不成立"},{"q":"屈肘并能屈肩的肌肉是","o":["三角肌","胸小肌","肱二头肌","肱肌","肱三头肌"],"a":2,"e":"肱二头肌起自肩胛骨盂上结节与喙突，止于桡骨粗隆，跨越肩、肘两关节，可屈肘、屈肩并使前臂旋后，C项正确。三角肌主要使肩关节外展，A项不屈肘。胸小肌作用于肩胛骨，B项不跨肘关节。肱肌为屈肘肌，但不跨肩关节、不能屈肩，D项不符。肱三头肌为伸肘肌，作用与屈肘相反，E项错误"},{"q":"腓深神经支配","o":["股二头肌","胫骨后肌","胫骨前肌","腓骨长肌","腓骨短肌"],"a":2,"e":"腓深神经伴胫前动脉下行，支配小腿前群肌，包括胫骨前肌、趾长伸肌、拇长伸肌等，并支配第1趾背肌，C项正确。股二头肌属大腿后群肌，由坐骨神经支配，A项不符。胫骨后肌属小腿后群深层，由胫神经支配，B项错误。腓骨长、短肌属小腿外侧群，由腓浅神经支配，D、E项神经归属不同"},{"q":"喉室位于","o":["喉中间腔内","喉前庭内","声门下腔","声门裂","喉口两侧"],"a":0,"e":"喉室为喉中间腔向两侧前庭襞与声襞之间突出的隐窝，位于喉中间腔内，A项正确。喉前庭位于前庭襞以上，B项位置偏高。声门下腔位于声襞以下，C项不符。声门裂为两侧声襞之间的裂隙，D项非腔室。喉口为喉腔上口，E项位置最高。喉室属于喉中间腔的一部分"},{"q":"椎弓的结构不包括","o":["椎弓根","关节突","横突","椎孔","棘突"],"a":3,"e":"椎弓由椎弓根与椎弓板组成，其上发出棘突、横突及上、下关节突，A、B、C、E项均为椎弓的结构或突起。椎孔是由椎体后面与椎弓共同围成的孔，容纳脊髓，并非椎弓本身的结构，D项为本题所选。相邻椎骨的椎上、下切迹围成椎间孔，有脊神经通过，需与椎孔概念区分"},{"q":"关于第四脑室的叙述，错误的是","o":["内充满脑脊液","位于脑桥、延髓和小脑之间","借正中孔和外侧孔通蛛网膜下腔","经中脑水管通第三脑室","是最大的脑室"],"a":4,"e":"第四脑室位于脑桥、延髓与小脑之间，内充脑脊液，向下通脊髓中央管，向上经中脑水管通第三脑室，并借正中孔、外侧孔通蛛网膜下隙，A、B、C、D项均正确。脑室中最大的是侧脑室，位于大脑半球内，第四脑室并非最大，E项为错误项。侧脑室经室间孔与第三脑室相通，是脑脊液循环的重要通路"},{"q":"在记录牙式时，L5代表的是","o":["左上颌第2乳磨牙","左上颌第2前磨牙","右上颌第3磨牙","右上颌第2磨牙","左上颌第2磨牙"],"a":1,"e":"牙式记录中，L代表左上颌，数字按恒牙从中线向后依次编号，1、2为中、侧切牙，3为尖牙，4、5为第1、第2前磨牙，故L5表示左上颌第2前磨牙，B项正确。A项第2乳磨牙属乳牙编号，与恒牙编号体系不同。C、D项为右上颌且牙位偏后，E项把5误作第2磨牙，恒牙第2磨牙编号为7"},{"q":"下列骨连结中，不属于间接连结的是","o":["椎间盘","肩关节","肘关节","髋关节","膝关节"],"a":0,"e":"骨连结分直接连结与间接连结，间接连结即滑膜关节，具有关节面、关节囊和关节腔。肩关节、肘关节、髋关节与膝关节均具备典型滑膜关节结构，属间接连结，B、C、D、E项不符。椎间盘由纤维环与髓核构成，属纤维软骨连结，为直接连结，无关节腔，A项为本题所选。直接连结还包括缝、韧带连结与骨性结合"},{"q":"关于左肺的描述，正确的是","o":["较右肺粗大","较右肺粗短","较右肺狭长","与右肺等大","分为三叶"],"a":2,"e":"左肺因受心的影响，体积较右肺小而狭长，仅分上、下两叶，前缘有心切迹与左肺小舌，C项正确。较右肺粗大或粗短均为右肺特点，A、B项不符。两肺并非等大，右肺略大，D项错误。分为三叶的是右肺，左肺分两叶，E项是右肺特征。左肺狭长、右肺粗短是两侧肺形态对比的要点"},{"q":"具有屈髋关节和伸膝关节作用的肌是","o":["长收肌","半膜肌","股二头肌","股直肌","腓肠肌"],"a":3,"e":"股直肌为股四头肌中唯一跨越髋关节的头，起自髂前下棘，经髌韧带止于胫骨粗隆，可屈髋关节并伸膝关节，D项正确。长收肌使髋关节内收，A项不符屈髋伸膝。半膜肌与股二头肌均为腘绳肌，作用为伸髋屈膝，B、C项作用相反。腓肠肌跨膝、踝关节，主司屈膝与跖屈，E项不屈髋"},{"q":"下列关于输精管的描述，正确的是","o":["起于睾丸下端","全程位于精索内","是粗细一致的横纹肌性管道","末端膨大为输精管壶腹","开口于前列腺"],"a":3,"e":"输精管末端在膀胱底后面膨大形成输精管壶腹，其下端与精囊排泄管汇合成射精管，D项正确。输精管起自附睾尾而非睾丸下端，A项起点错误。全程仅部分位于精索内，还要经过腹股沟管与盆腔，B项全程不对。输精管为平滑肌性管道、管壁厚而管径细，C项横纹肌、粗细一致错误。输精管不直接开口于前列腺，而是经射精管开口于尿道前列腺部，E项不符"},{"q":"关于颏舌肌，下列说法中正确的是","o":["是成对的舌内肌","起于下颌骨的颏结节","止于舌的两侧","单侧收缩时，使舌尖伸向同侧","两侧收缩可拉舌向前下"],"a":4,"e":"颏舌肌起自下颌骨正中联合后面的颏棘，纤维向后上放射状止于舌正中沟两侧，两侧同时收缩时拉舌向前下方，使舌伸出，E项正确。颏舌肌属舌外肌而非舌内肌，A项分类错误。起点为颏棘而非颏结节，B项名称不准。其止于舌体而非舌的两侧缘，C项描述不确。单侧收缩时舌尖偏向对侧，D项同侧说反"},{"q":"神经节是神经元胞体集中形成的团块，通常的位置是","o":["在中枢神经系统","在周围神经系统","中枢和周围神经系统都存在","只存在于植物神经周围部","只存在于躯体神经周围部"],"a":1,"e":"神经节是周围神经系统中神经元胞体聚集形成的结构，如脊神经节、交感神经节等，B项正确。中枢神经系统内神经元胞体集中处称为神经核，而非神经节，A项概念混淆。神经节仅存在于周围神经系统，C项两者都存在错误。植物神经与躯体神经的周围部均可有神经节，D、E项以只存在于限定均不准确"},{"q":"不能限制脊柱过度前屈的结构是","o":["棘上韧带","棘间韧带","黄韧带","后纵韧带","前纵韧带"],"a":4,"e":"限制脊柱过度前屈的韧带有后纵韧带、黄韧带、棘间韧带与棘上韧带，它们位于椎管后方或棘突间，前屈时被拉紧，A、B、C、D项均能限制前屈。前纵韧带位于椎体前面，主要作用是限制脊柱过度后伸，并不能限制前屈，E项为本题所选。前、后纵韧带分别位于椎体前、后面，作用相反，是常见对比考点"},{"q":"位于髋关节囊前部，限制大腿过度后伸的韧带是","o":["髂股韧带","耻股韧带","坐股韧带","股骨头韧带","骶结节韧带"],"a":0,"e":"髂股韧带起自髂前下棘，止于股骨转子间线，位于髋关节囊前部，是人体最强大的韧带之一，可限制大腿过度后伸并维持直立姿势，A项正确。耻股韧带位于关节囊前下部，限制外展与旋外，B项位置功能不同。坐股韧带位于关节囊后部，限制内旋，C项方向不符。股骨头韧带位于关节腔内，含营养血管，D项不限制后伸。骶结节韧带属骨盆韧带，E项与髋关节囊无关"},{"q":"正常情况下，声波从外耳道传至内耳，下列途径正确的是","o":["外耳道→鼓膜→听小骨→蜗窗→外淋巴","外耳道→鼓膜→听小骨→蜗窗→内淋巴","外耳道→鼓膜一听小骨→前庭窗→外淋巴","外耳道→鼓膜→听小骨→前庭窗→内淋巴","上述都不对"],"a":2,"e":"声波经外耳道振动鼓膜，再由听小骨链放大后经前庭窗传入前庭阶的外淋巴，为空气传导的主要途径，C项正确。蜗窗为缓冲内耳压力波动的结构，并非声波传入的主要通道，A、B项经蜗窗错误。听小骨将振动传入外淋巴而非内淋巴，D项内淋巴不对，内淋巴位于膜迷路蜗管内。E项都不对不成立，C项路径正确"},{"q":"下列结构接受头部变速旋转运动的刺激的是","o":["螺旋器","球囊斑和椭圆囊斑","蜗管","壶腹嵴","内淋巴"],"a":3,"e":"壶腹嵴位于半规管壶腹内，其毛细胞受内淋巴流动刺激，感受头部旋转变速运动即角加速度。螺旋器是听觉感受器，球囊斑和椭圆囊斑感受直线加速与头部位置，蜗管为膜迷路中耳蜗部分，均不参与旋转觉。内淋巴是刺激媒介而非感受结构"},{"q":"关于脊神经的描述哪项是错误的","o":["全身共31对","由前根和后根在椎间孔处汇合而成","均从同序数椎骨下方穿出","主要分布于躯干和四肢部位","均为混合性神经，内有四种神经纤维成分"],"a":2,"e":"脊神经共31对，由前、后根在椎间孔处合成，为含四种纤维成分的混合神经，主要分布躯干四肢。第1至第7颈神经在同序数椎骨上方穿出，第8颈神经以下才在同名椎骨下方穿出，故“均从同序数椎骨下方穿出”不成立"},{"q":"关于头静脉，说法正确的是","o":["起自手背静脉网的桡侧","起自手背静脉网的尺侧","起自手掌静脉网的尺侧","起自手掌静脉网的桡侧","起自前臂静脉网的尺侧"],"a":0,"e":"头静脉起自手背静脉网桡侧，沿前臂桡侧、肱二头肌外侧沟上行，最终注入腋静脉。手背静脉网尺侧是贵要静脉起点，手掌静脉网及前臂静脉网尺侧均非其起源，易与贵要静脉来源混淆"},{"q":"属于上肢带骨的连结是","o":["肩锁关节","肩关节","肘关节","桡腕关节","桡尺远侧关节"],"a":0,"e":"上肢带骨为锁骨和肩胛骨，肩锁关节由锁骨肩峰端与肩胛骨肩峰构成，属上肢带骨连结。肩关节连结肩胛骨与肱骨，肘关节、桡腕关节及桡尺远侧关节均为上肢自由骨之间的连结，不属带骨连结"},{"q":"有关尺动脉的描述，何者为错","o":["发出拇主要动脉","发出骨间总动脉至前臂深层","发掌深支参与掌深弓的组成","尺动脉与桡动脉有着广泛吻合","终支参与掌浅弓的组成"],"a":0,"e":"尺动脉主要分支包括骨间总动脉、掌深支，末端与桡动脉分支吻合参与掌浅弓和掌深弓。拇主要动脉由桡动脉发出，而非尺动脉，此即错误所在。尺、桡动脉在手掌形成广泛吻合，是手部血供的重要保证"},{"q":"以下关于小腿三头肌的描述，正确的是","o":["由腓骨长肌和比目鱼肌构成","比目鱼肌起自胫骨的内、外侧髁后面","跟腱止于跟骨结节","可使足跖屈并内翻","可伸踝"],"a":2,"e":"小腿三头肌由腓肠肌和比目鱼肌合成，向下汇成跟腱止于跟骨结节，收缩使足跖屈。比目鱼肌起自胫、腓骨后面而非股骨髁，腓骨长肌属小腿外侧群，该肌不能使足内翻，也无伸踝作用，故仅跟腱止点描述正确"},{"q":"左肾上端约平","o":["第11胸椎体下缘","第12胸椎体中份","第1腰椎体上端","第2腰椎体下缘","第3腰椎体中份"],"a":0,"e":"左肾上端约平第11胸椎体下缘，下端平第2腰椎体下缘；右肾因肝的位置约低半个椎体。第12胸椎和第1腰椎分别是右肾上、下级附近标志，第3腰椎远低于肾下极，第11胸椎体下缘为左肾上端正确体表对应"},{"q":"位于延髓的结构是","o":["锥体","大脑脚","基底沟","上丘","红核"],"a":0,"e":"延髓腹侧面可见锥体，由皮质脊髓束构成，其下端形成锥体交叉。大脑脚、红核、上丘均为中脑结构，基底沟位于脑桥腹侧正中，故只有锥体属于延髓"},{"q":"支配上睑提肌的神经为","o":["视神经","眼神经","滑车神经","动眼神经","展神经"],"a":3,"e":"上睑提肌由动眼神经支配，动眼神经还支配大部分眼外肌。滑车神经只支配上斜肌，展神经只支配外直肌，眼神经为三叉神经第一支主管眼区一般感觉，视神经传导视觉，均不支配上睑提肌"},{"q":"不属于腹膜形成的韧带是","o":["肝圆韧带","肝胃韧带","肝十二指肠韧带","小网膜","大网膜"],"a":0,"e":"肝圆韧带是脐静脉闭锁后的纤维索，位于肝左纵沟前部，不是腹膜形成的结构。肝胃韧带、肝十二指肠韧带均为小网膜组成部分，小网膜和大网膜都由腹膜褶皱形成，属腹膜形成的韧带"},{"q":"使瞳孔转向内侧的肌是","o":["外直肌","内直肌","下直肌","上直肌","上斜肌"],"a":1,"e":"内直肌收缩牵拉眼球转向内侧，由动眼神经支配。外直肌使瞳孔转向外侧，由展神经支配；上斜肌使瞳孔转向下外，由滑车神经支配；下直肌、上直肌主要使瞳孔转向上内或下内，均非内转肌"},{"q":"出入肾门的结构被结缔组织包绕称为","o":["肾柱","肾大盏","肾盂","肾蒂","肾窦"],"a":3,"e":"肾蒂是出入肾门的肾动脉、肾静脉、神经、淋巴管和肾盂等被结缔组织包绕形成的结构。肾柱是皮质嵌入髓质锥体之间的部分，肾大盏为肾窦内收集尿液的管道，肾盂是肾大盏汇合的漏斗，肾窦是肾门向肾内扩大的腔"},{"q":"属于腹膜外位器官的是","o":["脾","直肠上段","输尿管","胆囊","子宫"],"a":2,"e":"输尿管全程位于腹膜后隙，属腹膜外位器官。脾、胆囊、子宫均为腹膜内位器官，表面大部被腹膜包裹；直肠上段为腹膜间位器官，仅前面及两侧有腹膜覆盖，与输尿管的外位属性不同"},{"q":"在头面部，能活动的颅骨是","o":["下鼻甲","上颌骨","腭骨","下颌骨","上鼻甲"],"a":3,"e":"下颌骨是颅骨中唯一可活动的骨，借颞下颌关节与颞骨相连，参与咀嚼和语言。上颌骨、腭骨、下鼻甲、上鼻甲均借助骨缝或软骨与邻骨牢固结合，构成颅的固定部分，无活动性"},{"q":"有关十二指肠的叙述，正确的是","o":["升部即十二指肠球部，是溃疡好发部位","分为升部、降部、水平部三部分","全为腹膜内位器官","降部的前壁有十二指肠小乳头","降部的后内壁有十二指肠大乳头"],"a":4,"e":"十二指肠降部后内侧壁有十二指肠大乳头，是胆总管和胰管共同开口处。球部属于上部而非升部，十二指肠分上、降、水平、升四部，大部为腹膜外位或间位，小乳头位于降部后内侧壁并与大乳头相邻，其余表述均不成立"},{"q":"腰丛位于","o":["腰方肌深面","腰大肌深面","腰大肌浅层","梨状肌浅层","梨状肌深面"],"a":1,"e":"腰丛位于腰大肌深面、腰椎横突前方，由第12胸神经前支一部分及第1至第4腰神经前支组成。腰方肌深面非其常规位置，腰大肌浅层、梨状肌浅层与深面均不正确，梨状肌下孔穿出的是骶丛神经"},{"q":"关于肩胛骨形态的描述，错误的是","o":["为三角形扁骨","位于胸廓后外侧的上份","可分为内、外面","内侧缘薄而锐利","关节盂位于外侧角"],"a":2,"e":"肩胛骨为三角形扁骨，位于胸廓后外侧上部，可分为肋面、背侧面及上、内、下三缘，关节盂位于外侧角。“内、外面”并非其面的分法，内侧缘薄而锐利属正确描述，故此项错误在于面的划分说法"},{"q":"关于输胆管道的描述，正确的是","o":["胆总管长4～8cm","胆总管走行于肝胃韧带内","胆总管走行于肝固有动脉的左侧","肝左管与肝右管汇合成胆总管","胆囊管与胰管汇合成肝胰壶腹"],"a":0,"e":"胆总管由肝总管与胆囊管汇合而成，长约4至8cm，走行于肝十二指肠韧带内、肝固有动脉右侧。肝左右管汇合成肝总管而非胆总管，肝胰壶腹由胆总管与胰管汇合形成，胆总管并不在肝胃韧带内"},{"q":"可以固定子宫颈，防止子宫向下脱垂的韧带是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":3,"e":"子宫主韧带又称子宫颈旁组织，横行于子宫颈与骨盆侧壁之间，是固定子宫颈、防止子宫脱垂的主要结构。子宫圆韧带维持子宫前倾，子宫骶韧带维持前屈，子宫阔韧带限制子宫向两侧移位，卵巢悬韧带则悬吊卵巢"},{"q":"产生房水的结构是","o":["睫状体","晶状体","虹膜","脉络膜","视网膜"],"a":0,"e":"睫状体的睫状突上皮不断生成房水，房水经瞳孔进入前房，再由虹膜角膜角渗入巩膜静脉窦。晶状体为屈光介质，虹膜调节瞳孔大小，脉络膜营养视网膜，视网膜为感光层，均不产生房水"},{"q":"连结下肢骨与躯干骨的关节是","o":["腰骶关节","骶髂关节","耻骨联合","髋关节","关节突关节"],"a":1,"e":"骶髂关节由骶骨耳状面与髂骨耳状面构成，是连结下肢骨与躯干骨的唯一关节。腰骶关节和关节突关节连结椎骨之间，属躯干骨彼此连结；耻骨联合连结两侧髋骨；髋关节为下肢骨与髋骨之间的连结"},{"q":"膈的食管裂孔位置高度","o":["平第8胸椎","平第9胸椎","平第10胸椎","平第11胸椎","平第12胸椎"],"a":2,"e":"膈的食管裂孔约平第10胸椎，有食管和迷走神经通过。主动脉裂孔平第12胸椎，有主动脉和胸导管通过；腔静脉孔平第8胸椎，有下腔静脉通过。第9、11胸椎为相邻干扰平面，与三个裂孔的实际高度不符"},{"q":"颅中窝骨折患者，血性脑脊液经鼻腔流出，可能伤及的鼻旁窦是","o":["额窦","筛窦","上颌窦","蝶窦","上颌窦和额窦"],"a":3,"e":"蝶窦位于蝶骨体内，颅中窝骨折累及蝶窦时，血性脑脊液可经蝶窦开口流入鼻腔。筛窦和额窦位于颅前窝底，骨折多致颅前窝脑脊液鼻漏；上颌窦位于上颌骨内，与上颌窦和额窦并列均为颅中窝骨折的不相关选项"},{"q":"以下对舌下神经的描述，正确的是","o":["为第Ⅺ对脑神经","支配舌肌运动","管理舌的味觉","管理舌的一般感觉","一侧舌下神经损伤，伸舌时舌尖偏向健侧"],"a":1,"e":"舌下神经为第Ⅻ对脑神经，支配全部舌内肌和大部分舌外肌，管理舌的运动。舌前2/3味觉由面神经鼓索管理，舌后1/3味觉和一般感觉由舌咽神经管理，舌的一般感觉主要由三叉神经舌神经传导，一侧损伤伸舌偏向患侧"},{"q":"运动性语言中枢多位于左大脑半球的","o":["缘上回","角回","扣带回","颞横回","额下回后部"],"a":4,"e":"运动性语言中枢即Broca区，位于优势半球额下回后部，损伤导致运动性失语。缘上回为运用中枢，角回为视觉性语言中枢，颞横回为听觉中枢，扣带回参与内脏活动和情绪调节，均非运动性语言中枢"},{"q":"交感神经的低级中枢位于","o":["脊髓T1～L3节段的灰质侧柱的中间外侧核","交感神经节","腹腔神经节","椎前神经节","脑干的一般内脏运动核"],"a":0,"e":"交感神经低级中枢位于脊髓胸1至腰3节段灰质侧角的中间外侧核。交感神经节、腹腔神经节、椎前神经节均为周围部的神经节，不是中枢；脑干的一般内脏运动核属副交感神经中枢，与交感无关"},{"q":"下列关于上矢状窦的描述，正确的是","o":["成对","穿过颈静脉孔","产生脑脊液","位于硬脑膜与颅盖骨之间","接受脑脊液"],"a":4,"e":"上矢状窦位于大脑镰上缘，接受大脑上静脉和经蛛网膜粒回流的脑脊液。该窦为单一结构，不成对；位于硬脑膜两层之间而非硬脑膜与颅盖骨之间；脑脊液由脉络丛产生；穿颈静脉孔的是乙状窦延续为颈内静脉"},{"q":"关于贵要静脉的叙述正确的是","o":["起自手背静脉网的桡侧","于肘关节后方接受肘正中静脉","注入肱静脉","收集前臂桡侧的浅静脉血","沿肱二头肌外侧沟上行"],"a":2,"e":"贵要静脉起自手背静脉网尺侧，沿前臂尺侧、肱二头肌内侧沟上行，在臂中部注入肱静脉或腋静脉。肘正中静脉在肘窝前方连接头静脉与贵要静脉，其起点为手背桡侧的是头静脉，贵要静脉收集前臂尺侧浅血，走行于内侧沟"},{"q":"下列关于椎间盘的叙述中，正确的是","o":["在成人共有25块","椎间盘突出时，多突向后外方","脊柱运动时，椎间盘形状不发生改变","椎间盘突出多发生脊柱胸段","黄韧带可防止椎间盘向后突出"],"a":1,"e":"椎间盘由纤维环和髓核构成，后方纤维环较薄，故突出多向后外方，压迫神经根。成人椎间盘共23个而非25个，脊柱运动时其形状随负重改变，突出好发于腰段而非胸段，防止后突的是后纵韧带，黄韧带位于椎板之间"},{"q":"下面结构中通过腕管的是","o":["尺侧腕屈肌","正中神经","掌长肌腱","桡侧腕屈肌腱","桡侧腕长伸肌"],"a":1,"e":"腕管由腕骨沟和屈肌支持带围成，通过者有正中神经及指浅、指深屈肌腱和拇长屈肌腱。尺侧腕屈肌、掌长肌腱、桡侧腕屈肌腱均行于屈肌支持带浅面或外侧，不进入腕管；桡侧腕长伸肌属伸肌群，位于伸肌支持带深面"},{"q":"对膀胱的描述，错误的是","o":["是储尿的器官","男性膀胱下方邻接尿生殖膈","空虚时，膀胱尖不超过耻骨联合上缘","肌层由平滑肌构成","是腹膜间位器官"],"a":1,"e":"膀胱为储尿器官，空虚时尖不超过耻骨联合上缘，肌层由平滑肌构成，属腹膜间位器官。男性膀胱下方邻接前列腺，女性下方才邻接尿生殖膈，该表述将女性关系误植于男性，故为错误项"},{"q":"营养内囊的动脉主要是","o":["椎动脉","大脑中动脉","大脑后动脉","颈内动脉","基底动脉"],"a":1,"e":"营养内囊的主要动脉是大脑中动脉，其发出的豆纹动脉等中央支穿入脑实质供应内囊膝和后肢。椎动脉、基底动脉主要供应脑干和小脑，大脑后动脉供应枕叶，颈内动脉为大脑中动脉的起始来源，均非内囊的直接主要供血动脉"},{"q":"前庭蜗器包括","o":["骨半规管、前庭和耳蜗","鼓室、咽鼓管和乳突小房","外耳、中耳和内耳","外耳道、鼓膜和鼓室","骨迷路和膜迷路"],"a":2,"e":"前庭蜗器又称位听器，包括外耳、中耳和内耳三部分。骨半规管、前庭和耳蜗属于内耳骨迷路，鼓室、咽鼓管和乳突小房属于中耳，骨迷路和膜迷路是内耳的组成，均不能概括整个前庭蜗器"},{"q":"下列结构中不含脑脊液的是","o":["蛛网膜下腔","小脑延髓池","终池","硬膜外隙","脊髓中央管"],"a":3,"e":"硬膜外隙位于椎管骨膜与硬脊膜之间，内含脂肪、静脉丛和淋巴管，呈负压，不含脑脊液。蛛网膜下腔、小脑延髓池、终池均为脑脊液循环的腔隙，脊髓中央管也与第四脑室相通并含脑脊液"},{"q":"支配躯干四肢骨骼肌随意运动的下运动神经元是","o":["锥体细胞","前角运动细胞","后角细胞","侧角细胞","双极细胞"],"a":1,"e":"前角运动细胞位于脊髓灰质前角，其轴突构成运动神经，直接支配躯干四肢骨骼肌随意运动，属下运动神经元。锥体细胞为大脑皮质上运动神经元，后角细胞为感觉中间神经元，侧角细胞为内脏运动神经元，双极细胞见于视网膜和嗅上皮"},{"q":"下列结构中属于关节辅助结构的是","o":["关节头","关节窝","关节唇","关节腔","关节囊"],"a":2,"e":"关节唇是附着于关节窝周缘的纤维软骨环，可加深关节窝、增大关节面，属关节辅助结构。关节头和关节窝构成关节面，与关节囊、关节腔同属关节主要结构，关节唇不在其列。关节囊由纤维层和滑膜层构成，是主要结构而非辅助结构"},{"q":"在呼吸道中，唯一具有完整软骨环的软骨是","o":["甲状软骨","环状软骨","会厌软骨","气管软骨环","杓状软骨"],"a":1,"e":"环状软骨是喉软骨中唯一完整的软骨环，对保持呼吸道通畅有重要作用，位于甲状软骨下方。气管软骨环为C形缺口向后，并非完整环；甲状软骨为最大喉软骨，会厌软骨和杓状软骨形态各异，均不构成完整环"},{"q":"关于椎动脉的叙述，正确的是","o":["穿行第1～7颈椎横突孔","发自颈总动脉","经枕骨大孔入颅腔","参与构成大脑动脉环","发自大脑中动脉"],"a":2,"e":"椎动脉起自锁骨下动脉，穿第6至第1颈椎横突孔，经枕骨大孔入颅腔。其穿经的是上位6个颈椎横突孔而非第1至第7全部；并非发自颈总动脉或大脑中动脉；直接参与大脑动脉环的是其合成的基底动脉，椎动脉本身不直接参与"},{"q":"喉腔内最狭窄的部位是","o":["声门下腔","前庭裂","喉室","声门裂","喉前庭"],"a":3,"e":"声门裂位于两侧声襞及杓状软骨之间，是喉腔最狭窄处，也是异物易滞留部位。声门下腔为声襞以下至环状软骨下缘的部分，虽易发生水肿但较宽；前庭裂、喉室和喉前庭的腔径均大于声门裂"},{"q":"关于食管的第一个狭窄，下列选项说法正确的是","o":["食管与左主支气管交叉处","约平第6颈椎体的上缘","距中切牙约15cm","平对胸骨角","距中切牙约25cm"],"a":2,"e":"食管第一狭窄位于食管起始处，约平第6颈椎体下缘，距中切牙约15cm。食管与左主支气管交叉处及平胸骨角处为第二狭窄，距中切牙约25cm；第6颈椎体上缘的高度描述不准确，第二狭窄对应约25cm而非此处"},{"q":"乳突是下面哪块骨上的结构","o":["蝶骨","颞骨","颧骨","枕骨","额骨"],"a":1,"e":"乳突是颞骨岩部后方的锥形突起，其内的乳突小房与中耳鼓室相通。蝶骨包含蝶鞍、翼突等结构，颧骨构成颧弓，枕骨有枕髁和枕外隆凸，额骨构成眶上缘和额窦，均无乳突"},{"q":"使瞳孔转向下外的肌是","o":["上斜肌","下斜肌","外直肌","内直肌","下直肌"],"a":0,"e":"上斜肌收缩使瞳孔转向下外，由滑车神经支配，是使眼球下外转的肌。下斜肌使瞳孔转向上外，外直肌使瞳孔外展，内直肌使瞳孔内收，下直肌使瞳孔转向下内，方向均与上斜肌不同"},{"q":"可以做环转运动的关节是","o":["肩关节","肘关节","指骨间关节","骶髂关节","关节突关节"],"a":0,"e":"肩关节为球窝关节，肱骨头与肩胛骨关节盂构成，是三轴关节，可作屈伸、收展、旋内旋外及环转运动。肘关节主要作屈伸，指骨间关节仅能屈伸，骶髂关节和关节突关节属微动关节，均不能完成环转"},{"q":"关于十二指肠，下列说法正确的是","o":["呈“C”形包绕胰头","只接受胃液和胆汁注入","全部由腹腔干分支供血","为腹膜外位器官","分为三部"],"a":0,"e":"十二指肠呈C形包绕胰头，其降部有十二指肠大乳头接受胆汁和胰液。它还接受肠系膜上动脉供血，并非全部来自腹腔干；大部为腹膜外位或间位；分为上、降、水平、升四部，且接受胃液、胆汁、胰液三种消化液"},{"q":"上消化道是指","o":["口腔至食管","口腔至回肠","口腔至空肠","口腔至十二指肠","口腔至胃"],"a":3,"e":"上消化道指口腔至十二指肠的一段，包括口腔、咽、食管、胃和十二指肠。口腔至食管或至胃均未包含十二指肠，范围不全；空肠、回肠属下消化道，因此口腔至空肠或回肠的说法错误"},{"q":"关于颈椎，正确的是","o":["均有椎体及椎弓","第1～2颈椎无横突孔","棘突末端都分叉","第6颈椎棘突末端膨大成颈动脉结节","第7颈椎又名隆椎"],"a":4,"e":"第7颈椎棘突长且末端不分叉，隆起于皮下，故名隆椎，是计数椎骨的标志。第1颈椎无椎体；各颈椎均有横突孔；第1颈椎无棘突、第7颈椎棘突不分叉，并非都分叉；颈动脉结节是第6颈椎横突前结节，与棘突无关"},{"q":"以下属于副交感神经核的是","o":["面神经核","舌下神经","动眼神经核","迷走神经背核","展神经核"],"a":3,"e":"迷走神经背核为副交感神经核，发出副交感节前纤维支配胸腹腔脏器。面神经核、动眼神经核、展神经核、舌下神经核均属躯体运动核，支配骨骼肌；舌下神经本身为脑神经名称而非核团，亦非副交感性质"},{"q":"与脑的血供无关的动脉是","o":["颈内动脉","椎动脉","基底动脉","脑膜中动脉","前、后交通动脉"],"a":3,"e":"脑膜中动脉为上颌动脉的分支，主要营养硬脑膜，不参与脑实质供血。颈内动脉、椎动脉、基底动脉以及前、后交通动脉共同构成脑的动脉供应和大脑动脉环，与脑血供直接相关"},{"q":"上颌窦开口于","o":["上鼻道","中鼻道","下鼻道","咽隐窝","蝶筛隐窝"],"a":1,"e":"上颌窦位于上颌骨体内，开口于中鼻道的半月裂孔，因开口位置较高、分泌物不易排出，窦腔积液时需体位引流。额窦开口于中鼻道前部的筛漏斗；筛窦前、中群开口于中鼻道、后群开口于上鼻道；蝶窦开口于蝶筛隐窝；下鼻道有鼻泪管开口"},{"q":"受桡神经支配的骨骼肌为","o":["三角肌","肱三头肌","肱肌","喙肱肌","背阔肌"],"a":1,"e":"肱三头肌由桡神经支配，是伸肘的主要肌。三角肌由腋神经支配，肱肌和喙肱肌由肌皮神经支配，背阔肌由胸背神经支配，它们的神经来源均非桡神经"},{"q":"做外耳道检查时，在成人应将耳廓拉向","o":["前上方","后上方","前下方","后下方","后方"],"a":1,"e":"成人外耳道呈S形弯曲，检查时须将耳廓拉向后上方以拉直外耳道。婴幼儿外耳道短而直，检查时应拉向后下方；前上、前下及正后方均不能与成人外耳道的走向对应，无法充分暴露鼓膜"},{"q":"关于心的位置，下列说法正确的是","o":["位于上纵隔","2/3在正中线的右侧","1/3在正中线的左侧","前面和两侧被肺与胸膜包裹","外面包有心包"],"a":4,"e":"心位于中纵隔，外面包以心包，这是其正确位置描述。心约2/3位于正中线左侧、1/3在右侧，并非2/3在右；前面大部被肺和胸膜遮盖，仅在心底处与胸壁相贴，两侧也不全被包裹，其余方位和比例描述错误"},{"q":"体循环起始于","o":["左心室","右心室","左心房","右心房","毛细血管"],"a":0,"e":"体循环又称大循环，起始于左心室，血液经主动脉及其分支流向全身，最后经上下腔静脉回流右心房。右心室为肺循环起点，左心房为肺循环终点，右心房为体循环终点，毛细血管是物质交换部位而非循环起点"},{"q":"乳腺脓肿切开引流应采用的切口","o":["横切口","纵切口","斜切口","放射状切口","乳房下切口"],"a":3,"e":"乳腺脓肿切开引流应采用放射状切口，与乳腺导管走向一致，可避免损伤输乳管导致乳瘘。横切口、纵切口、斜切口均与导管方向交叉，易切断导管；乳房下切口仅用于乳房后脓肿或特殊部位，非一般脓肿常规选择"},{"q":"关于横结肠的说法，正确的是","o":["与小网膜相连","无肠脂垂","位于左上腹部","属于腹膜间位器官","有系膜"],"a":4,"e":"横结肠属腹膜内位器官，有横结肠系膜连于腹后壁，活动度较大。小网膜连接肝与胃及十二指肠上部，与横结肠无关；结肠具有结肠带、结肠袋和肠脂垂；横结肠横跨上腹部而非局限于左上腹，亦非腹膜间位"},{"q":"关于垂体的描述，正确的是","o":["位于颅前窝的垂体窝内","神经垂体分泌抗利尿激素","一般女性的垂体较男性的大","腺垂体和神经垂体都具有内分泌功能","腺垂体分泌的促甲状腺素由神经垂体释放"],"a":2,"e":"一般女性垂体较男性为大，妊娠期更为明显，这是垂体的正常性别差异。垂体位于颅中窝蝶骨体上面的垂体窝；抗利尿激素由下丘脑合成、神经垂体储存释放；神经垂体本身无内分泌功能；促甲状腺素由腺垂体分泌并释放"},{"q":"鼻咽侧壁上的结构是","o":["咽鼓管咽口","舌扁桃体","腭扁桃体","蝶筛隐窝","梨状隐窝"],"a":0,"e":"咽鼓管咽口位于鼻咽侧壁，下鼻甲后方，是鼻咽的重要结构，连通鼻咽与鼓室。舌扁桃体位于舌根，腭扁桃体位于口咽，蝶筛隐窝在上鼻道后端属鼻腔，梨状隐窝位于喉咽，均不在鼻咽侧壁"},{"q":"肝的右纵沟后半部通过的结构是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","动脉导管"],"a":3,"e":"肝右纵沟前部为胆囊窝，容纳胆囊；后半部为腔静脉沟，有下腔静脉通过。肝圆韧带位于左纵沟前部，静脉韧带位于左纵沟后部，胆囊在右纵沟前部，动脉导管为胎儿时期结构，均不在右纵沟后半"},{"q":"关于乳糜池的描述，正确的是","o":["为成对的梭形膨大","位于第2腰椎体前方","由左、右腰干汇合而成","右淋巴导管起始于乳糜池","由左、右腰干和肠干汇合而成"],"a":4,"e":"乳糜池为胸导管起始处的梭形膨大，位于第1腰椎体前方，由左、右腰干和肠干汇合而成。其为单个而非成对；不在第2腰椎前方；仅腰干汇合的说法缺少肠干；右淋巴导管注入右静脉角，与乳糜池无关"},{"q":"下列关于脊髓内部结构的说法，正确的是","o":["中央管向上直接通第三脑室，内有脑脊液","由灰质、白质、神经核和神经纤维组成","中央管位于灰质连合的中央","前角基部外侧有网状结构","灰质连合与前正中裂之间的白质为白质连合"],"a":2,"e":"脊髓中央管位于灰质连合中央，纵贯脊髓全长，内含脑脊液。中央管向上通第四脑室而非第三脑室；脊髓主要由灰质和白质构成；网状结构位于侧角与后角之间；灰质连合与前正中裂之间为前白连合"},{"q":"锁骨下静脉的收集范围包括","o":["甲状腺静脉","面静脉","舌静脉","颈外静脉","颈内静脉"],"a":3,"e":"锁骨下静脉收集上肢、颈浅部和胸壁的静脉血，颈外静脉最终注入锁骨下静脉。甲状腺静脉、面静脉和舌静脉均汇入颈内静脉；颈内静脉与锁骨下静脉合成头臂静脉，本身并非锁骨下静脉的属支"},{"q":"关于牙的叙述，正确的是","o":["每个牙分为牙冠、牙根和牙腔三部分","乳牙分为切牙、尖牙和磨牙三种类型","幼儿3岁乳牙开始脱落","牙髓由血管、淋巴管和结缔组织构成","是人体中唯一没有血管的器官"],"a":1,"e":"乳牙分切牙、尖牙和磨牙三类，无前磨牙，这是其与恒牙的重要区别。牙分为牙冠、牙颈、牙根三部而非牙腔；乳牙约6岁开始脱落换恒牙；牙髓含血管、神经和疏松结缔组织；牙有丰富血供，并非无血管器官"},{"q":"下列关于精囊腺的描述，正确的是","o":["为囊状不成对器官","位于输精管壶腹的内侧","位于膀胱底的上方","通过直肠前壁可以触及","前邻前列腺"],"a":3,"e":"精囊腺位于膀胱底后方、输精管壶腹外侧，其后面邻接直肠，故可经直肠前壁触及。其为成对囊状腺体；位于膀胱底后方而非上方；前邻膀胱而非前列腺；前列腺位于其下方，均与描述不符"},{"q":"有关腱鞘的描述，正确的是","o":["腱位于滑液鞘内","由腱纤维鞘和腱滑膜鞘组成","腱系膜由腱纤维鞘形成","腱纤维鞘分为壁层和脏层","腱滑膜鞘由深筋膜增厚形成"],"a":1,"e":"腱鞘由外层腱纤维鞘和内层腱滑膜鞘构成，后者又分壁层与脏层，两层间含滑液。肌腱被滑膜脏层包绕并在鞘管内滑动；腱系膜由腱滑膜鞘的血管进入处形成；腱纤维鞘由深筋膜增厚形成，腱滑膜鞘则为滑膜结构"},{"q":"和中脑脚间窝相连的神经根为","o":["视神经","动眼神经","滑车神经","展神经","面神经"],"a":1,"e":"动眼神经起自中脑脚间窝，支配大部分眼外肌和提上睑肌。视神经起自间脑，滑车神经起自中脑下丘下方，展神经和面神经均起自脑桥，与脚间窝相连的神经根只有动眼神经"},{"q":"下列骨骼肌中不受正中神经支配的为","o":["肱桡肌","旋前圆肌","桡侧腕屈肌","指浅屈肌","旋前方肌"],"a":0,"e":"肱桡肌由桡神经支配，不属正中神经支配范围。旋前圆肌、桡侧腕屈肌、指浅屈肌和旋前方肌均由正中神经或其分支骨间前神经支配，是前臂屈肌群中受正中神经支配的主要肌"},{"q":"有关节内软骨的关节是","o":["肩关节","肘关节","髋关节","膝关节","距小腿关节"],"a":3,"e":"膝关节内有半月板，为纤维软骨构成的关节内软骨，可加深关节窝、缓冲震荡。肩关节和髋关节的关节唇为附着于关节窝周缘的纤维软骨环，不属关节内软骨；肘关节和距小腿关节无关节内软骨"},{"q":"主动脉弓的描述何者有误","o":["是主动脉的第2段","位于胸骨柄的后方","弓形弯向左后方","凸缘的分支自右至左是头臂干、左锁骨下动脉、左颈总动脉","至第4胸椎体下缘平面与胸主动脉相续"],"a":3,"e":"主动脉弓凸缘自右向左依次发出头臂干、左颈总动脉和左锁骨下动脉，题中将后两者顺序颠倒，故为错误。主动脉弓为主动脉第二段，位于胸骨柄后方，弓形弯向左后，至第4胸椎体下缘续为胸主动脉"},{"q":"使瞳孔转向上外的肌是","o":["上斜肌","下斜肌","外直肌","内直肌","上直肌"],"a":1,"e":"下斜肌收缩使瞳孔转向上外，由动眼神经支配。上斜肌使瞳孔转向下外，由滑车神经支配；外直肌使眼球外展；内直肌使眼球内收；上直肌主要使瞳孔转向上内，方向均不同于下斜肌"},{"q":"中枢神经系统中，神经元胞体聚集构成的结构是","o":["神经核","纤维束","网状结构","神经节","神经"],"a":0,"e":"神经核是中枢神经系统内形态功能相似的神经元胞体聚集而成的结构。纤维束为轴突聚集；网状结构为灰白质交错区域；神经节和神经均为周围神经系统的结构，其中神经节是胞体聚集处，不属中枢"},{"q":"肝的左纵沟前半部容纳的是","o":["肝圆韧带","静脉韧带","胆囊","下腔静脉","镰状韧带"],"a":0,"e":"肝左纵沟前部为肝圆韧带窝，容纳脐静脉闭锁形成的肝圆韧带；后部为静脉韧带窝。胆囊位于右纵沟前部的胆囊窝，下腔静脉行于右纵沟后半的腔静脉沟，镰状韧带为肝表面的腹膜皱襞，均不在左纵沟前半"},{"q":"下列关于附睾的描述，正确的是","o":["为男性生殖腺","全部由附睾管构成","贴附于睾丸前缘","为附属腺之一","下连输精管"],"a":4,"e":"附睾贴附于睾丸后缘，分头、体、尾，其尾部向下续接输精管。睾丸才是男性生殖腺，附睾头由输出小管构成而非全部附睾管，附睾不属附属腺，附属腺为精囊、前列腺和尿道球腺"},{"q":"有关心的后方，何者为错","o":["平对第5～8胸椎","有胸主动脉","有食管","有迷走神经","主要是右心房"],"a":4,"e":"心的后面主要由左心房构成，并有肺静脉注入，右心房主要构成心的右缘和前面。心后方平对第5至第8胸椎，与胸主动脉、食管和迷走神经相邻，这些结构位于后纵隔，与心后面毗邻，故“主要是右心房”错误"},{"q":"下列关于肩关节的叙述中，正确的是","o":["由肱骨头和肩胛骨关节盂构成","关节盂较大而深","关节内有关节盘","关节囊内有肱三头肌长头肌腱通过","只能做屈伸、旋转运动"],"a":0,"e":"肩关节由肱骨头与肩胛骨关节盂构成，肱骨头大、关节盂小而浅，是全身最灵活的关节。关节囊内有肱二头肌长头腱通过而非肱三头肌；关节内无关节盘；可作屈伸、收展、旋内旋外和环转，运动范围远不止屈伸旋转"},{"q":"组成臂丛的纤维是","o":["第5～8颈神经前支和第1胸神经前支的大部分纤维","第5～8颈神经前支和第1胸神经前支的小部分纤维","第5～8颈神经和第1胸神经的大部分纤维","第5～7颈神经前支和第1胸神经前支的大部分纤维","第5～7颈神经前支和第1胸神经前支的小部分纤维"],"a":0,"e":"臂丛由第5至第8颈神经前支和第1胸神经前支的大部分纤维组成，经斜角肌间隙穿出。若只取第5至第7颈神经或缺第1胸神经则来源不全；小部分纤维或用于后支、全部神经的说法均不准确，前支的大部分才是其正确构成"},{"q":"位于前臂肌前群浅层最外侧的肌肉是","o":["肱二头肌","肱三头肌","喙肱肌","肱桡肌","桡侧腕屈肌"],"a":3,"e":"肱桡肌位于前臂肌前群浅层最外侧即桡侧，由桡神经支配，可屈肘。肱二头肌、喙肱肌属臂肌前群，肱三头肌属臂肌后群，均不在前臂；桡侧腕屈肌虽在前臂浅层但位于肱桡肌尺侧，不是最外侧"},{"q":"临床上后尿道是指","o":["尿道海绵体部","尿道膜部和前列腺部","尿道膜部","尿道膜部和海绵体部","尿道海绵体部和前列腺部"],"a":1,"e":"临床上后尿道指尿道膜部和前列腺部，二者位置较固定，损伤后尿液易外渗。尿道海绵体部为前尿道，穿尿道海绵体，活动度大；仅膜部或仅海绵体部、前列腺部与海绵体部的组合均不符合前后尿道的划分"},{"q":"支配股四头肌的神经为","o":["闭孔神经","坐骨神经","股神经","髂腹下神经","髂腹股沟神经"],"a":2,"e":"股神经支配股四头肌，为腰丛最大分支，同时支配缝匠肌并管理大腿前面及小腿内侧感觉。闭孔神经支配大腿内收肌群，坐骨神经支配大腿后群肌，髂腹下神经和髂腹股沟神经主要支配腹壁肌及相应区感觉，均不支配股四头肌"},{"q":"近侧列腕骨不包括","o":["手舟骨","月骨","三角骨","钩骨","豌豆骨"],"a":3,"e":"近侧列腕骨由桡侧向尺侧为手舟骨、月骨、三角骨和豌豆骨，钩骨属远侧列腕骨。钩骨与头状骨、小多角骨、大多角骨同列，位于远侧列尺侧，与近侧列无关，故为不包括者"},{"q":"关于椎体的说法，错误的是","o":["呈短圆柱状","位于椎骨前部","主要由松质构成","表面有一层密质","椎体中央有椎孔"],"a":4,"e":"椎体呈短圆柱状，位于椎骨前部，主要由松质构成，表面覆以薄层密质。椎孔由椎体与椎弓共同围成，并非位于椎体中央；椎体内部为松质和红骨髓，无椎孔结构，此项混淆了椎体与椎孔的构成关系"},{"q":"肝上界与右锁骨中线相交的肋是","o":["第7肋","第5肋","第6肋","第8肋","第9肋"],"a":1,"e":"肝上界与右锁骨中线相交于第5肋，右腋中线相交于第7肋，右肩胛线相交于第10肋。第6、7、8、9肋均低于第5肋，其中第7肋为腋中线投影高度，第9肋接近下界，均非锁骨中线上的肝上界标志"},{"q":"以下哪项属于内分泌组织","o":["胸腺","垂体","胰岛","松果体","肾上腺"],"a":2,"e":"胰岛是散布于胰腺内的内分泌细胞团，属内分泌组织而非独立器官。胸腺、垂体、松果体和肾上腺均为独立的内分泌器官，有完整被膜和器官结构，与胰岛作为胰腺内细胞团的性质不同"},{"q":"关于海绵窦的叙述中，错误的是","o":["位于垂体窝两侧","窦内充满静脉血","窦内充满脑脊液","外侧壁有动眼神经、滑车神经通过","内侧壁有展神经通过"],"a":2,"e":"海绵窦位于蝶鞍两侧，窦内充满静脉血，其外侧壁有动眼神经、滑车神经及三叉神经第一、二支通过，内侧壁有展神经和颈内动脉通过。窦内不含脑脊液，故“充满脑脊液”错误；充满静脉血才是其正确内容"},{"q":"拇指腕掌关节由第1掌骨与哪块骨构成","o":["手舟骨","桡骨下端","尺骨下端","大多角骨","小多角骨"],"a":3,"e":"拇指腕掌关节由第1掌骨底与大多角骨构成，为鞍状关节，可作屈伸、收展、对掌和环转。手舟骨属近侧列腕骨并与桡骨构成桡腕关节，桡骨下端、尺骨下端参与前臂和腕关节构成，小多角骨与第2掌骨相关，均不参与拇指腕掌关节"},{"q":"下列颈丛组成的描述，正确的是","o":["第1～4颈神经全部","第1～4颈神经前支","第1～4颈神经后支","第1～3颈神经前支全部和第4颈神经前支大部分","第1～3颈神经前支全部和第4颈神经前支小部分"],"a":1,"e":"颈丛由第1至第4颈神经前支组成，位于胸锁乳突肌深面、中斜角肌与肩胛提肌前方。用后支或全部颈神经均非其构成；将第4颈神经前支分为大部分或小部分参与的说法也不符合颈丛由第1至第4颈神经前支组成的定义"},{"q":"头面部浅感觉传导通路的第3级神经元是","o":["锥体细胞","三叉神经脊束核","三叉神经脑桥核","丘脑腹后内侧核","丘脑腹后外侧核"],"a":3,"e":"头面部浅感觉传导通路的第3级神经元为丘脑腹后内侧核，其轴突投射至大脑皮质中央后回下部。三叉神经脊束核和脑桥核为第2级神经元胞体所在；锥体细胞为皮质运动神经元；丘脑腹后外侧核为躯干四肢浅感觉的第3级神经元"},{"q":"有关前、中、后斜角肌的描述，正确的是","o":["构成颈深肌群的外侧群","起自颈椎椎体的前面","止于第1肋","斜角肌间隙内通过锁骨下动脉和静脉","收缩可助呼气"],"a":0,"e":"前、中、后斜角肌构成颈深肌群外侧群，起自颈椎横突，收缩可助吸气。前、中斜角肌止于第1肋，后斜角肌止于第2肋，并非都止于第1肋；斜角肌间隙内通过锁骨下动脉和臂丛，锁骨下静脉行于前斜角肌前方，不在此间隙内"},{"q":"可以维持子宫前屈位的韧带是","o":["子宫阔韧带","卵巢悬韧带","子宫圆韧带","子宫主韧带","子宫骶韧带"],"a":4,"e":"子宫骶韧带向后上方牵拉子宫颈，使子宫体前倾并维持前屈位。子宫圆韧带主要维持子宫前倾，子宫主韧带固定宫颈防止脱垂，子宫阔韧带限制子宫向两侧移位，卵巢悬韧带悬吊卵巢，作用各不相同"},{"q":"垂体窝位于下面哪块颅骨上","o":["额骨","颞骨","顶骨","筛骨","蝶骨"],"a":4,"e":"垂体窝位于蝶骨体上面的蝶鞍中央，容纳垂体。额骨构成眶上缘和额窦，颞骨含外耳道和乳突，顶骨构成颅顶，筛骨含筛板和筛窦，均不形成垂体窝，只有蝶骨体的鞍区与垂体相关"},{"q":"一侧皮质核束不支配","o":["同侧的动眼神经核","对侧的三叉神经运动核","对侧的滑车神经核","同侧的舌下神经核","对侧的疑核"],"a":3,"e":"一侧皮质核束不支配同侧舌下神经核，因舌下神经核只接受对侧皮质核束支配，面神经核下部亦然。动眼神经核、滑车神经核及疑核等受双侧皮质核束支配，故同侧动眼、滑车神经核及三叉神经运动核、疑核均有同侧支配，不受此限"},{"q":"关于骶骨描述，正确的是","o":["由3块骶椎组成","骶前孔、骶后孔均与骶管相通","骶骨的耳状面与髋骨的耳状面相连，属直接连接","骶管与椎管不通","女性骶岬较男性突出"],"a":1,"e":"骶骨由5块骶椎融合而成，骶前孔和骶后孔均与骶管相通，分别有骶神经前、后支通过。耳状面与髋骨构成骶髂关节，属间接连接；骶管与椎管相续；骶岬在男性更为突出，女性骶骨则较短宽"},{"q":"上颌神经通过颅底什么结构出颅","o":["眶上裂","圆孔","卵圆孔","棘孔","颈静脉孔"],"a":1,"e":"上颌神经为三叉神经第二支，经圆孔出颅，支配上颌部感觉。眼神经经眶上裂出颅，下颌神经经卵圆孔出颅，脑膜中动脉经棘孔入颅，舌咽、迷走、副神经经颈静脉孔出颅，出颅通道各有不同"},{"q":"关于主支气管描述正确的是","o":["左主支气管短、粗且走向较垂直","是喉至肺之间的管道","是气管杈至肺门之间的管道","右主支气管长、细且走向较垂直","右主支气管短、细且走向较水平"],"a":2,"e":"主支气管是气管杈至肺门之间的管道，左、右各一。左主支气管长、细而较水平，右主支气管短、粗而较垂直，故异物多坠入右侧；喉至肺之间还包括气管，气管杈至肺门才专指主支气管，其余方向描述均与左右支气管的实际形态相反"},{"q":"有关面神经的叙述，错误的是","o":["为第Ⅶ对脑神经","管理舌前2/3黏膜的味觉","控制腮腺的分泌","支配面肌的运动","控制泪腺的分泌"],"a":2,"e":"腮腺由舌咽神经经耳神经节发出的节后纤维支配，面神经并不控制腮腺分泌。面神经为第Ⅶ对脑神经，其鼓索支配舌前2/3味觉，支配面肌运动，岩大神经经翼腭神经节支配泪腺分泌，故其余描述均为面神经的功能"},{"q":"关于肺下界的体表投影，下列说法正确的是","o":["在锁骨中线与第8肋相交","在腋中线与第10肋相交","在腋前线与第10肋相交","在肩胛线与第11肋相交","近后正中线处平第10胸椎棘突"],"a":4,"e":"肺下界在近后正中线处平第10胸椎棘突，是肺下界体表投影的正确标志。锁骨中线处平第6肋，腋中线平第8肋，肩胛线平第10肋，腋前线约平第7肋，题中所给锁骨中线第8肋、腋中线第10肋、肩胛线第11肋均与实际不符"},{"q":"头臂静脉的收集范围不包括","o":["心脏","颅骨","颈部","上肢","脑"],"a":0,"e":"头臂静脉由颈内静脉与锁骨下静脉合成，收集头颈部、上肢及胸壁的静脉血。心脏的静脉血大部经冠状窦直接汇入右心房，不经头臂静脉；颅骨、颈部、上肢和脑的静脉血均汇入颈内静脉或锁骨下静脉，再汇入头臂静脉"},{"q":"新纹状体是指","o":["豆状核","尾状核和壳","尾状核和苍白球","壳","苍白球"],"a":1,"e":"纹状体由尾状核和豆状核组成，豆状核又分为壳和苍白球。种系发生上尾状核和壳较新，合称新纹状体；苍白球较古老，称旧纹状体。新纹状体接受大脑皮质纤维，发出纤维至苍白球和黑质，是锥体外系重要环节。屏状核位于岛叶皮质深面，不属纹状体"},{"q":"从侧面观察，脊柱有","o":["向后凸的颈曲","向前凸的胸曲","向后凸的腰曲","向前凸的骶曲","23对椎间孔"],"a":4,"e":"脊柱侧面观有颈、胸、腰、骶四个生理弯曲，其中颈曲和腰曲向前凸，胸曲和骶曲向后凸。题中将颈曲、胸曲、腰曲、骶曲的凸向全部颠倒，均不成立；相邻椎骨间的椎间孔共23对，是侧面观可见的结构，为唯一正确项"},{"q":"翼腭神经节发出的节后纤维支配","o":["瞳孔括约肌","睫状肌","腮腺","泪腺","瞳孔开大肌"],"a":3,"e":"翼腭神经节为副交感神经节，其节后纤维支配泪腺分泌，来自面神经岩大神经。瞳孔括约肌和睫状肌由动眼神经副核经睫状神经节支配，腮腺由舌咽神经经耳神经节支配，瞳孔开大肌由交感神经颈上神经节支配"},{"q":"躯干骨在体表易摸到的骨性标志是","o":["肋凹","肋沟","胸椎横突","胸骨角","骶岬"],"a":3,"e":"胸骨角是胸骨柄与胸骨体连接处向前隆凸的骨性标志，平对第2肋，体表易于触及。肋凹和肋沟位于胸椎和肋骨，位置深在；胸椎横突被肌肉覆盖；骶岬位于骨盆入口后缘，均不易在体表清楚摸到"},{"q":"关于胃分部的叙述，不正确的是","o":["胃底在临床上有时称为胃穹窿","通常将胃分为4部分","贲门附近的区域称为贲门部","自胃底至角切迹的部分称胃体","幽门部的左侧部分称为幽门管"],"a":4,"e":"幽门部以中间沟为界分为幽门窦和幽门管，其中靠近幽门的右侧部分称幽门管，左侧部称幽门窦，故题中说法颠倒。胃底在临床亦称胃穹窿，胃通常分贲门部、胃底、胃体和幽门部四部，自胃底至角切迹为胃体，这些描述均正确"},{"q":"有结肠带的肠管是","o":["直肠","盲肠","回肠","阑尾","肛管"],"a":1,"e":"结肠带是结肠和盲肠特有的纵行肌增厚结构，盲肠具有结肠带、结肠袋和肠脂垂。直肠、肛管和阑尾均无结肠带，回肠为小肠，也无结肠带；这三种结构是区别大肠与小肠的重要形态标志"},{"q":"下列关于肩关节的叙述中，错误的是","o":["由肱骨头和肩胛骨关节盂构成","肱骨头大，关节盂小而浅","关节内有关节盘","关节囊内有肱二头肌长头肌腱通过","是全身运动最灵活的关节"],"a":2,"e":"肩关节内没有关节盘，这是其结构特点。肩关节由肱骨头和肩胛骨关节盂构成，肱骨头大、关节盂小而浅，关节囊内有肱二头肌长头腱通过，是全身运动最灵活的关节，这些描述均正确"},{"q":"臂丛由何处穿出经锁骨后方进入腋窝","o":["胸锁乳突肌浅层","中斜角肌后方","前斜角肌前方","斜角肌间隙","后斜角肌后方"],"a":3,"e":"臂丛自斜角肌间隙穿出，该间隙由前、中斜角肌与第一肋围成，内有锁骨下动脉和臂丛通过。胸锁乳突肌浅层、前斜角肌前方、中斜角肌后方及后斜角肌后方均非臂丛穿出的部位，臂丛位于锁骨下动脉的后上方并经此间隙进入腋窝"},{"q":"支配眼轮匝肌的神经为","o":["动眼神经","眼神经","面神经","视神经","滑车神经"],"a":2,"e":"眼轮匝肌属面肌，由面神经支配，收缩可闭眼。上睑提肌由动眼神经支配，眼神经为三叉神经第一支主管眼区感觉，视神经传导视觉冲动，滑车神经支配上斜肌，它们均不支配眼轮匝肌"},{"q":"自脊髓骶部第2～4节段灰质的骶副交感核发出的纤维最终支配的器官为","o":["肾","空肠","横结肠","回肠","降结肠"],"a":4,"e":"骶副交感核位于脊髓第2至第4骶节，发出盆内脏神经，支配降结肠、乙状结肠、直肠及盆腔脏器。肾、空肠、回肠和横结肠主要由迷走神经或交感神经支配，其中空肠、回肠、横结肠属迷走神经分布范围，只有降结肠属骶副交感支配"},{"q":"椎骨的描述，正确的是","o":["所有颈椎棘突分叉","第6颈椎称隆椎","腰椎关节呈冠状位","腰椎棘突宽而短呈板状","胸椎椎体都有一完整肋凹"],"a":3,"e":"腰椎棘突宽而短，呈板状水平后伸，棘突间隙较宽，便于腰椎穿刺。并非所有颈椎棘突都分叉，第7颈椎称隆椎；腰椎关节突呈矢状位，冠状位为胸椎特点；胸椎椎体自上而下由完整肋凹渐变为半肋凹，并非都有完整肋凹"},{"q":"关于牙的说法，正确的是","o":["磨牙萌出晚，故又称迟牙或智牙","牙包括牙冠、牙颈、牙根和牙龈","牙内的腔隙称牙腔，牙腔内充满牙髓","牙周组织包括牙质、牙槽和牙周膜","牙由釉质和牙质构成"],"a":2,"e":"牙内的腔隙称牙腔，内含由血管、神经和结缔组织构成的牙髓。第三磨牙萌出最晚称迟牙或智牙，并非所有磨牙；牙分牙冠、牙颈、牙根三部，牙龈属牙周组织；牙周组织包括牙周膜、牙槽骨和牙龈；牙由釉质、牙质和牙骨质构成"},{"q":"椎前节不包括","o":["奇神经节","腹腔神经节","肠系膜上神经节","肠系膜下神经节","主动脉肾神经节"],"a":0,"e":"奇神经节位于骶尾关节前方，属交感干神经节的椎旁节，不属椎前节。腹腔神经节、肠系膜上神经节、肠系膜下神经节和主动脉肾神经节均位于腹主动脉分支周围，为典型的椎前节，奇神经节位置与来源均不同"},{"q":"关于空肠特点的叙述，不正确的是","o":["血供丰富、颜色呈粉红色","空肠常位于左腰区和脐区","空肠系膜内动脉弓数多、直血管短","黏膜内主要有孤立淋巴滤泡","管径粗、壁厚"],"a":2,"e":"空肠系膜内动脉弓较少、直血管较长，动脉弓数多、直血管短是回肠的特点。空肠血供丰富呈粉红色，多位于左腰区和脐区，黏膜内主要是孤立淋巴滤泡，管径粗、管壁较厚，这些均为空肠特征，故错误项在动脉弓与直血管的描述"},{"q":"迷走神经背核支配的器官不包括","o":["心","肾","直肠","小肠","横结肠"],"a":2,"e":"直肠由骶副交感神经即盆内脏神经支配，不属迷走神经背核分布范围。迷走神经背核支配心、肾、小肠和横结肠等胸腔及腹腔脏器，至结肠左曲以上的消化管；直肠位于盆腔内，其副交感支配来自脊髓骶段，与迷走神经来源不同"},{"q":"关于输尿管的描述，正确的是","o":["起于肾大盏终于膀胱","有两个弯曲","穿过尿生殖膈","沿腰大肌前面下降","肌层由骨骼肌构成"],"a":3,"e":"输尿管沿腰大肌前面下降，属腹膜外位器官，肌层由平滑肌构成。它起于肾盂而非肾大盏，终于膀胱；全程有三个生理性狭窄而非两个弯曲；男性输尿管不穿尿生殖膈，穿尿生殖膈的是输精管或尿道，故其余描述均不准确"},{"q":"肱骨上端骨折的最易发部位是","o":["解剖颈","外科颈","肱骨干","肱骨下端","外侧髁"],"a":1,"e":"肱骨外科颈位于肱骨上端与体交界处，是骨折最易发部位，因该处骨质较细且为松质与密质移行区。解剖颈为肱骨头周围的环形浅沟，骨折较少；肱骨干、肱骨下端及外侧髁均非肱骨上端骨折的最好发部位"},{"q":"下列哪个静脉是浅静脉","o":["肱静脉","股静脉","头静脉","尺静脉","桡静脉"],"a":2,"e":"头静脉是上肢重要的浅静脉，起自手背静脉网桡侧，沿前臂桡侧上行注入腋静脉。肱静脉、股静脉、尺静脉和桡静脉均为深静脉，多与同名动脉伴行，位于深筋膜深面，与头静脉的浅表位置不同"},{"q":"关于直肠的叙述，错误的是","o":["在第5腰椎高度续于乙状结肠","下段膨大为直肠壶腹","直肠指诊，男性可触及前列腺、精囊","直肠指诊，女性可触及或子宫和阴道","穿盆膈续于肛管"],"a":0,"e":"直肠在第3骶椎高度续于乙状结肠，而非第5腰椎高度。直肠下段膨大形成直肠壶腹，直肠指诊男性可触及前列腺和精囊，女性可触及子宫和阴道，直肠穿盆膈后续于肛管，这些描述均正确，错误只在续接高度"},{"q":"支配臀大肌的神经是","o":["阴部神经","臀上神经","臀下神经","髂腹下神经","髂腹股沟神经"],"a":2,"e":"臀下神经支配臀大肌，该肌为髋关节有力的伸肌和外旋肌。臀上神经支配臀中肌、臀小肌和阔筋膜张肌，阴部神经支配会阴部肌，髂腹下神经和髂腹股沟神经支配腹壁肌及腹股沟区感觉，均不支配臀大肌"},{"q":"下列结构中属于关节主要结构的是","o":["关节唇","关节盘","关节半月板","关节囊","滑膜囊"],"a":3,"e":"关节囊由纤维层和滑膜层构成，与关节面、关节腔同属关节的主要结构，是维持关节连接和运动的基础。关节唇、关节盘、半月板均为辅助结构，滑膜囊为独立于关节的滑液囊，也不属关节主要结构"},{"q":"关于肝门的描述，正确的是","o":["出肝门的是肝门静脉","入肝门的是肝左管","出肝门的是下腔静脉","入肝门的是肝固有动脉","出肝门的是静脉导管"],"a":3,"e":"肝固有动脉是入肝门的重要结构，与肝门静脉、肝管伴行进出肝门。肝门静脉为入肝门而非出肝门；肝左管为出肝门的管道；下腔静脉经第二肝门出肝，不在第一肝门；静脉导管为胎儿时期结构，生后闭锁，均不符合肝门出入关系"},{"q":"下列何者不是颈外动脉的分支","o":["甲状腺上动脉","舌动脉","面动脉","椎动脉","枕动脉"],"a":3,"e":"椎动脉起自锁骨下动脉，穿颈椎横突孔经枕骨大孔入颅，不属颈外动脉分支。甲状腺上动脉、舌动脉、面动脉和枕动脉均为颈外动脉的前支或后支，是颈外动脉供应头颈部的主要分支"},{"q":"在消化管壁上，由平滑肌增厚所形成的环行肌不包括","o":["贲门括约肌","肝胰壶腹括约肌","肛门外括约肌","肛门内括约肌","幽门括约肌"],"a":2,"e":"肛门外括约肌为骨骼肌，属随意肌，可主动控制排便，不是平滑肌增厚形成的环行肌。贲门括约肌、幽门括约肌、肛门内括约肌和肝胰壶腹括约肌均由平滑肌增厚形成，属不随意肌，与肛门外括约肌性质不同"},{"q":"延髓脑桥沟处有三对脑神经穿过，其中，最靠近中线的脑神经是","o":["三叉神经","展神经","面神经","前庭蜗神经","舌咽神经"],"a":1,"e":"延髓脑桥沟内自中线向外依次有展神经、面神经和前庭蜗神经根穿出，故最靠近中线的是展神经。三叉神经自脑桥腹侧面出脑，位置更外侧且不在延髓脑桥沟；舌咽神经自延髓橄榄后沟出脑，与该沟无关，面神经和前庭蜗神经均位于展神经外侧"},{"q":"肾动脉的描述何者有误","o":["肾动脉直接起自腹主动脉","左肾动脉短","右肾动脉长","肾副动脉不经肾门入肾","右肾动脉经下腔静脉的前面至右肾"],"a":4,"e":"右肾动脉起自腹主动脉后，经下腔静脉后方而非前方至右肾，故该描述有误。左肾动脉较短，右肾动脉较长；肾动脉直接起自腹主动脉；肾副动脉多为不经肾门入肾的额外动脉，这些描述均正确，错误只在右肾动脉与下腔静脉的前后关系"},{"q":"有关颈总动脉的描述，错误的是","o":["左侧起自主动脉弓","右侧起自头臂动脉","至舌骨大角平面分为颈内、颈外动脉","颈动脉结节是颈总动脉的压迫止血点","分叉处有颈动脉球"],"a":2,"e":"颈总动脉左侧起自主动脉弓、右侧起自头臂干，于甲状软骨上缘平面分为颈内、颈外动脉，分叉处膨大称颈动脉窦。舌骨大角平面并非分叉平面，该项所述平面错误。颈动脉结节为第6颈椎横突前结节，是颈部压迫止血点"},{"q":"包绕于肾和肾上腺周围的是","o":["肾筋膜前层","肾筋膜后层","肾纤维囊","肾脂肪囊","脏腹膜"],"a":3,"e":"肾脂肪囊为包绕肾和肾上腺周围的脂肪组织层，起缓冲与固定作用。肾纤维囊紧贴肾实质表面，不包绕肾上腺；肾筋膜位于脂肪囊外，前、后两层在肾上腺上方相互融合。脏腹膜仅覆盖肾前面，不包绕肾上腺"},{"q":"伸膝时，防止胫骨前移的结构是","o":["胫侧副韧带","腓侧副韧带","髌韧带","前交叉韧带","后交叉韧带"],"a":3,"e":"前交叉韧带起自胫骨髁间隆起前部，止于股骨外侧髁内侧面，伸膝时紧张，限制胫骨前移。后交叉韧带限制胫骨后移，作用与之相反。胫、腓侧副韧带主要限制膝关节侧方异常运动，髌韧带为股四头肌腱的延续，主司伸膝"},{"q":"不成对的脑颅骨是","o":["顶骨","蝶骨","颞骨","犁骨","下颌骨"],"a":1,"e":"蝶骨位于颅底中央，为不成对的脑颅骨，额骨、筛骨、枕骨亦属不成对脑颅骨。顶骨与颞骨为成对的脑颅骨。犁骨与下颌骨虽不成对，但属于面颅骨，不属脑颅骨，这是易混之处"},{"q":"胸膜下界在腋中线处相交于","o":["第8肋","第9肋","第10肋","第11肋","第12肋"],"a":2,"e":"胸膜下界在锁骨中线平第8肋、腋中线平第10肋、肩胛线平第12肋，较肺下界各低两个肋间隙。肺下界在腋中线平第8肋，常与胸膜下界混淆。第11、12肋多对应肩胛线附近平面，并非腋中线处的胸膜下界"},{"q":"属于肋骨的结构是","o":["肋凹","横突肋凹","肋切迹","锁切迹","肋沟"],"a":4,"e":"肋沟位于肋骨内面下缘，为肋间神经和血管走行处，属肋骨本身结构。肋凹与横突肋凹位于胸椎，分别与肋头、肋结节相关节；肋切迹与锁切迹位于胸骨，分别承接肋软骨与锁骨，均不属于肋骨"},{"q":"视觉传导通路的第2级神经元是","o":["视杆细胞","视锥细胞","双极细胞","神经节细胞","锥体细胞"],"a":3,"e":"视觉传导路第1级神经元为视网膜双极细胞，第2级为视网膜节细胞，其轴突组成视神经，第3级神经元位于外侧膝状体。视杆、视锥细胞是感光换能的感受器，不属传导神经元；锥体细胞为大脑皮质运动神经元，与视觉通路无关"},{"q":"关于右淋巴导管的描述，正确的是","o":["亦称胸导管","长约30～40cm","注入右静脉角","收集上半身的淋巴","由右颈干和右锁骨下干合成"],"a":2,"e":"右淋巴导管由右颈干、右锁骨下干和右支气管纵隔干合成，注入右静脉角，收集右上肢、右头颈及右胸部淋巴，约占全身四分之一。胸导管又称左淋巴导管，长约30～40cm，收集其余四分之三；右淋巴导管短小，且非由两条干合成"},{"q":"收集下肢、盆部和腹部成对脏器的淋巴干是","o":["肠干","颈干","腰干","锁骨下干","支气管纵隔干"],"a":2,"e":"腰干由腰淋巴结输出管合成，收集下肢、盆部及腹腔成对脏器如肾、肾上腺的淋巴，注入乳糜池。肠干收集腹腔不成对脏器即消化管、肝、脾、胰的淋巴；颈干引流头颈部，锁骨下干引流上肢，支气管纵隔干引流胸部"},{"q":"和延髓锥体外侧相连的脑神经为","o":["动眼神经","展神经","滑车神经","舌下神经","迷走神经"],"a":3,"e":"舌下神经根丝自延髓前外侧沟即锥体外侧出脑，支配舌肌。展神经起自延髓脑桥沟；迷走神经根丝自延髓后外侧沟即橄榄后沟出脑；滑车神经于中脑下丘下方出脑；动眼神经自中脑脚间窝出脑"},{"q":"关于腭的描述，错误的是","o":["硬腭由腭骨覆以黏膜而成","软腭的后缘游离","前2/3为硬腭，后1/3为软腭","腭是口腔的顶，分隔鼻腔与口腔","吞咽时，软腭上提可分隔鼻咽、口咽"],"a":0,"e":"硬腭由上颌骨腭突与腭骨水平板覆以黏膜构成，并非仅由腭骨形成，故该项错误。腭前三分之二为硬腭、后三分之一为软腭，软腭后缘游离；吞咽时软腭上提分隔鼻咽与口咽；腭构成口腔顶，分隔口腔与鼻腔"},{"q":"下列关于子宫的描述，正确的是","o":["分为子宫底、子宫体及子宫颈管","下端的部分称为子宫底","底和体交界的部位称为子宫峡","子宫的内腔称为子宫腔","伸入阴道的部分称为子宫颈阴道部"],"a":4,"e":"子宫颈下端伸入阴道的部分称子宫颈阴道部，为正确描述。子宫分为底、体、颈三部，子宫颈管不属于其分部；下端狭窄部为子宫颈而非子宫底；子宫峡位于子宫体与颈交界处，并非底体交界；子宫腔仅指子宫体内的腔隙"},{"q":"锁骨下动脉的分支中没有","o":["椎动脉","甲状颈干","胸廓内动脉","肋颈干","甲状腺上动脉"],"a":4,"e":"锁骨下动脉主要分支有椎动脉、胸廓内动脉、甲状颈干和肋颈干。甲状腺上动脉起自颈外动脉起始部，是甲状腺的主要供血动脉，不属锁骨下动脉分支。甲状颈干发出甲状腺下动脉，易与上动脉混淆"},{"q":"支配睫状肌的神经为","o":["眼神经","视神经","动眼神经","滑车神经","展神经"],"a":2,"e":"睫状肌受动眼神经副交感纤维支配，经睫状神经节换元后由睫状短神经入眼，收缩时晶状体变凸以视近物。眼神经为三叉神经分支，主司眼部感觉；视神经传导视觉；滑车神经支配上斜肌，展神经支配外直肌"},{"q":"右心室","o":["参与心右缘的构成","有三入口一出口","入口周围有二尖瓣","出口周围有三尖瓣","构成心前面的大部分"],"a":4,"e":"右心室位于心前面，构成胸肋面即心前面的大部分。心右缘主要由右心房构成；右心室为一入口一出口，入口为右房室口，周缘附三尖瓣，出口为肺动脉口。二尖瓣位于左心室入口，三尖瓣在右心室入口而非出口"},{"q":"属于下肢带骨的是","o":["股骨","胫骨","跗骨","髋骨","跖骨"],"a":3,"e":"髋骨由髂骨、坐骨和耻骨融合而成，与骶骨共同构成骨盆，属下肢带骨。股骨为大腿游离骨，胫骨为小腿骨，跗骨与跖骨属足骨，均属自由下肢骨而非带骨；上肢带骨则为锁骨与肩胛骨"},{"q":"黄韧带连结的部位是","o":["相邻椎体之间","相邻椎弓根之间","相邻椎弓板之间","相邻横突之间","相邻棘突之间"],"a":2,"e":"黄韧带由弹性纤维构成，连于相邻椎弓板之间，参与构成椎管后壁，前屈时紧张、后伸时松弛。相邻椎体间由椎间盘及前、后纵韧带连结；相邻棘突间为棘间韧带与棘上韧带；相邻横突间为横突间韧带"},{"q":"下列属于颈内动脉直接分支的是","o":["椎动脉","脑膜中动脉","前交通动脉","大脑前动脉","大脑后动脉"],"a":3,"e":"大脑前动脉为颈内动脉终支之一，直接续自颈内动脉，与大脑中动脉同属其直接分支。椎动脉起自锁骨下动脉；脑膜中动脉发自上颌动脉；大脑后动脉来自基底动脉；前交通动脉连接两侧大脑前动脉，非颈内动脉直接发出"},{"q":"肝门静脉的属支不包括下列哪项","o":["胃左静脉","肠系膜上静脉","肠系膜下静脉","脾静脉","肾静脉"],"a":4,"e":"肝门静脉属支主要有肠系膜上静脉、脾静脉、肠系膜下静脉、胃左静脉、胃右静脉及胆囊静脉，收集腹腔不成对脏器的静脉血。肾静脉直接注入下腔静脉，属体循环，不汇入门静脉；胃左、肠系膜上、肠系膜下静脉及脾静脉均为其属支"},{"q":"颈丛位于","o":["颈阔肌浅层","颈阔肌深面","胸锁乳突肌上部深面","胸锁乳突肌下部深面","胸锁乳突肌上部浅层"],"a":2,"e":"颈丛由第1至第4颈神经前支组成，位于胸锁乳突肌上部深面、中斜角肌与肩胛提肌前方。颈阔肌为颈部浅层皮肌，颈丛在其深面而非浅层；胸锁乳突肌下部深面为颈动脉鞘所在区域，并非颈丛位置"},{"q":"全身运动最灵活的关节是","o":["肩关节","肘关节","桡腕关节","髋关节","膝关节"],"a":0,"e":"肩关节由肱骨头与肩胛骨关节盂构成，属球窝关节，头大盂浅、关节囊松弛，可作屈伸、收展、旋内旋外及环转，是全身最灵活的关节。髋关节虽同为球窝关节，但髋臼深、韧带强，稳固有余而灵活性不及；膝、肘、桡腕关节活动范围均较小"},{"q":"关于气管的说法，错误的是","o":["有14～16个气管软骨环","气管杈的位置约平胸骨角平面","位于食管的前方","气管可分为颈、胸、腹三段","气管切开术常在第3～5气管软骨环处进行"],"a":3,"e":"气管仅分颈部和胸部两段，并无腹段，故该项错误。气管由14～16个C形气管软骨环构成，气管杈约平胸骨角平面，位于食管前方；气管切开术常在第3～5气管软骨环处进行"},{"q":"关于腰椎的正确说法是","o":["椎体粗壮，横切面呈三角形","椎孔呈圆形","各棘突的间隙较宽","上关节面是冠状位","上关节面呈水平位"],"a":2,"e":"腰椎棘突宽短、呈板状水平后伸，棘突间隙较宽，临床常在此作腰椎穿刺。腰椎椎体粗壮、横切面呈肾形而非三角形；椎孔呈三角形而非圆形；上关节面为矢状位，冠状位见于胸椎，水平位说法不成立"},{"q":"关于胸廓内动脉的描述，何者正确","o":["发自锁骨下动脉上壁","行程中发出肋间后动脉","发自甲状颈干","发出腹壁上动脉","与腹壁下动脉无吻合"],"a":3,"e":"胸廓内动脉起自锁骨下动脉下壁，沿胸骨外侧下降，末端分为腹壁上动脉与肌膈动脉，腹壁上动脉与腹壁下动脉相吻合。它发出的是肋间前动脉而非肋间后动脉，后者来自主动脉；该动脉亦不起自甲状颈干"},{"q":"关于甲状软骨的描述，错误的是","o":["是喉软骨中最大的软骨","两甲状软骨板前缘相交形成前角","前角上端突出称喉结","上角与杓状软骨形成关节","下角与环状软骨形成关节"],"a":3,"e":"甲状软骨上角与舌骨大角相关节，下角与环状软骨形成环甲关节，与杓状软骨相关节的是环状软骨，故该项错误。甲状软骨为喉软骨中最大者，两侧软骨板前缘相交形成前角，前角上端突出称喉结"},{"q":"下列关于脊髓的说法，错误的是","o":["位于椎管内，成人下端平第3腰椎下缘","全长有两个膨大，即颈膨大和腰骶膨大","全长有31个脊髓节段，连有31对脊神经","人胚早期，脊髓与椎管长度相等","表面无明显的节段性"],"a":0,"e":"成人脊髓下端平第1腰椎下缘，新生儿才平第3腰椎，该项把成人平面说成第3腰椎，属错误。脊髓全长有颈膨大和腰骶膨大两个膨大，31个节段连31对脊神经；人胚早期脊髓与椎管等长，表面无明显节段性"},{"q":"关于网膜囊的描述，正确的是","o":["是仅位于小网膜与腹后壁之间扁窄的腹膜间隙","是仅位于胃与腹后壁之间扁窄的腹膜间隙","为腹膜腔的一部分，又称大腹膜腔","网膜囊以外的腹膜腔称为小腹膜腔","网膜孔是小腹膜腔与大腹膜腔之间的唯一通道"],"a":4,"e":"网膜囊又称小腹膜腔，是位于小网膜和胃后方与腹后壁之间的扁窄间隙，仅经网膜孔与大腹膜腔相通，网膜孔为其唯一通道。网膜囊以外的腹膜腔为大腹膜腔，选项将大、小腹膜腔名称颠倒；仅说位于小网膜或胃与腹后壁之间均不完整"},{"q":"通过内囊膝的纤维束是","o":["皮质脊髓束","皮质核束","脊髓丘脑束","丘脑中央辐射","视辐射"],"a":1,"e":"内囊膝有皮质核束即皮质延髓束通过，支配脑神经运动核。皮质脊髓束、丘脑中央辐射及视辐射、听辐射主要经内囊后肢；脊髓丘脑束为上行感觉束，不经过内囊膝，这是常设的混淆点"},{"q":"股动脉在腹股沟深面的正确位置是","o":["在股神经的外侧","在股神经的内侧","在股静脉的内侧","在股静脉的后侧","在股静脉的前面"],"a":1,"e":"股三角内由外侧向内侧依次为股神经、股动脉、股静脉和淋巴管，故股动脉位于股神经内侧、股静脉外侧。股静脉在股动脉内侧，并非动脉在静脉内侧或后侧；股神经居最外侧，据此可辨明三者的邻里关系"},{"q":"关于结膜的叙述正确的是","o":["无血管","球结膜位于巩膜的后部","睑结膜位于上、下睑内面，与睑板紧密连接","结膜穹窿位于上睑结膜与下睑结膜之间","上睑与下睑闭合时，整个结膜形成的囊状腔隙为结膜穹窿"],"a":2,"e":"睑结膜被覆上、下睑内面，与睑板紧密相贴而不能移动。结膜富含血管；球结膜覆盖巩膜前部而非后部；结膜穹窿为睑结膜与球结膜的移行部，不在上下睑结膜之间；上下睑闭合时结膜形成的囊状腔隙为结膜囊"},{"q":"不属于股骨近端结构的是","o":["股骨颈","股骨头","小转子","大转子","粗线"],"a":4,"e":"股骨近端包括股骨头、股骨颈、大转子和小转子，参与构成髋关节。粗线位于股骨体后面，为肌肉附着的骨嵴，属股骨体结构而非近端，其下端分为内侧髁上线和外侧髁上线"},{"q":"下列对阑尾的描述何者正确","o":["有系膜但不恒定","阑尾动脉通常有两支","常位于右髂窝腹膜外","McBurney点是阑尾根部的体表投影","阑尾静脉注入肠系膜下静脉"],"a":3,"e":"阑尾根部体表投影为McBurney点，即脐与右髂前上棘连线中外三分之一交点，为正确描述。阑尾有恒定的三角形阑尾系膜；阑尾动脉多为回结肠动脉的分支；阑尾属腹膜内位器官，位于右髂窝，其静脉经回结肠静脉汇入肠系膜上静脉"},{"q":"小腿内侧面皮肤由什么神经支配","o":["闭孔神经","胫神经","腓浅神经","腓深神经","隐神经"],"a":4,"e":"隐神经为股神经的分支，伴大隐静脉下行，支配小腿内侧面及足内侧缘皮肤。闭孔神经支配大腿内侧肌群与皮肤；胫神经支配小腿后群肌及足底；腓浅神经支配小腿外侧与足背大部皮肤，腓深神经支配小腿前群肌及第一趾蹼区"},{"q":"颈外动脉的描述中何者有误","o":["起始处行于颈内动脉的前内侧","继经颈内动脉的前方转至外侧","经二腹肌深方入腮腺实质","在下颌颈后方分为上颌动脉及颞浅动脉","起始处的膨大称颈动脉窦"],"a":4,"e":"颈动脉窦为颈内动脉起始处的膨大，属压力感受器，并非颈外动脉结构，故该项错误。颈外动脉起始处行于颈内动脉前内侧，继经其前方转至外侧，经二腹肌深面入腮腺实质，在下颌颈后方分为上颌动脉和颞浅动脉"},{"q":"关于输卵管的描述，正确的是","o":["直接与卵巢相通","壶腹部有伞附着","末端有漏斗","长7～8cm","位于盆腔中央"],"a":2,"e":"输卵管外侧端膨大形成漏斗，漏斗周缘有输卵管伞，为正确描述。输卵管长约10～12cm，位于子宫阔韧带内；伞附着于漏斗而非壶腹部；输卵管不与卵巢直接相通，伞在卵巢表面拾卵；其位置在子宫两侧而非盆腔中央"},{"q":"输尿管与髂血管交叉处是在","o":["输尿管腹段","输尿管盆段","肾盂与输尿管移行处","越过小骨盆入口处","输尿管壁内段"],"a":3,"e":"输尿管在越过小骨盆入口即骨盆上口处跨过髂外动脉前方，形成第二处狭窄，是结石易嵌顿部位。肾盂与输尿管移行处为第一狭窄，位于腹段；壁内段为第三狭窄，二者均非与髂血管交叉处"},{"q":"坐骨棘与髂后下棘之间的是","o":["坐骨大切迹","坐骨结节","髋臼切迹","坐骨小切迹","弓状线"],"a":0,"e":"坐骨大切迹位于髂后下棘与坐骨棘之间，有梨状肌及坐骨神经等通过。坐骨小切迹位于坐骨棘与坐骨结节之间；髋臼切迹为髋臼下部的缺口；弓状线为髂骨内面的骨嵴；坐骨结节为坐骨下端的骨性突起"},{"q":"以下对牵涉性痛的描述错误的是","o":["因某些内脏器官发生病变在体表一定区域产生感觉过敏或痛觉的现象","海德带有助于内脏疾病的定位诊断","牵涉性痛均发生在患病内脏邻近的皮肤区","肝胆疾患时常在右肩部感到疼痛","心绞痛时常在胸前区及左臂内侧皮肤感到疼痛"],"a":2,"e":"牵涉性痛可出现在远离病变内脏的体表区域，如心绞痛放射至左肩臂内侧，并非均局限于邻近皮肤，故该项错误。牵涉性痛是内脏病变在同节段脊髓支配的体表区产生痛觉过敏，海德带有助于定位；肝胆疾患常牵涉右肩部"},{"q":"关于颈外静脉，下列描述中正确的是","o":["属于深静脉","注入颈内静脉","与同名动脉伴行","注入锁骨下静脉或静脉角","起自面静脉"],"a":3,"e":"颈外静脉为颈部最大的浅静脉，由耳后静脉与下颌后静脉后支合成，注入锁骨下静脉或静脉角。它不与颈外动脉伴行，也不注入颈内静脉；面静脉起自内眦静脉，与颈外静脉来源不同"},{"q":"确认输卵管的标志是","o":["输卵管子宫部","输卵管峡","输卵管壶腹","输卵管漏斗","输卵管伞"],"a":4,"e":"输卵管伞为输卵管漏斗周缘的指状突起，术中以此辨认输卵管，是确认该管的可靠标志。输卵管峡短直而管腔窄，为结扎部位；壶腹为受精场所；子宫部穿经子宫壁；漏斗为末端膨大，均非辨认标志"},{"q":"关于肾的描述，正确的是","o":["左、右肾上端等高","出入肾门的结构被纤维囊包绕","右肾比左肾略低半个椎体","第12肋斜过右肾后面的下部","在肾门处肾小盏移行为肾大盏"],"a":2,"e":"受肝的影响，右肾比左肾约低半个椎体，左肾上端平第11胸椎、右肾平第12胸椎。两肾上端并不等高；出入肾门的结构由肾筋膜包绕而非纤维囊；第12肋斜过右肾后面上部；肾小盏汇合成肾大盏在肾窦内进行，不在肾门处"},{"q":"以人体正中矢状面为准的方位术语是","o":["内、外","内侧、外侧","近侧、远侧","深、浅","近端、远端"],"a":1,"e":"内侧与外侧以人体正中矢状面为准，近正中矢状面者为内侧，远离者为外侧。内、外以体腔或空腔脏器为准；近侧、远侧和近端、远端多用于四肢，以靠近躯干附着处为准；深、浅则以体表为准"},{"q":"后丘脑的主要功能是","o":["视、听觉传导路的中继站","痛、温觉传导路的中继站","本体感觉传导路的中继站","内分泌调节","随意运动调节"],"a":0,"e":"后丘脑由内侧膝状体和外侧膝状体组成，分别是听觉与视觉传导路的中继站。痛、温觉中继在丘脑腹后外侧核等核团；本体感觉中继亦在腹后核群；内分泌调节主要由下丘脑负责；随意运动调节与纹状体、小脑及运动皮质有关"},{"q":"关于上腔静脉，下列描述中正确的是","o":["由左、右头臂静脉汇合而成","注入左心房","在入心之前接受无名静脉注入","沿升主动脉前面垂直下行","收集胸腔内心脏的静脉血"],"a":0,"e":"上腔静脉由左、右头臂静脉在右侧第一胸肋结合处后方汇合而成，注入右心房。它位于升主动脉右侧而非前面；心脏本身的静脉血经冠状窦回流，不汇入上腔静脉；头臂静脉即无名静脉，是合成它的血管，并非入心前才接受"},{"q":"与颈内静脉伴行的血管是","o":["颈外静脉","上颌静脉","颈外动脉","下颌后静脉","颈总动脉"],"a":4,"e":"颈内静脉与颈总动脉及颈内动脉共同包于颈动脉鞘内伴行，收纳头颈部静脉血。颈外静脉为浅静脉，不与动脉伴行；上颌静脉与下颌后静脉位于腮腺区，不与颈内静脉伴行；颈外动脉亦无此紧密伴行关系"},{"q":"在脑桥基底部和小脑中脚交界处连接的神经为","o":["三叉神经","展神经","面神经","动眼神经","滑车神经"],"a":0,"e":"三叉神经根自脑桥基底部与小脑中脚交界处出脑，粗大，含一般躯体感觉和特殊内脏运动纤维。展神经起自延髓脑桥沟；面神经亦起自该沟、位于展神经外侧；动眼神经起自中脑脚间窝；滑车神经于中脑下丘下方出脑"},{"q":"关于小腿肌前群的描述，正确的是","o":["包括胫骨前肌、趾长伸肌和腓骨长肌","趾长伸肌位于胫骨前肌和拇长伸肌之间","均能屈距小腿关节","胫骨前肌还能使足外翻","均能使足背屈"],"a":4,"e":"小腿肌前群包括胫骨前肌、趾长伸肌、拇长伸肌和第三腓骨肌，均作用于踝关节使其背屈。腓骨长肌属外侧群而非前群；拇长伸肌位于胫骨前肌与趾长伸肌之间；胫骨前肌使足内翻而非外翻；前群屈踝的说法与背屈作用相反"},{"q":"躯干和四肢意识性本体感觉传导通路的第1级神经元是","o":["脊神经节","三叉神经节","脊髓后角细胞","薄束核和楔束核","三叉神经脊束核"],"a":0,"e":"躯干和四肢意识性本体感觉传导路第1级神经元为脊神经节细胞，其轴突组成薄束和楔束上行。薄束核与楔束核为第2级神经元；脊髓后角细胞是脊髓丘脑束的第2级神经元；三叉神经节与三叉神经脊束核属头面部感觉传导路，不参与躯干四肢本体感觉"}];
